Ceviri.ekle("hy","olay",{
"OLAYLAR_EK17:1606-10-11:0":{"b": ["Սեդեֆքյար Մեհմեդ աղան նշանակվեց գլխավոր ճարտարապետ. Սուլթանահմեդ մզկիթի ճարտարապետը", "27b66fce"], "d": ["Ալբանիայի Էլբասան ավանից 1562-63 թվականներին դևշիրմեով պալատ վերցված Մեհմեդ աղան, կրթվելով ճարտարապետ Սինանի մոտ, 1606 թ. հոկտեմբերի 11-ին նշանակվեց օսմանյան գլխավոր ճարտարապետ։ TDV İslâm Ansiklopedisi-ն հաղորդում է, որ ժամանակակից մի աղբյուր նրան նկարագրում է որպես «մեղմաբարո, համեստ, խոսքի տեր, բարեպաշտ և խելացի»։ Երեք տարի անց Ահմեդ I-ի հրամանով Սուլթանահմեդ մզկիթի շինարարությանը ձեռնամուխ եղած Մեհմեդ աղան իր ստորագրությունը դրեց լայն ժառանգության տակ՝ Քաաբայի վերանորոգումներից մինչև Ստամբուլի և Էդիրնեի բազմաթիվ աղբյուրներ ու մզկիթներ։ Այն, որ վեց մինարեթը Մեքքայի Քաաբայի հետ «հավասարության» վեճի տեղիք է տվել, տարածված ժողովրդական պատում է. հանրագիտարանային աղբյուրները դա չեն հաստատում, լուծումը բնութագրում են միայն որպես «մինչ այդ չփորձված»։", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["Նոր փադիշահ Մուստաֆա I. գահին՝ գունատ դեմքով, մտացիր հայացքով «վանդակի» կալանավորը", "c487b0d1"], "d": ["Ահմեդ I-ի մահով գահ բարձրացած Մուստաֆա I-ը, լինելով եղբոր ողջ թողած առաջին շահզադեն, տարիներ շարունակ խիստ հսկողության տակ փակված էր ապրել պալատում. TDV İslâm Ansiklopedisi-ն նրան նկարագրում է որպես «գունատ դեմքով, նոսր մորուքով, խոշոր սև աչքերով, սառած հայացքով» և արձանագրում, որ երկարատև այս բանտարկությունը ծանրացրել էր նրա հոգեկան վիճակը։ Իննսունվեց օր տևած այս առաջին թագավորության ընթացքում նա չկարողացավ վարել պետական գործերը. փոխարենը, ըստ ավանդության, հաճախ որսի էր գնում, շրջում նավաշինարանում, անգամ ոսկի էր նետում ջուրը և դիտում ձկներին։ Ենիչերիները, օջախը և ուլեման, նրան թագավորելու անպիտան համարելով, 1618 թ. փետրվարի 26-ին գահընկեց արին և նրա փոխարեն բազմեցրին տասնչորսամյա եղբորորդուն՝ Օսման II-ին։", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["Էվլիյա Չելեբիի ճամփորդության երազը. «շեֆաաթ» ասելու փոխարեն «սեյահաթ» ասելը", "2d863e22"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի՝ Էվլիյա Չելեբին իր քառասուն տարի տևելիք ճամփորդական կյանքի սկիզբը կապում է հիջ. 1040 թ. Մուհառամի աշուրայի գիշերը (1630 թ. օգոստոսի 19) տեսած երազի հետ. երազում Ստամբուլի Ահի Չելեբի մզկիթում բազմամարդ համայնքի հետ տեսնում է Մարգարեին և հուզմունքից «շեֆաաթ, ո՛վ Աստծո առաքյալ» (բարեխոսություն) ասելու փոխարեն ասում է «սեյահաթ, ո՛վ Աստծո առաքյալ» (ճամփորդություն)։ Ըստ ավանդության՝ Մարգարեն, ժպտալով այս լեզվի սայթաքմանը, նրան ավետում է և՛ բարեխոսություն, և՛ ճամփորդություն, և՛ ուխտագնացություն։ Նա երբեք չամուսնացավ և կյանքը նվիրեց «ճամփորդության» այս խոստմանը։", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["Մուրադ IV-ի հակասությունները. խմիչքի սիրահար փադիշահի խմիչքի արգելքը, ըմբիշի դաստակ, կոմպոզիտորի ականջ", "3d2ea5e0"], "d": ["Տասնմեկ տարեկանում գահ բարձրացած Մուրադ IV-ի առաջին տարիներին վճռորոշ էր նրա մոր՝ Քյոսեմ սուլթանի ազդեցությունը. TDV İslâm Ansiklopedisi-ն հաղորդում է, որ Քյոսեմը, զգուշանալով որդու՝ իշխանության հակումից, նրան «մղում էր զվարճանքի, զբաղեցնում էր նվերներով և տոնախմբություններով»։ Երբ մոտ քսան տարեկանում նա փաստացի իր ձեռքն առավ կառավարումը, բարձրահասակ, լայնաթիկունք, վեհաշուք տիրակալ էր. ըստ ավանդության՝ մի ուժեղ մարդու գոտուց բռնելով բարձրացրել և Հաս Օդայում մի քանի անգամ ման է ածել։ TDV-ի արձանագրած ապշեցուցիչ հակասությունը սա է. ասվում է, որ փադիշահը ատում էր ծխախոտն ու ափիոնը, բայց չափից ավելի հակված էր խմիչքի. չնայած դրան, արշավանքից առաջ արգելեց սուրճը, ծխախոտը, ապա և խմիչքը. միաժամանակ նա երաժշտական գիտելիք ուներ այնքան, որ կարող էր մակամի ավանդույթին համապատասխան երաժշտություն հորինել։", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["Լագարի Հասան Չելեբիի թռիչքը հրթիռով. ավանդություն, որի միակ աղբյուրը Էվլիյա Չելեբին է", "1f02e3f2"], "d": ["Ըստ Էվլիյա Չելեբիի «Սեյահաթնամե»-ի՝ Լագարի Հասան Չելեբին Մուրադ IV-ի ներկայությամբ Սարայբուրնուում հիսուն օքա վառոդով պատրաստեց յոթթևանի հրթիռային սարք և ասելով՝ «Փադիշա՛հ իմ, քեզ Աստծուն եմ հանձնում, գնում եմ Հիսուս մարգարեի հետ զրուցելու», նստեց հրթիռին։ Ըստ ավանդության՝ մոտ 250 մետր բարձրացած Հասան Չելեբին բազեի թևերի նման սարքերով սահելով իջավ ծով, լողալով վերադարձավ փադիշահի մոտ և փոխարենը ստացավ յոթանասուն ակչե օրավարձով սիպահիության պաշտոն։", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["Քեմանքեշ Կարա Մուստաֆա փաշան դարձավ մեծ վեզիր. սկսվեց ֆինանսական բարեփոխումների շրջանը", "583846a4"], "d": ["Բաղդադի արշավանքում Թայյար Մեհմեդ փաշայի նահատակությունից հետո հիջ. 1048 թ. Շաաբան ամսի 17-ին (1638 թ. դեկտեմբերի 24) մեծ վեզիր դարձած Քեմանքեշ Կարա Մուստաֆա փաշան սուլթան Իբրահիմի օրոք կիրառեց խիստ ֆինանսական կարգապահություն. ենիչերիների և սիպահիների թիվը իջեցրեց մեկ երրորդի, բարելավեց դրամի հարգը, խստացրեց նարխի համակարգը։ TDV-ի բերած թվով՝ այս խնայողությունը տարեկան հասավ 6000 քսակի. բայց այս խիստ վերահսկողությունը նրան թշնամիներ վաստակեց պալատական շրջանակներում։", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["Մուստաֆա I-ը մահացավ տասնհինգամյա մոռացությունից հետո", "b4c872cd"], "d": ["1623 թ. սեպտեմբերի 10-ին երկրորդ անգամ գահընկեց արված Մուստաֆա I-ը մինչև մահը անցած տասնհինգ տարիներն ապրեց մի սենյակում, ուր նրան փակ էին պահում. աղբյուրներում այդ տարիների մասին ոչ մի տեղեկություն չկա։ Նա մահացավ հիջ. 1048 թ. Ռամադան ամսի 15-ին (1639 թ. հունվարի 20). աղբյուրների մի մասը դա համարում է բնական մահ, իսկ մի մասը պնդում է, որ դրանում Մուրադ IV-ի ձեռքը կա։", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["«Խելագար Իբրահի՞մ», թե՞ ալիքաձև ընթացող հիվանդություն", "2abc230f"], "d": ["TDV İslâm Ansiklopedisi-ն բացահայտ մերժում է 20-րդ դարում տարածված «Խելագար Իբրահիմ» մակդիրը. հաղորդում է, որ փադիշահն իր իսկ նամակներում գանգատվում է ցավերից, ախորժակի կորստից, ոտքերի թուլությունից, գլխում մշուշի զգացումից, կրծքի սեղմումից և ուշագնացության նոպաներից։ Մինչդեռ գահազրկման ընթացքում նրա հետևողական և ողջամիտ պատասխանները հակասում են մշտական անհավասարակշռության պնդմանը. հոդվածը եզրակացնում է, որ նրա վիճակը «կայուն չէր, այլ փոփոխական սրությամբ» էր ընթանում։ Այդ շրջանում Քյոսեմ սուլթանի պատասխանատվությունները գնալով մեծացան, իսկ պալատ կանչված Ջինջի խոջայի՝ «ազդեցիկ աղոթքներով» փադիշահին հոգևոր մխիթարություն մատուցելը ուժեղացրեց նրա՝ քաղաքականությանը միջամտելու կարողությունը։", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["Սամուրի դեպքը. մեծ վեզիր Ահմեդ փաշայի մորթու հարկը նախապատրաստեց Իբրահիմի վախճանը", "a2a47d62"], "d": ["Մինչ պալատում սուլթան Իբրահիմի սամուրե մուշտակի և սաթի հանդեպ կիրքը գնալով աճում էր, մեծ վեզիր Ահմեդ փաշան մոտ 1647-1648 թվականներին ներմուծեց մի կիրառություն, որով պետական այրերից բռնի հավաքվում էր սամուրե մուշտակի գինը. TDV İslâm Ansiklopedisi-ն արձանագրում է, որ պաշտոնյաները դա դիտում էին որպես բացահայտ «խարաջ»։ Երբ ենիչերիական սպաները միասնաբար մերժեցին վճարել, այս դիմադրությունը դարձավ փադիշահի գահընկեցության հանգեցրած ընթացքի անմիջական կայծը. 1648 թ. օգոստոսի 7-ի առավոտյան հավաքված պաշտոնյաները նախ սպանեցին Ահմեդ փաշային, հաջորդ օրը գահընկեց արին Իբրահիմին։", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["«Պետությունը կանայք են կառավարում». Վարվար Ալի փաշայի ապստամբությունը Սեբաստիայից", "5b027357"], "d": ["Սեբաստիայի բեյլերբեյ Վարվար Ալի փաշան, ասելով՝ «Սեբաստիայի տարեկան եկամուտը այս գումարը չի ծածկում», հրաժարվեց վճարել Ստամբուլի՝ «բայրամիյե» անունով պահանջած 30.000 ղուրուշը. ըստ TDV İslâm Ansiklopedisi-ի՝ նրա ապստամբության հիմնավորումն այն պնդումն էր, որ փադիշահի հիվանդության պատճառով պետական գործերն անցել են կանանց ձեռքը, և դա կուսակալների հաճախակի փոփոխություններով անկայունություն է ծնում։ 1648 թ. մայիսին թեև սկզբում ռազմական հաջողություն ունեցավ, պարտվեց Իփշիր Մուստաֆա փաշային, 1648 թ. մայիսի 20-ին մահապատժի ենթարկվեց, և նրա գլուխն ուղարկվեց Ստամբուլ։", "e45166db"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["Վենետիկին կորցրած Նաֆպլիոնը. Մորեայի պատերազմի շրջադարձային կետը", "9d400557"], "d": ["TDV-ի «Անաբոլու» հոդվածի համաձայն՝ պաշարման ընթացքում քաղաքի մուսուլման բնակչությունից ողջ մնացածները փախան շրջակա կղզիներ և Անատոլիա (1686)։ Ընդունված ակադեմիական աղբյուրի համաձայն (Setton, Venice, Austria, and the Turks in the Seventeenth Century)՝ Քյոնիգսմարկի ուժերը երկու շաբաթ ետ մղեցին օսմանյան օգնական բանակի հարձակումները. երբ օգոստոսի 29-ին Իսմայիլ փաշայի գրոհն ավարտվեց ծանր պարտությամբ, բերդը մի քանի օրում հանձնվեց։ Նաֆպլիոնը 1540 թ. պայմանագրով ստացված օսմանյան հող էր. նրա կորստով արագացավ Մորեայի թերակղզու անցումը Վենետիկին։", "592908a0"]},
"OLAYLAR_EK17:1687-08-01:0":{"b": ["Մեհմեդ IV-ը հրաժարվեց որսից. վերջին ջանքը գահազրկման նախօրեին", "7daa904b"], "d": ["Մոհաչի պարտությունից (1687 թ. օգոստոս) հետո ռոճիկ չստացած բանակը ապստամբեց և շարժվեց Ստամբուլի վրա։ Մեհմեդ IV-ը մահապատժի ենթարկել տվեց մեծ վեզիրի կնիքը տարած Սուլեյման փաշային, նրա գլուխը ցույց տվեց զորքին և, որսի պարագաներն ու բարակները ցրելով, հայտարարեց, թե ապաշխարում է. բայց այդ քայլը բավական չեղավ գահը փրկելու համար, և մի քանի ամիս անց նրան գահազրկեցին։", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["Մունկաչի (Մուկաչևո) բերդի հանձնումը Ավստրիային եռամյա պաշարումից հետո", "ca2efc3d"], "d": ["1685 թ. վերջին կայսերական ուժերի կողմից պաշարված Մունկաչի բերդը Թյոքյոլի Իմրեի կնոջ՝ Իլոնա Զրինիի ղեկավարությամբ երեք տարի դիմադրեց. ըստ բազմաթիվ հրատարակված տեղեկատու աշխատությունների՝ բերդը 1688 թ. հունվարի 17-ին հանձնվեց գեներալ Անտոնիո Կարաֆային։ Սա օսմանա-հաբսբուրգյան ճակատում Հունգարիայում օսմանամետ դիմադրության վերջին խոշոր բերդերից մեկի անկումն էր։", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["Բալթաջի Մեհմեդ փաշայի և Եկատերինա թագուհու ավանդությունը", "c1b739f1"], "d": ["Դարեր շարունակ կրկնվել է ժողովրդական այն պատումը, որը Պրուտում պաշարված ռուսական բանակի փրկությունը կապում է Եկատերինա I-ի՝ Բալթաջի Մեհմեդ փաշային ուղարկած նվերների/կաշառքի հետ։", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["Վեճը Պրուտում «բաց թողնված հնարավորության» մասին. երկու տեսակետ", "61ee699c"], "d": ["Այն, որ օսմանյան բանակը, ռուսական բանակը լիովին շրջապատած լինելով, բավարարվեց խաղաղությամբ, պայմանագրից անմիջապես հետո դարձավ պատմաբանների վեճի առարկա. TDV-ի իսկ ձևակերպմամբ՝ «հասկացվել է, որ մեծ հնարավորություն է բաց թողնվել, և այս թեզը հակառակ կարծիքի տեր անձինք ինտենսիվ մշակել են»։ Ըստ քննադատողների՝ ցարը կարող էր գերվել, ռուսական բանակի զենքերը՝ հանձնվել. իսկ պաշտպանողների կարծիքով՝ Հյուսիսային Եվրոպայում Շվեդիայի հզորացումը կանխելու համար Ռուսաստանը սահմանափակ ձևով թուլացնելը ավելի «խելացի քաղաքականություն» էր։ TDV-ն փոխանցում է երկու տեսակետն էլ՝ կողմ չբռնելով։", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["Հիմնվեց երեսուներկու հոգանոց գիտական/թարգմանչական հանձնախումբ", "0e3a713c"], "d": ["Դամադ Իբրահիմ փաշայի մեծ վեզիրության օրոք Ստամբուլում հիմնվեց երեսուներկու հոգանոց գիտնական-գրագիրների հանձնախումբ, որը, TDV-ի ձևակերպմամբ, «կարող է համարվել ժամանակի ակադեմիան»։ Հանձնախումբը արաբերենից, պարսկերենից, հունարենից և լատիներենից թուրքերեն թարգմանեց պատմության, փիլիսոփայության և աշխարհագրության երկեր. դրանց թվում էին Յանյայից Էսադ էֆենդիի՝ քսանհինգ հոգանոց խմբով Արիստոտելի «Ֆիզիկա»-ն թարգմանելը և բանաստեղծ Նեդիմի՝ պատմական թարգմանության հանձնախմբի նախագահությունը։ Օրը TDV-ում նշված չէ, հայտարարված է տարին։", "69ac19ac"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["Մահմուդ I-ը Փաթրոնա Հալիլին պալատ հրավիրելով ծուղակը գցեց", "6147059f"], "d": ["Գահ բարձրանալուց յոթ շաբաթ անց Մահմուդ I-ը իր վստահելի մարդկանց՝ պալատում Հաջի Բեշիր աղայի, դրսում Ղրիմի խան Կապլան Գիրեյ I-ի միջոցով զինվորական առաջնորդներին իր կողմը քաշեց և կոտրեց Փաթրոնա Հալիլի ազդեցությունը։ 1730 թ. նոյեմբերի 25-ին Թոփքափը պալատի Թլփատության սենյակում տեղի ունեցող ժողովի կանչված Փաթրոնա Հալիլին, Մուսլու Բեշեին և Քել Մեհմեդ աղային ներս ընդունեցին. մեծ վեզիր Սիլահդար Մեհմեդ փաշայի նշանով նախօրոք թաքցված երեսուներկու զինված մարդ դուրս եկավ և սպանեց երեքին էլ։ Այսպիսով Մահմուդ I-ը ապստամբության վերահսկողությունը լիովին վերցրեց իր ձեռքը։", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["Հումբարաջի Ահմեդ փաշան (Բոնվալ) նշանակվեց Հումբարաջիների օջախի ղեկավար", "27b0b1d7"], "d": ["Իսկական անունով Կլոդ-Ալեքսանդր կոմս դը Բոնվալ ֆրանսիացի սպան, նախ ծառայելով ֆրանսիական և ավստրիական բանակներում, Սարաևոյում ընդունեց իսլամը, վերցրեց Ահմեդ անունը և 1729 թ. ապաստանեց Օսմանյան պետությունում։ Մահմուդ I-ի օրոք 1731 թ. Հումբարաջիների օջախի ղեկավար նշանակված Ահմեդ փաշան Ուսկյուդարի Այազմայում հիմնել տված զորանոցում վարժեցրեց Բոսնիայից բերված մոտ 300 զինվորի. նրանց թիվը կարճ ժամանակում անցավ 600-ը, և նա ինքը նաև մաթեմատիկայի դասեր էր տալիս։ Ֆրանսիայի օգտին Ռակոցիի հետ Հունգարիայում ձեռնարկած ապստամբության փորձը խարխլեց նրա ազդեցությունը, և 1738 թ. նա աքսորվեց Կաստամոնու։ 1747 թ. մայիսի 23-ին մահացավ Ստամբուլում. գերեզմանը Ղալաթա Մևլևիների վանքի գերեզմանոցում է։", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["Սմեդերևոյի վերագրավումը Հաբսբուրգների (Հունգարիայի թագավորության թագի) ձեռքից. 1737-39 թթ. պատերազմը", "63dcf604"], "d": ["TDV-ի «Սմեդերևո» հոդվածի համաձայն՝ 1717 թ. Պոժարևացով Ավստրիային թողնված բերդը հետ վերցվեց 1737 թ. սկսված օսմանա-ավստրիական պատերազմի Դանուբ-Սավա ճակատում օսմանյան առաջխաղացմամբ. Հաբսբուրգյան (Հունգարիայի թագավորության թագի) ուժերը շրջանում կարողացան դիմանալ մինչև 1738 թ. օգոստոս, այս ամսաթվից հետո Սմեդերևոն կրկին անցավ օսմանյան կառավարման։ Մեկ տարի անց ստորագրված Բելգրադի պայմանագիրը (1739-09-18) ամրագրելու էր այս ձեռքբերումը՝ Բելգրադի և հյուսիսային Սերբիայի հետ միասին։", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["Մորավայի հովտի վերադարձը օսմանյան կառավարման. Յագոդինա, Կրագուևաց և Չաչակ", "b219d3c9"], "d": ["1738 թ. օգոստոսին Սմեդերևոն հետ վերցնելով՝ Սմեդերևոյի և օսմանյան հիմնական մարմնի միջև մնացած Մորավայի հովիտն էլ վերադարձավ օսմանյան կառավարման. Յագոդինան, Կրագուևացը և Չաչակը այս ամսաթվից համարվում են օսմանյան։ Աղբյուրները այս երեք վայրերի վերադարձը առանձին ամսաթվով չեն հիշատակում. քարտեզը գործում է Սմեդերևոյի օրով։ Բելգրադի պայմանագիրը (1739-09-18) ամրագրեց այս վիճակը։", "4b38fa55"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["Աբդուլհամիդ I-ը Օչակովի անկման լուրը կարդալիս կաթված ստացավ և մահացավ", "6ac60365"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի abdulhamid-i հոդվածի՝ ռուս-ավստրիական պատերազմի ծանր ընթացքից առողջությունը լիովին խաթարված Աբդուլհամիդ I-ը, Օչակովի բերդի՝ ռուսների կողմից գրավման մասին մեծ վեզիրի զեկուցագիրը կարդալիս, հանկարծակի կաթվածից մահացավ (հիջ. 1203 թ. Ռաջաբ ամսի 11 / 1789 թ. ապրիլի 7)։ Նրա դիակը թաղվեց Ստամբուլի Բահչեքափըում իր իսկ կառուցել տված դամբարանում։ Նույն օրը գահ բարձրացավ նրա եղբորորդի Սելիմ III-ը։", "e0b9fc27"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["Օսմանա-ռուսական պաշտպանական դաշինք. համատեղ պաշտպանություն Ֆրանսիայի դեմ", "c87079d1"], "d": ["Նապոլեոնի կողմից Եգիպտոսի գրավումից հետո Սելիմ III-ը և ռուս ցար Պավել I-ը կնքեցին տասնչորս հոդվածից կազմված, ութ տարի ժամկետով պաշտպանական դաշինք։ Կողմերը պարտավորվեցին ունենալ ընդհանուր բարեկամ և թշնամի, միմյանց օգնել և առանձին խաղաղություն չկնքել։", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["Օսմանյան պետության և Երկու Սիցիլիաների (Նեապոլի) պաշտպանական դաշինքը. ընդհանուր գործ Ֆրանսիայի դեմ", "1d2be816"], "d": ["Ֆրանսիայի՝ Իտալիան, Մալթան և Եգիպտոսը գրավելու պայմաններում Օսմանյան պետությունը և Երկու Սիցիլիաների թագավորությունը կնքեցին ինը հոդվածից կազմված պաշտպանական դաշինք։ Կողմերը պարտավորվեցին համատեղ պատերազմել, առանձին խաղաղություն չկնքել և միմյանց ցամաքային ու ծովային օգնություն ցույց տալ։", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["Հիմնվեց Յոթ կղզիների հանրապետությունը. Հոնիական կղզիները ռուս-օսմանյան հովանու ներքո", "08839694"], "d": ["1799 թ. ռուս-օսմանյան միացյալ նավատորմը ֆրանսիացիներին դուրս էր մղել Հոնիական կղզիներից (Կորֆուի բերդն ընկավ 1799 թ. մարտի 5-ին). 1800 թ. մարտի 21-ի տասներկու հոդվածից կազմված պայմանագրով կղզիները հիմնվեցին որպես ներքին գործերում ինքնավար, արտաքին գործերում Օսմանյան պետությանը կապված «Cezâyir-i Seb'a-i Müctemia Cumhuru» (Յոթ կղզիների հանրապետություն)։ 1799-03-05-ից մինչև այս օրը համատեղ օկուպացիայի շրջանն է։", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["Թիլզիտ. Յոթ կղզիների հանրապետության նկատմամբ ռուսական իրավունքները փոխանցվեցին Ֆրանսիային", "98a78beb"], "d": ["Թիլզիտում Ռուսաստանի և Ֆրանսիայի միջև ձեռք բերված համաձայնությամբ Ռուսաստանը Յոթ կղզիների նկատմամբ իր իրավունքները թողեց Ֆրանսիային. 1807 թ. ամռանը ֆրանսիական զորքերը հաստատվեցին կղզիներում, և Յոթ կղզիների հանրապետությունը վերացավ։", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["Լեֆկադայի և Հոնիական կղզիների անցումը անգլիական հովանու ներքո. նապոլեոնյան դարաշրջանից հետո ստեղծված կարգը", "0af821dc"], "d": ["1797 թ. Ֆրանսիային անցած Լեֆկադան և Հոնիական մյուս կղզիները, Նապոլեոնի վերջնական պարտությունից հետո, 1815 թ. նոյեմբերի 5-ին Փարիզում Անգլիայի, Ռուսաստանի, Ավստրիայի և Պրուսիայի միջև ստորագրված հատուկ պայմանագրով «Յոթ կղզիների միացյալ նահանգներ» անունով թողնվեցին անգլիական հովանու ներքո. սա առանձին փաստաթուղթ է 1815 թ. նոյեմբերի 20-ի Փարիզի ընդհանուր պայմանագրից։ Հովանավորությունը տևելու էր մինչև 1864 թ., ապա կղզիները հանձնվելու էին Հունաստանին։", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["Պրիզրենի գրավումը. օսմանյան սանջակի կենտրոն Կոսովոյում", "f84c220f"], "d": ["Հիջ. 859 թ. Ռաջաբ ամսի 4-ին (1455 թ. հունիսի 20) Ֆաթիհ սուլթան Մեհմեդի հրամանատարությամբ օսմանյան բանակը սերբ դեսպոտ Ջուրաջ Բրանկովիչի (օսմանյան աղբյուրներում՝ Վըլքօղլու) հետ կռվից հետո գրավեց Պրիզրենը։ Քաղաքը 13-րդ դարի կեսին Բյուզանդիայից անցել էր Սերբական թագավորությանը և թագավոր Միլուտինի, ցար Դուշանի ու թագավոր Ուրոշի օրոք եղել էր արքայական նստավայր. Դուշանի մահից հետո նրա նշանակությունը նվազել էր։ Գրավումից հետո այն դարձվեց սանջակի կենտրոն և մինչև 1912 թ.՝ չորսուկես դար, պահպանեց այդ կարգավիճակը։ Պրիզրենը, մինչև Հարավսլավիայի մասնատումը, Բալկաններում միակ քաղաքն էր, ուր միաժամանակ խոսում էին երեք լեզվով՝ ալբաներեն, թուրքերեն և սերբերեն։", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["Բաստիլի անկումը. Ֆրանսիական հեղափոխության սկիզբը", "96e931f1"], "d": ["Թագավոր Լյուդովիկոս XVI-ի՝ ֆինանսների նախարար Նեկկերին պաշտոնանկ անելու (1789 թ. հուլիսի 11) առաջացրած զայրույթի և տնտեսական ճգնաժամի պայմաններում Փարիզի բնակչությունը, զենք և վառոդ պահանջելով, շարժվեց Բաստիլի բերդի վրա։ Կեսօրից հետո սկսված բախման ժամանակ ավելի քան երեք հազար ապստամբների դեմ ընդամենը մոտ հարյուր պահակ ունեցող բերդը ժամը 17:00-ի սահմաններում հանձնվեց. սպանվեցին մի քանի պաշտոնյաներ, այդ թվում բերդի հրամանատար Բեռնար-Ռենե դը Լոնեն, ազատ արձակվեց յոթ կալանավոր։ Գրեթե դատարկ և արդեն քանդվելու նախատեսված բերդը թագավորական բռնակալության խորհրդանիշ էր. նրա անկման մասին Լյուդովիկոս XVI-ին զեկուցեցին. «Ո՛չ, տե՛ր, սա ապստամբություն չէ, այլ հեղափոխություն»։ Հուլիսի 14-ն այսօր Ֆրանսիայի ազգային տոնն է, և իրադարձությունը համարվում է կարճ ժամանակում ողջ երկրում տարածված ժողովրդական շարժման և Ֆրանսիական հեղափոխության (1789-1799) խորհրդանշական սկիզբը. հեղափոխությունը հաջորդ տասնամյակում, տապալելով բացարձակ միապետությունը, հիմնովին փոխելու էր Եվրոպայի քաղաքական քարտեզը և Օսմանյան պետությունն էլ ներառող միջազգային հավասարակշռությունները։", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["Մամլուքյան բանակը մտավ Մալաթիա. քաղաքը իլխանական կառավարումից անցավ մամլուքյան կառավարման", "2540363d"], "d": ["Մամլուքները Դամասկոսի նաիբ Սեյֆեդդին Թենգիզի հրամանատարությամբ բանակ ուղարկեցին Մալաթիայի վրա. բանակը հիջ. 715 թ. Մուհառամ ամսի 22-ին (1315 թ. ապրիլի 28) մտավ քաղաք։ Մալաթիան մինչ այդ իլխանական տիրապետության տակ էր և Եփրատից արևմուտք իլխանական ու մամլուքյան ազդեցության գոտիների հպման գծի առանցքային կետն էր։ Քաղաքի ձեռքից ձեռք անցնելը ցույց է տալիս երկու պետությունների երկարատև մրցակցության մեջ մամլուքների առաջխաղացումը դեպի Վերին Եփրատ։ Այս ամսաթվից հետո Մալաթիան որոշ ժամանակ մտնելու էր Էրեթնաօղուլների կառավարման ներքո, իսկ 1338 թվականից կրկին վերադառնալու էր մամլուքյան տիրապետության։", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["Էշրեֆօղուլների բեյության վերջը. Բեյշեհիրն ու Սեյդիշեհիրը անցան Համիդօղուլներին", "e4e70846"], "d": ["Իլխանության Անատոլիայի ընդհանուր կուսակալ էմիր Չոբանի որդի Դեմիրթաշը գործի անցավ անկախություն հռչակած թուրքմենական բեյությունների դեմ և, մտնելով Բեյշեհիր, սպանել տվեց Էշրեֆօղլու Սուլեյման շահին, որը ժամանակին իրենից գանգատվել էր (1326 թ. հոկտեմբերի 9)։ Այսպիսով ավարտվեց 13-րդ դարի վերջին Բեյշեհիր-Սեյդիշեհիրի շրջանում հիմնված Էշրեֆօղուլների բեյությունը։ TDV-ի «Համիդօղուլներ» հոդվածը շարունակությունն է տալիս. Դեմիրթաշի վերացրած Էշրեֆօղուլներին պատկանած Բեյշեհիրը, Սեյդիշեհիրը, Աքշեհիրը և Դողանհիսարը միացան Համիդի բեյության սահմաններին։ Նույն տարում Համիդօղլու Դյունդար բեյն էլ հանձնվեց Դեմիրթաշին և սպանվեց։ Այս հողերը 1381 թ. 80.000 ոսկով վաճառվելու էին Մուրադ I-ին և անցնելու էին օսմանյան կառավարման։", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["Մալաթիան կրկին անցավ մամլուքյան տիրապետության տակ. Էրեթնաօղուլների կառավարման վերջը", "08b80aa2"], "d": ["1315 թ. մամլուքյան կառավարման անցած Մալաթիան Իլխանության քայքայման տարիներին որոշ ժամանակ անցել էր Էրեթնաօղուլների ձեռքը։ TDV-ի «Մալաթիա» հոդվածը վերադարձը մեկ նախադասությամբ է տալիս. 1338 թվականից քաղաքում կրկին իշխեցին մամլուքները։ Սա Անատոլիայի հարավ-արևելքում Իլխանությունից հետո առաջացած դատարկությունը մամլուքների և Էրեթնայի միջև բաժանվելու տարիների մի կտրվածք է։", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["Իզմիրի նավահանգստի կորուստը խաչակրաց նավատորմին. Այդընօղուլների ծովային ուժը կոտրվեց", "775c65fe"], "d": ["Հռոմի պապ Կղեմես VI-ի խրախուսմամբ Վենետիկի, Ջենովայի, Կիպրոսի թագավորության, Հռոդոսի ասպետների և Նաքսոսի դուքսի նավերից կազմված խաչակրաց նավատորմը Իզմիրի նավահանգիստը խլեց Այդընօղուլների ձեռքից (1344 թ. հոկտեմբերի 28)։ Նավահանգիստը Ումուր բեյի հայր Մեհմեդ բեյը 1328-1329 թվականներին վերցրել էր ջենովացի Մարտինո Ձակկարիայից, և այն Էգեյան ծովում Այդընօղուլների ծովային ուժի հենակետն էր։ 1334 թ. սեպտեմբերին նույն նպատակով եկած խաչակրաց նավատորմը ստիպված էր եղել նահանջել. այս երկրորդ արշավանքը հաջողվեց։ Ումուր բեյը շարունակեց դիմադրությունը և, միավորվելով թուրքական մյուս բեյությունների հետ, 1345 թ. հունվարի 17-ին հաղթեց խաչակրաց նավատորմին, բայց նավահանգիստը հետ վերցնել չհաջողվեց։", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["Կարամանօղլու Ալաեդդին բեյը Կոնիան, Ակսարայը և Նիղդեն միացրեց Կարամանի հողերին", "2b8b0f70"], "d": ["Ցանկանալով օգտվել Մամլուքների սուլթանության կողմից Հայկական թագավորությանը վերջ դնելով ողջ Չուքուրովան իր հողերին միացնելուց և Կենտրոնական Անատոլիայի Էրեթնայի պետությունում ծագած խառնակություններից՝ Կարամանօղլու Ալաեդդին բեյը Կարամանյան հողերին միացրեց նախ Կոնիան (1366-1367), ապա Նիղդեի Կարահիսարը (Եշիլհիսար), Ակսարայը, Աքշեհիրը, Իլգընը, Իշաքլըն և Կեսարիան։ Կոնիան, որպես սելջուկյան մայրաքաղաք իր ունեցած կշռի պատճառով, Կարամանօղուլների համար ոչ միայն քաղաք էր, այլև օրինականության հավակնություն։", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["Ուզուն Հասանը վերջ դրեց Կարա Կոյունլուների պետությանը. Վանա լճի ավազանն անցավ Ակ Կոյունլուներին", "d8d6c2e8"], "d": ["Ակ Կոյունլու տիրակալ Ուզուն Հասանը, անակնկալի բերելով 1467 թ. իր վրա եկած անողոք թշնամուն՝ Կարա Կոյունլու տիրակալ Ջահան Շահին, վերջ դրեց Կարա Կոյունլուների պետությանը։ 1438 թվականից իշխող Ջահան Շահի վերացումով Վանա լճի ավազանը՝ Վանը, Բիթլիսը, Բարգիրին (Մուրադիյե), Խոշապը և Կոտուրը, Կարա Կոյունլուներից անցավ Ակ Կոյունլուների կառավարման։ Այս հաղթանակը Ակ Կոյունլուների պետությունը դարձրեց Արևելյան Անատոլիայի և Իրանի միակ մեծ ուժը և Ուզուն Հասանին դրեց այն ճանապարհին, որը մեկ սերունդ անց նրան կանգնեցնելու էր օսմանցիների դեմ հանդիման։", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["Ջեմ սուլթանին բերեցին Հռոմ. պատանդի դիվանագիտություն և տարեկան 40.000 դուկատ", "1c6715a8"], "d": ["Պապ Իննոկենտիոս VIII-ը, համաձայնության գալով Հռոդոսի ասպետների առաջնորդ Պիեռ դ'Օբյուսոնի հետ, Ջեմ սուլթանին բերել տվեց Հռոմ (1489 թ. մարտի 4)։ Ջեմը 1482 թ. հուլիսի 29-ին ապաստանել էր Հռոդոսում, այնտեղից անցել Սավոյայի հողերը և վերջում՝ պապական հսկողության։ Բայազիդ II-ը, որպես հակառակ ծառայություն՝ եղբորը հսկողության տակ պահելու դիմաց, ընդունել էր ասպետներին տարեկան 40.000 դուկատ վճարել և նրանց օսմանյան տարածքներում ազատ առևտրի իրավունք տալ։ Այս վճարը խարաջ չէր, այլ գահի օրինական հավակնորդին Եվրոպայում անշարժ պահելու գինը. եթե Ջեմը ազատ մնար, կարող էր Անատոլիայում բանակ հավաքել և, բացի այդ, դառնալ խաչակրաց արշավանքի օրինականության աղբյուր։ Այսպիսով հարստության ներքին մի հարց երեսուն տարի դարձավ օսմանյան արտաքին քաղաքականության հիմնական սահմանափակումը. սա է Բայազիդի՝ Արևմուտքում զգուշավոր վարվելու պատճառը։ 1495 թ. Ջեմի մահով այս սահմանափակումը վերացավ։", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["Վրաց թագավորությունը բաժանվեց երեքի՝ Քարթլի, Կախեթի և Իմերեթի՝ Քութայիսի կենտրոնով", "f9c5f798"], "d": ["Բագրատունյաց հարստության կառավարած միացյալ Վրաց թագավորությունը երկարատև ներքին պայքարից հետո պաշտոնապես բաժանվեց երեք թագավորության. արևելքում Թիֆլիս կենտրոնով Քարթլի, հյուսիս-արևելքում Կախեթի և արևմուտքում Իմերեթի՝ Քութայիսի կենտրոնով։ TDV-ի «Վրաստան» հոդվածը հաստատում է բաժանումը. «Վրաստանը բաժանվեց երեք թագավորության (Քարթլիա, Կախեթիա, Իմերեթիա) և հինգ իշխանության»։ Բաժանումը վճռորոշ եղավ հաջորդ դարի օսմանա-սեֆյան մրցակցության մեջ. 1555 թ. Ամասիայի պայմանագրով Իմերեթիան, Դադիանը, Գուրիան և Դավելին թողնվեցին Օսմանյան պետությանը, իսկ Քարթլին, Կախեթիան և Մոսուքը՝ Սեֆյաններին։ Այսինքն՝ ատլասի՝ արևմտյան և արևելյան Վրաստանը տարբեր տերերի կապելը ծագում է այս բաժանումից։ Յավուզ Սուլթան Սելիմը դեռ Տրապիզոնի կուսակալ եղած ժամանակ՝ 1508 թ., հնազանդության և խարաջի էր ենթարկել Իմերեթիի (Աչըքբաշ) թագավորությունը։", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["Իսպանացիները գրավեցին Տրիպոլին (Լիբիա). Հաֆսյան տիրապետության վերջը", "de319d23"], "d": ["Ամմարյաններից հետո Տրիպոլիում Հաֆսյանների տիրապետությունը շարունակվեց մինչև 1510 թ.։ Այդ տարում քաղաքը գրավեցին Օլիվետոյի կոմս Դոն Պեդրո Նավառոյի հրամանատարությամբ իսպանացիները. կոտորածից փրկված մուսուլմանները լքեցին քաղաքը։ Գրավումը Հյուսիսային Աֆրիկայի ափին Մելիլիայից Տրիպոլի ձգվող իսպանական բերդերի շղթայի արևելյան ծայրն էր։ Տրիպոլիի բնակչությունը հիջ. 925 (1519) թ. պատվիրակություն ուղարկելով Ստամբուլ՝ իսպանական ներխուժման դեմ օգնություն խնդրեց Օսմանյան պետությունից. 1551 թ. քաղաքը, վերցվելով Թուրգութ ռեիսի և Սինան փաշայի կողմից, անցնելու էր օսմանյան կառավարման։", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["Մալթան և Տրիպոլին տրվեցին Սուրբ Հովհաննեսի ասպետներին. Հռոդոսից վտարված օրդենի նոր հենակետը", "2595729e"], "d": ["Սուլթան Սուլեյման Կանունիի հիջ. 928 (1522) թ. Հռոդոսից դուրս մղած Սուրբ Հովհաննեսի (հոսպիտալյան) ասպետներին ութ տարի անհայրենիք մնալուց հետո Իսպանիա-Գերմանիայի թագավոր Կարլոս V-ը բնակեցրեց Մալթայում. նույն նվիրատվությամբ օրդենին տրվեց նաև Տրիպոլիի պաշտպանությունը։ Մալթան իր իդեալական նավահանգիստներով ծովերում ակտիվ ասպետների համար դարձավ հարմար հենակետ. նախ հաստատվեցին Բիրգուում, ամրացրին Սեն Անջելո բերդը և Սենգլեայի ծայրին կառուցեցին Սեն Միշել բերդը։ Այս բնակեցումը Միջերկրական ծովի կենտրոնում ստեղծեց օսմանյան ծովային ուղիները կտրող մշտական թշնամական հենակետ. Թուրգութ ռեիսի՝ հիջ. 947 (1540) թ. Գոցոյի ասպատակությամբ սկսված բախումները տևելու էին մինչև 1565 թ. Մալթայի պաշարումը։", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["Վեստֆալյան խաղաղությունը. Երեսնամյա պատերազմներն ավարտվեցին, Սրբազան Հռոմի միասնությունը քայքայվեց", "d7719f05"], "d": ["Երեսնամյա պատերազմներին (1618-1648) վերջ դրած պայմանագրերը նույն օրը ստորագրվեցին Մյունստերում և Օսնաբրյուկում (1648 թ. հոկտեմբերի 24)։ Սրբազան Հռոմեական կայսրության մոտ երեք հարյուր իշխանություններ ստացան իրենց սեփական արտաքին քաղաքականությունը վարելու իրավունք. կայսրությունը դադարեց պետություն լինելուց և վերածվեց ծածկոցի։ Շվեդիան ստացավ Արևմտյան Պոմերանիան և Շտետինը, իսկ Բրանդենբուրգը՝ Արևելյան Պոմերանիան և Մագդեբուրգի արքեպիսկոպոսության ակնկալիքը. Հոհենցոլեռնների՝ 1701 թ. թագավորության ուղղվելիք հողային կուտակումը այստեղ է սկսվում։ Հոլանդիայի և Շվեյցարիայի անկախությունը պաշտոնապես ճանաչվեց։ Օսմանյան պետության համար դրա նշանակությունը անուղղակի է, բայց մեծ. Հաբսբուրգների արևմտյան ճակատից քաշվելով Կենտրոնական Եվրոպայում ծնվեց ուժ, որ կարող էր կրկին դեպի արևելք շրջվել։", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["Հռչակվեց Պրուսիայի թագավորությունը. Ֆրիդրիխ I-ը թագադրվեց Քյոնիգսբերգում", "337a9f74"], "d": ["Բրանդենբուրգի կուրֆյուրստ Ֆրիդրիխ III-ը, կայսր Լեոպոլդ I-ի հավանությամբ թագադրվելով Քյոնիգսբերգում, ստացավ «թագավոր Պրուսիայում» տիտղոսը (1701 թ. հունվարի 18)։ Տիտղոսը վերցվել էր Արևելյան Պրուսիայից, որովհետև այն Սրբազան Հռոմեական կայսրությունից դուրս էր, և կայսրին ենթակա կուրֆյուրստը կարող էր թագավոր լինել միայն կայսրության սահմաններից դուրս։ Հոհենցոլեռն հարստության ցրված հողերն այս ամսաթվից սկսեցին կոչվել մեկ պետության անունով։", "203ac1b3"]},
"OLAYLAR_EK20:1720-09-02:0":{"b": ["Սարդինիան Իսպանիայից անցավ Սավոյա հարստությանը. ծնվեց Սարդինիայի թագավորությունը", "adf778b7"], "d": ["Իսպանական ժառանգության պատերազմը փակող կարգավորումների վերջին օղակում Սարդինիա կղզին վերցվեց Իսպանիայից և տրվեց Սավոյա հարստությանը. Սավոյայի դուքսը փոխարենը թողեց Սիցիլիան և ստացավ Սարդինիայի թագավորի տիտղոսը։ Այսպիսով Կալյարին և Սասարին դուրս եկան երկդարյա իսպանական կառավարումից։ Ծնված Սարդինիայի թագավորությունը մեկուկես դար անց իտալական միասնությունը կերտելիք պետության միջուկն է. այսինքն՝ 1870 թ. Հռոմ մտած Իտալիայի թագավորության արմատը այստեղ է հասնում։", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["Կորսիկան Ջենովան վաճառեց Ֆրանսիային. Վերսալի պայմանագիրը", "770343df"], "d": ["Ջենովայի Հանրապետությունը Ֆրանսիային հանձնեց Կորսիկան, որը դարեր շարունակ իր ձեռքում էր, բայց ապստամբությունների պատճառով փաստացի չէր կարողանում վերահսկել։ TDV-ի «Կորսիկա» հոդվածը իրադարձությունը մեկ նախադասությամբ է տալիս. Ջենովան այս կղզին, որին այնքան էլ տեր չէր կարողանում կանգնել, 1768 թ. վաճառեց Ֆրանսիային։ Հանձնումը նշանավորում է Միջերկրական ծովում Ջենովայի վերջին խոշոր տարածքային ունեցվածքից նրա հեռանալը. կղզին 1796 թ. որոշ ժամանակ անցնելու էր անգլիական ձեռք, ապա կրկին վերադարձվելու էր Ֆրանսիային։ Կղզու՝ ֆրանսիական հող դառնալը մեկ տարի անց Այաչչոյում ծնվելիք Նապոլեոն Բոնապարտին դարձրեց ֆրանսիական հպատակ։ Այս տարի (1768) Կորսիկան, ներառյալ Բաստիան, Ջենովայից վաճառվեց Ֆրանսիային (TDV «Կորսիկա». օրը հաստատված չէ)։", "c6214397"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["Թիլզիտի պայմանագիրը. Պրուսիան կորցրեց իր հողերի կեսը, հիմնվեց Վարշավայի դքսությունը", "d30bb2cc"], "d": ["Յենա-Աուերշտեդտի ջախջախումից հետո Պրուսիան ստիպված էր Թիլզիտում Նապոլեոնի հետ ծանր խաղաղություն ընդունել (1807 թ. հուլիսի 9)։ Նա զիջեց Էլբայից արևմուտք իր բոլոր հողերը և 1793 ու 1795 թվականների բաժանումներով ստացած լեհական տարածքները. վերջիններից հիմնվեց Վարշավայի դքսությունը, իսկ Բելոստոկի շրջակայքը տրվեց Ռուսաստանին։ Պրուսիան կորցրեց իր բնակչության և հողի մոտ կեսը, բանակը սահմանափակվեց 42.000-ով։ Ատլասում Պոզնանն ու Տորունը այս օրվանից անցնում են Վարշավայի դքսությանը, իսկ Բելոստոկը՝ Ռուսաստանին։ Այս պայմանագրով Լոձը և Չենստոխովան (1772-ից հետո Պրուսիային անցած լեհական նահանգներ) անցան Վարշավայի դքսությանը. Գդանսկը (Դանցիգ) դարձավ անկախ ազատ քաղաք։", "e484982c"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["Իտալական զորքերը մտան Հռոմ. Պապական պետության վերջը և իտալական միասնության ամբողջացումը", "a3689f2e"], "d": ["Երբ ֆրանս-պրուսական պատերազմում Նապոլեոն III-ի տապալումը ետ քաշեց Հռոմը պաշտպանող ֆրանսիական կայազորը, իտալական զորքերը մտան քաղաք, և պապը քաշվեց Վատիկան։ Այսպիսով ավարտվեց ավելի քան հազար տարի գոյատևած Պապական պետությունը, իսկ Հռոմն էլ միության մեջ առած Իտալիայի թագավորությունը հանդես եկավ Եվրոպայի և աշխարհի բեմում որպես քաղաքական ուժ։ Սա ատլասի վերջին կես դարի համար անմիջական հետևանքներ ունեցող իրադարձություն է. միացյալ Իտալիան է այն պետությունը, որ 1911 թ. Օսմանյան պետությունից վերցնելու է Տրիպոլին և Տասներկու կղզիները։", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["Չելենկոյի ճակատամարտը. Հարարի ամիրայության վերջը և հաբեշական գրավումը", "5671a0d9"], "d": ["Երբ Դավուդը դարձավ Աուսսայի իմամ, օրոմոների կառավարած հողերի կենտրոնում մնացած Հարարը կրկին դարձել էր անկախ ամիրայություն և այդ վիճակը պահել մինչև 1887 թ. հաբեշական գրավումը։ Ջիհադ հայտարարած էմիր Աբդալլահը 5000 հոգով 1887 թ. հունվարի 7-ին դիմավորեց հաբեշներին Շելենեկոյում (Չելենկո). երբ հասկացավ, որ պարտվելու է, փախավ Հարարի հարավում գտնվող Օգադենի շրջան։ Ճակատամարտը ցույց տվեց հրազենով սպառազինված հաբեշական բանակի և ամիրայության ուժերի անհավասարակշռությունը և վերացրեց Կարմիր ծովի հետևի վերջին անկախ մուսուլմանական ամիրայություններից մեկը։ Այսպիսով Հարարը, Ջիջիգան և Դագաբուրը միացան Եթովպիային։", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["Շահ Իսմայիլը վերցրեց Դերբենդը. սեֆյան տիրապետությունը հասավ Կովկասի դարպասին", "305542c4"], "d": ["1500 թ. Շիրվանշահ Ֆարրուխ Յասարի պարտվելով և սպանվելով Բաքուն և Շամախին անցել էին սեֆյան ձեռքը, իսկ Դերբենդը որոշ ժամանակ դեռ առանձին էր մնացել։ 1509 թ. Շահ Իսմայիլը գրավեց քաղաքը և այնտեղ բնակեցրեց ռումլու ցեղերից մեկին. այսպիսով սեֆյան տիրապետությունը հասավ Կովկասի հյուսիսային դարպասին՝ Կասպից ծովի և լեռների միջև ընկած այս նեղ անցքին։ 1538 թ. Շիրվանի՝ սեֆյան ուղղակի կառավարման անցնելով կապը կայունացավ։ Դերբենդը 1578 թ. արշավանքում անցնելու էր օսմանյան ձեռքը և մինչև 1607 թ. լինելու էր յոթ սանջակ ունեցող բեյլերբեյության կենտրոն։ TDV-ի գրառումը այսպիսին է. «Սեֆյան պետության հիմնումն ու զարգացումը Դերբենդում նոր շրջանի սկիզբ դարձավ։ Շահ Իսմայիլը 1509 թ. գրավեց քաղաքը և այնտեղ բնակեցրեց ռումլու ցեղերից մեկին։ Երբ 1538 թ. Շիրվանն անմիջապես անցավ սեֆյան տիրապետության տակ...»։", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["Կարսի վերջնական միացումը օսմանյան հողերին. արևելյան սահմանի մեխը", "6235c85a"], "d": ["Սեֆյանների կողմից Ակ Կոյունլուների պետության կործանումից հետո Կարսը որոշ ժամանակ մնացել էր ավշար թուրքմեններից Սևունդյուք խան Կուրչիբաշիի ձեռքին։ Կանունիի Իրաքեյնի արշավանքի ժամանակ (հիջ. 940/1534), Պասենի, Շուրագյալի և Օլթիի բերդերը վերցնելիս, մեծ հավանականությամբ Կարսի բերդն էլ կապվել է օսմանցիներին. սակայն քաղաքի վերջնական միացումը եղել է երեք տարի անց։ TDV-ի գրառումը այսպիսին է. «Կարսը օսմանյան ծառայության անցած Դուլկադիրցի Մեհմեդ խանի կողմից վերջնականապես օսմանյան հողերին ներառվեց հիջ. 944 (1537) թ.»։ Քանի որ երկարատև պայքարների պատճառով քաղաքն ու բերդը մեծ մասամբ ավերվել էին, ձեռնարկվեց արագ վերանորոգում. հիջ. 955 (1548) թ., երբ բերդը նորոգվում էր, սեֆյանները հարձակվեցին քաղաքի վրա և բերդը կրկին ավերեցին։ Դրանից հետո Կարսը երեք հարյուր քառասուն տարի մնալու էր օսմանյան հյուսիս-արևելյան սահմանի բանալին, իսկ 1877-78 թթ. պատերազմից հետո թողնվելու էր Ռուսաստանին։", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["Նիկոպոլի հետ վերցնելը. ավարտվեց վեցամսյա ռուսական օկուպացիան", "7fb299d7"], "d": ["1806-1812 թթ. ռուս-թուրքական պատերազմում Դանուբի հարավային ափ անցած ռուսական ուժերը 1810 թ. հոկտեմբերին գեներալ Կուտուզովի հրամանատարությամբ գրավել էին Նիկոպոլը։ Վեց ամիս անց, տեսնելով, որ Դանուբի գիծը չեն կարողանա պահել, դատարկեցին քաղաքը. նախքան հեռանալը բերդի մեծ մասը պայթեցրին։ TDV-ի գրառումը այսպիսին է. «1810 թ. հոկտեմբերին (1808-1812 թուրք-ռուսական պատերազմի շրջանում) Նիկոպոլը գրավեցին ռուս հռչակավոր գեներալ Միխայիլ Կուտուզովի ուժերը։ Ռուսները, նախքան քաղաքը լքելը, 1811 թ. ապրիլին պայթեցրին բերդի մեծ մասը և քաղաքին մեծ վնաս հասցրին»։ Ռուսական ուժերի հեռանալուց հետո օսմանցիները վերակառուցեցին բերդը. 1813-1814 թվագրված արձանագրությունը այս վերանորոգման վկայությունն է։", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["Սիլիստրայի տարհանումը. Դանուբի միջին բերդը լքվեց՝ պարիսպները քանդելով", "561628bb"], "d": ["Դանուբի ամենաուժեղ օսմանյան բերդերից Սիլիստրան 1810 թ. ենթարկվել էր ռուսական հրետանու ռմբակոծության, և զինապահեստի պայթյունից բերդն ու արվարձանը ծանր վնասվել էին։ Ռուսները, քաղաքը գրավելուց հետո, նախընտրեցին ոչ թե պահել այն, այլ ոչնչացնել ամրությունները. գեներալ Կուտուզովը հրամայեց քանդել պարիսպները և 1811 թ. մայիսին ցարին զեկուցեց, որ Սիլիստրայի պարիսպները պայթեցվել են։ TDV-ի գրառումը. «1810 թ. քաղաքը ռմբակոծվեց ռուսների կողմից… Ռուսների՝ քաղաքը գրավելուց հետո և նախքան նահանջելը գեներալ Կուտուզովը հրամայեց քանդել Սիլիստրան։ 1811 թ. մայիսին ցարին հայտնեց, որ Սիլիստրայի պարիսպները պայթեցվել են»։ Նույն բերդը 1827-1828 թթ. պատերազմում ռուսները նորից վերցնելու էին, և այդ պաշարումը մանրամասնորեն նկարագրելու էր Հելմուտ ֆոն Մոլտկեն։", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["Զենդ հարստության վերջը. Ղաջարների տիրապետությունը Իրանում", "5dda30a4"], "d": ["Զենդ հարստության վերջին տիրակալ Լութֆ Ալի խանի պարտությամբ ավարտվեց 1751 թ. հիմնված հարստությունը, և ողջ Իրանը անցավ Աղա Մուհամմեդ խանի ձեռքը։ Ղաջարների պետության պաշտոնական հիմնումը թվագրվում է երկու տարի ուշ՝ Աղա Մուհամմեդ խանի՝ Թեհրանում շահնշահի թագը կրելով (1796). սակայն իշխանության փոխանցումը կայացել է 1794 թ.։", "793d45c6"]},
"OLAYLAR_EK22:1923-07-24:0":{"b": ["Լոզան–Սևր տարբերությունները. պարտադրված խաղաղությունից դեպի հավասար խաղաղություն", "4b578583"], "d": ["Սևրը (1920 թ. օգոստոսի 10) Ստամբուլի կառավարությանը պարտադրված, երբեք ուժի մեջ չմտած փաստաթուղթ էր. Լոզանը (1923 թ. հուլիսի 24) այն խաղաղությունն է, որը Անկարան ստորագրեց որպես հավասար կողմ, և Թուրքիայի Ազգային մեծ ժողովը (TBMM) վավերացրեց 1923 թ. օգոստոսի 23-ին (Լոզան, հոդվ. 1, 143)։ Սահմանների հարցում Սևրը Թուրքիայի եվրոպական սահմանը քաշում է դեպի Չաթալջայի գիծ և Հունաստանին տալիս Արևելյան Թրակիան՝ ներառյալ Էդիրնեն, ինչպես նաև Իմբրոսն ու Թենեդոսը (Սևր, հոդվ. 27, 84). իսկ Իզմիրն ու շրջակայքը անվանապես մնում են թուրքական ինքնիշխանության տակ, բայց կառավարումը թողնվում է Հունաստանին, և հինգ տարի անց տեղական խորհրդարանը կարող է խնդրել միացում (հոդվ. 65-83)։ Լոզանը գծում է Մարիցա-Արդա գիծը, Էդիրնեն և Կարաաղաչը մնում են Թուրքիային, Իմբրոսն ու Թենեդոսը դառնում են թուրքական (Լոզան, հոդվ. 2, 12, 14. Կարաաղաչի արձանագրություն)։ Նեղուցների հարցում Սևրը ստեղծում է բոլոր ջրերը ընդգրկող միջազգային հանձնաժողով, ուր թուրք անդամն ունի միայն մեկ ձայն. ամրությունները քանդվում են, և շրջանը բացվում է Դաշնակիցների օգտագործման համար (Սևր, հոդվ. 36-61, 178-180)։ Լոզանը պահպանում է ազատ անցման սկզբունքը, բայց թողնում է թուրք նախագահով հանձնաժողով, ապառազմականացված գոտիներ և Ստամբուլում 12.000 հոգանոց կայազոր (Լոզան, հոդվ. 23. Նեղուցների կոնվենցիա)։ Հայաստանի ճանաչումը և ԱՄՆ նախագահի սահմանային արբիտրաժը, ինչպես նաև քրդական ինքնավարության ծրագիրը (Սևր, հոդվ. 62-64, 88-93) Լոզանում տեղ չունեն։ Արաբական հողերի, Եգիպտոսի, Սուդանի և Կիպրոսի հարցերում Սևրը դնում է հանձնման մանրամասն դրույթներ (Սևր, հոդվ. 94-97՝ մանդատներ, հոդվ. 98-100՝ Հիջազ, հոդվ. 101-122՝ Եգիպտոսից, Սուդանից, Կիպրոսից, Մարոկկոյից, Թունիսից և Լիբիայից հրաժարում. TDV-ի հոդվածների միջակայքերն էլ այդպիսին են). Լոզանը հրաժարումը ավելի կարճ է գրում, Տասներկու կղզիները մնում են Իտալիային, Կիպրոսը՝ Անգլիային, Մոսուլի սահմանը հետաձգվում է (Լոզան, հոդվ. 3, 15-21)։ Սևրը վերականգնում և ընդլայնում է կապիտուլյացիաները, Ֆինանսական հանձնաժողովի միջոցով վերահսկում թուրքական բյուջեն և փոխառությունները, զինված ուժը (ժանդարմերիա և համալրման տարրեր) չի կարող անցնել 50.000 հոգին, ռազմական և ծովային ավիացիան արգելված է (Սևր, հոդվ. 155, 164, 191-195, 231-264, 261-263)։ Լոզանը վերացնում է կապիտուլյացիաները, բաշխում պարտքերը և բանակի առանձին սահմանափակում չի դնում (Լոզան, հոդվ. 28, 46-63. հոդվ. 113-ը վերացնում է նաև օտար փոստային բաժանմունքները)։ Փոքրամասնությունների դրույթները Սևրում ավելի լայն են և բաց Դաշնակիցների միջամտության համար, իսկ Լոզանում՝ Ազգերի լիգայի երաշխիքով և փոխադարձ (Սևր, հոդվ. 140-151. Լոզան, հոդվ. 37-45)։\n\nԱռանցք առ առանցք համեմատություն.\n• Արևելյան Թրակիա, Էդիրնե, Չաթալջա — Սևր. սահմանը Չաթալջայի գիծն է. Արևելյան Թրակիան և Էդիրնեն՝ Հունաստանին (հոդվ. 27, 84-85) | Լոզան. սահմանը Մարիցայի և Արդայի երկայնքով. Էդիրնեն և Կարաաղաչը՝ Թուրքիայում (հոդվ. 2. Կարաաղաչի արձանագրություն)\n• Իզմիրի շրջան — Սևր. ինքնիշխանությունը թուրքական, կառավարումն ու բանակը՝ հունական, հինգ տարի անց միացման դիմում (հոդվ. 65-83) | Լոզան. Իզմիրի համար հատուկ կարգավիճակի հոդված չկա. Անատոլիան Թուրքիայի սահմանների ներսում է (հոդվ. 2-3՝ ընդհանուր սահման. Իզմիրի վերաբերյալ առանձին հոդվածային ապացույց չկա)\n• Նեղուցներ և Ստամբուլ — Սևր. Նեղուցների միջազգային հանձնաժողով, Թուրքիան՝ 1 ձայն. ամրությունների քանդում, շրջանը՝ Դաշնակիցների օգտագործման տակ. Ստամբուլը թուրքական ձեռքում, բայց կախված փոքրամասնությունների պայմանից (հոդվ. 36-61, 178-180) | Լոզան. ազատ անցման սկզբունք. թուրք նախագահով հանձնաժողով, ապառազմականացված գոտիներ, Ստամբուլում 12.000 հոգանոց կայազոր (հոդվ. 23. Նեղուցների կոնվենցիա)\n• Հայաստան և Քուրդիստան — Սևր. Հայաստանը ճանաչվում է, սահմանը որոշում է ԱՄՆ նախագահը. քրդական ինքնավարություն, մեկ տարի անց անկախության դիմում (հոդվ. 62-64, 88-93) | Լոզան. համապատասխան դրույթ չկա (հոդվ. 1-143 ամփոփումներում չի հիշատակվում)\n• Էգեյան կղզիներ, Տասներկու կղզիներ — Սևր. Իմբրոսը, Թենեդոսը և Էգեյան կղզիները՝ Հունաստանին. Տասներկու կղզիները և Մեիսը՝ Իտալիային (հոդվ. 84, 122) | Լոզան. Իմբրոսն ու Թենեդոսը՝ Թուրքիայում, արևելաէգեյան կղզիները՝ հունական, Տասներկու կղզիներն ու Մեիսը՝ Իտալիայում (հոդվ. 12-15)\n• Կիպրոս, Եգիպտոս, Սուդան, արաբական հողեր — Սևր. Սիրիայի/Միջագետքի և Պաղեստինի մանդատ, Հիջազը անկախ. ճանաչվում են Եգիպտոսի պրոտեկտորատը, Սուդանի, Կիպրոսի բռնակցումը (հոդվ. 94-98, 101-117) | Լոզան. Սիրիայի սահմանը՝ 1921 թ. ֆրանս-թուրքական համաձայնագրով, Իրաքի սահմանը՝ հետագայում. հրաժարում Եգիպտոսից, Սուդանից, Կիպրոսից (հոդվ. 3, 16-20)\n• Կապիտուլյացիաներ — Սևր. վերականգնվում և ընդլայնվում են. դատական բարեփոխումների ծրագիրը՝ Դաշնակիցների հանձնաժողովում (հոդվ. 136, 261-263, 308-309) | Լոզան. լիովին վերացվում են. վերանում են օտար փոստային բաժանմունքները և Բարձրագույն սանիտարական խորհուրդը (հոդվ. 28, 113-114)\n• Ֆինանսական վերահսկողություն և պարտքեր — Սևր. Դաշնակիցների Ֆինանսական հանձնաժողովը վերահսկում է բյուջեն և փոխառությունները, Օսմանյան պետական պարտքի վարչությունը (Düyun-ı Umumiye) ընդլայնվում է, ռեսուրսները՝ գրավ (հոդվ. 231-264) | Լոզան. Օսմանյան պետական պարտքը բաշխվում է պետությունների բաժնեմասերի միջև. պատերազմական վնասները փոխադարձաբար զիջվում են (հոդվ. 46-63, 58)\n• Ռազմական սահմանափակումներ — Սևր. բանակը 50.000 հոգի, արգելվում են օդուժը և տանկերը, Դաշնակիցների վերահսկիչ հանձնաժողովներ (հոդվ. 152-207) | Լոզան. ընդհանուր սահմանափակում չկա. միայն հունական կղզիներում և Նեղուցների ու Թրակիայի շրջաններում ապառազմականացում (հոդվ. 13. Նեղուցների և Թրակիայի կոնվենցիաներ)\n• Փոքրամասնություններ — Սևր. Դաշնակիցների երաշխիք և միջամտության իրավունք, «լքյալ գույքի» (Emval-i Metruke) չեղարկում, վերադարձ (հոդվ. 140-151, 86, 142-144) | Լոզան. ոչ մուսուլման փոքրամասնություններին՝ Ազգերի լիգայի երաշխավորած իրավունքներ, Հունաստանում մուսուլմանների փոխադարձ իրավունքներ. հույն-թուրք բնակչության փոխանակում (հոդվ. 37-45. Փոխանակման կոնվենցիա)\n• Իրավական կարգավիճակ — Սևր. ստորագրել է Ստամբուլի կառավարությունը, Անկարան մերժել է, ուժի մեջ չի մտել (TDV) | Լոզան. հավասար կողմ. TBMM-ի վավերացումը՝ 1923 թ. օգոստոսի 2, 213 կողմ, 14 դեմ (TDV. հոդվ. 1, 143)", "95c8b4ce"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Օսմանյան առաջին ակչեի հատումը", "38d2d638"], "d": ["Օրհան Ղազիի անունով հատված առաջին արծաթե ակչեն բեյլիքի անկախ գերիշխանության դրամական հռչակումն է. ակչեն հինգ դար մնաց որպես հիմնական դրամական միավոր։", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Հիմնվեց Ռումելիի բեյլերբեյությունը", "ffa16089"], "d": ["Եվրոպական ափի նվաճումները հավաքվեցին մեկ ռազմավարչական տանիքի տակ. բեյլերբեյությունների կարգը դարձավ կայսրության գավառական վարչական կազմակերպության ողնաշարը։", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Յըլդըրըմ Բայազիդ – Դեսպինա խաթուն ամուսնությունը", "4b10dc6c"], "d": ["Կոսովոյից հետո Սերբական դեսպոտության հետ հաստատված վասալությունը կնքվեց Լազարի դստեր Օլիվերայի՝ Բայազիդի հետ ամուսնությամբ. վաղ շրջանի ամուսնական դիվանագիտության բնորոշ օրինակ։", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Հիմնվեց Անատոլիայի բեյլերբեյությունը", "5ef8d3a7"], "d": ["Բռնակցված բեյլիքների հողերի կառավարման համար կազմակերպվեց Անատոլիայի բեյլերբեյությունը. ամբողջացավ Ռումելի-Անատոլիա երկթև վարչական կարգը։", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Ավարտվեց Բուրսայի Ուլու մզկիթը", "27bcc4a5"], "d": ["Նիկոպոլիսի ավարով կառուցված քսան գմբեթով մեծ մզկիթը վաղ օսմանյան ճարտարապետության մոնումենտալ օրինակն է և գեղագրության արվեստի բաց թանգարանը։", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Չանդարլը Հալիլ փաշայի պաշտոնազրկումը և մահապատիժը", "5e19438f"], "d": ["Նվաճումից հետո մահապատժի ենթարկվեց պաշարման նկատմամբ զսպվածություն ցուցաբերած հինավուրց Չանդարլը ընտանիքից սերող մեծ վեզիրը. առաջին անգամ մեծ վեզիրը սպանվում էր փադիշահի հրամանով, բացվում էր դևշիրմե ծագմամբ վեզիրների դարաշրջանը։", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Մոլդովայի խարաջատու դառնալը", "25bd3693"], "d": ["Մոլդովայի վոյևոդությունը համաձայնեց խարաջ վճարել. Վալախիայի և Տրանսիլվանիայի հետ միասին Դանուբից հյուսիս եռակի վասալական գոտին դարձավ կայսրության հյուսիսային բուֆերը։ Նույն ամսաթվին միացած այլ վայրեր՝ Յասսի։", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Դուբրովնիկի (Ռագուզա) խարաջը", "d127c78a"], "d": ["Վաճառական հանրապետություն Ռագուզան խարաջի դիմաց երաշխավորեց իր ինքնավարությունն ու առևտրային արտոնությունները. որպես Ադրիատիկ ծովում օսմանյան պատուհան՝ հարստացավ։ Հանրապետության հողը եղած Մլյետ կղզին (Mljet) ևս կիսում էր այս կարգավիճակը։", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Վալախիայի արշավանքը՝ Ցցահանող վոյևոդը", "fd4530bb"], "d": ["Խարաջ վճարել մերժած և դեսպաններին սպանած Վլադ Ցեպեշի դեմ կազմակերպված արշավանքով Վալախիան վերադարձվեց վասալության. գիշերային հարձակումն ու ցցահանման սարսափելի տեսարանները Եվրոպայում դարձան լեգենդ։ Նույն ամսաթվին միացած այլ վայրեր՝ Բուխարեստ։", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Բացվեց Ֆաթիհի համալիրը", "a150ea55"], "d": ["Իր ութ մեդրեսեներով (Սահն-ը Սեման) համալիրը Ստամբուլը իսլամական աշխարհի գիտական կենտրոնի վերածելու ծրագրի առաջին մեծ քայլն էր։", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ալի Քուշչուն Ստամբուլում", "8508229d"], "d": ["Սամարղանդի աստղադիտարանի վերջին մեծ ներկայացուցիչ Ալի Քուշչուն Ֆաթիհի հրավերով դարձավ Այա Սոֆիայի մեդրեսեի դասախոս (մյուդեռիս). Ստամբուլում հիմնեց մաթեմատիկա-աստղագիտության ավանդույթը։", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Ֆաթիհի կանունամեն", "b08944c9"], "d": ["Պետական կառույցը, արարողակարգը և պատիժները ամփոփող առաջին ընդգրկուն սովորութային կանունամեն. «աշխարհի կարգի համար» եղբայրասպանությունը թույլատրող իր հայտնի հոդվածով մինչև այսօր վիճարկվում է։", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Հատվեց առաջին օսմանյան ոսկեդրամը (սուլթանի)", "2fd5c0dd"], "d": ["Հատվեց վենետիկյան դուկատին համարժեք առաջին օսմանյան ոսկեդրամը. կայսրության ֆինանսները միացան միջազգային դրամական կարգին։", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Տեղափոխություն Թոփքափի պալատ", "b9cd6a5e"], "d": ["Նոր պալատի (Թոփքափի) ավարտով պետական կառավարման կենտրոնը տեղափոխվեց այստեղ. պալատը չորս դար մնաց որպես կայսրության ուղեղը։", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Ֆլորենցիայի Հանրապետությունը վերածվեց դքսության — Ալեսանդրո դե Մեդիչի", "c08764e1"], "d": ["Պապ Կլեմենտ VII-ի ճնշմամբ Ֆլորենցիայի կառավարող հանձնաժողովը (Balìa) ընդունեց նոր սահմանադրություն. հնգադարյա հանրապետական կարգը վերացավ, Ալեսանդրո դե Մեդիչին հռչակվեց ժառանգական դուքս և մայիսի 1-ին փաստացի գահ բարձրացավ։ Այսպիսով Ֆլորենցիան անկախ քաղաք-հանրապետությունից վերածվեց Մեդիչի հարստության ժառանգական դքսության։", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Քանունի – Հյուրեմ Սուլթան ամուսնությունը", "abc05f26"], "d": ["Քանունիի՝ Հյուրեմի հետ պաշտոնական ամուսնությունը արմատապես փոխեց պալատական ավանդույթը. ծնվեց «Հասեքի սուլթան» հաստատությունը, և հարստության քաղաքականության մեջ բացվեց կանանց դարաշրջանի դուռը։", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Առաջին ընդգրկուն կապիտուլյացիաները Ֆրանսիային", "e2264e48"], "d": ["Որպես հաբսբուրգյան սեղմման դեմ ֆրանսիական դաշինքի մաս՝ Ժան դը լա Ֆորեի և Մաքբուլ Իբրահիմ փաշայի միջև ստորագրվեցին առևտրային արտոնություններ. այն ժամանակ դիվանագիտական միջոց եղած կապիտուլյացիաները դարերի ընթացքում վերածվելու էին ֆինանսական կախվածության դռան։", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Հնդկական օվկիանոսի արշավանքը՝ Դիուի պաշարումը", "fcd1217a"], "d": ["Սուեզից դուրս եկած նավատորմը անցավ Կարմիր ծովը և պաշարեց Գուջարաթի Դիուն. թեև ամրոցը չգրավվեց, օսմանյան ուժն առաջին անգամ հասավ Հնդկական օվկիանոս, և պորտուգալական մենաշնորհը խարխլվեց։", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Սեյդի Ալի Ռեիսի հնդկական ճանապարհորդությունը", "e5da3b2c"], "d": ["Բասրայի նավատորմը Եգիպտոս բերելու հանձնարարություն ստացած Սեյդի Ալի Ռեիսը փոթորիկների հետևանքով քշվեց Հնդկաստան. վերադարձի արկածները պատմող «Միրաթ ալ-մամալիք»-ը օսմանյան առաջին ուղեգրություններից է։", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Պիրի Ռեիսի մահապատիժը", "63026444"], "d": ["Հորմուզի արշավանքից նավատորմը Բասրայում թողած և վերադարձած մեծ ծովագնաց-քարտեզագիրը 84 տարեկանում մահապատժի ենթարկվեց. մեր գիտության պատմության ամենավիճելի որոշումներից մեկը։", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Բացվեց Սուլեյմանիե համալիրը", "1c6458b2"], "d": ["Ճարտարապետ Սինանի՝ «իմ ենթավարպետության գործը» անվանած համալիրը իր մեդրեսեներով, հիվանդանոցով և գրադարանով դարձավ դասական շրջանի ամենամեծ կրթաբարեգործական համալիրը։", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Մալթայի պաշարումը", "f57f6a85"], "d": ["Միջերկրական ծովի բանալի Մալթան չորս ամիս պաշարվեց. Թուրգութ Ռեիսը նահատակվեց, պաշարումը վերացվեց։ Սա դարձավ Քանունիի շրջանի ծովագնացության առաջին մեծ հետընթացը։", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Ավարտվեց Սելիմիե մզկիթը", "3b0484e1"], "d": ["Սինանի՝ «իմ վարպետության գործը» անվանած Սելիմիեն, որտեղ մեկ գմբեթը տիրում է տարածքին, համարվում է օսմանյան դասական ճարտարապետության գագաթնակետը (ՅՈՒՆԵՍԿՕ-ի համաշխարհային ժառանգություն)։", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Հիմնվեց Ստամբուլի աստղադիտարանը", "169bdf5d"], "d": ["Թաքիյուդդինի՝ ժամանակի ամենալավ սարքավորված դիտարաններից մեկը եղած աստղադիտարանը 1577 թվականի գիսավորից հետո ծագած վեճերի հետևանքով 1580 թվականին քանդվեց. ինստիտուցիոնալ աստղագիտությունը ուշացավ երեք դար։", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Չըլդըրի հաղթանակը — սկսվեց արևելյան պատերազմը", "13125a54"], "d": ["Չըլդըրում Սեֆյան բանակի պարտությամբ բացվեցին Կովկասի դարպասները. գրավվեց Թիֆլիսը, և Վրաստանն անցավ օսմանյան տիրապետության տակ։", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Ջահերի ճակատամարտը — Շիրվանը վերջնականապես օսմանյան է", "3bbc23bc"], "d": ["Քանի որ գիշերը ջահերի լույսով էլ շարունակվեց՝ այս անունով հիշվող ճակատամարտում Սեֆյանները վճռական պարտություն կրեցին. ամրապնդվեց օսմանյան տիրապետությունը Շիրվանում և Բաքվում։", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Մեծ արժեզրկումը — ակչեի ճգնաժամը", "9205c3d4"], "d": ["Երկարատև պատերազմների և ամերիկյան արծաթի ճնշման տակ ակչեի արծաթի պարունակությունը կրճատվեց կիսով չափ. գների հեղափոխությունը սնեց սիփահիական կարգի քայքայումը և ջալալիական խառնակությունը։", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Թավրիզի նվաճումը", "6506bdb9"], "d": ["Սերդար Օզդեմիրօղլու Օսման փաշան մտավ Թավրիզ. Սեֆյանների նախկին մայրաքաղաքն անցավ օսմանյան կառավարման տակ։ Օսման փաշան մի քանի շաբաթ անց մահացավ ռազմակայանում։", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Ֆերհադ փաշայի պայմանագիրը — արևելքում ամենաընդարձակ սահմանները", "c429972f"], "d": ["Շահ Աբբասի դեսպան Հայդար Միրզայի՝ Ստամբուլ գալուց (1590 թվականի հունվարի 18) հետո, այն պայմանով, որ նվաճված վայրերը մնային օսմանցիներին, կնքված և 12-ամյա պատերազմին վերջ դրած պայմանագրով Թավրիզը, Ղարաբաղը, Շիրվանը, Վրաստանը և Լուրիստանը մնացին օսմանցիներին. կայսրությունը արևելքում հասավ իր պատմության ամենաընդարձակ սահմաններին։", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Սկսվեց օսմանա-սեֆյան պատերազմը (1603-1612) — Շահ Աբբասի հակահարձակումը, Թավրիզի կորուստը", "abf27dd8"], "d": ["Իր բանակը վերակազմած Շահ Աբբասը, օգտվելով ջալալիական խառնակություններից, անցավ հարձակման. ընկավ Թավրիզը, կովկասյան ձեռքբերումները մի քանի տարվա ընթացքում ձեռքից գնացին։ Նույն արշավանքում և դրանից հետո ձեռքից դուրս եկած այլ բնակավայրեր՝ Նախիջևան, Խոյ, Մարանդ, Սալմաստ. Ղարաջադաղի (Ahar) և մուքրի բեյերը ևս անցան Սեֆյան կողմը։", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Ծնվեց Էվլիյա Չելեբին", "2b6051ff"], "d": ["Իր ավելի քան հիսուն տարվա ճանապարհորդությունները տասնհատորյա «Սեյահաթնամե»-ում ամփոփած Էվլիյա Չելեբին թողեց 17-րդ դարի օսմանյան աշխարհի եզակի համապատկերը։", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Նասուհ փաշայի պայմանագիրը", "bb69e388"], "d": ["1603 թվականից շարունակվող պատերազմին վերջ դրած պայմանագրով հրաժարվեցին 1590 թվականի ձեռքբերումներից և վերադարձան 1555 թվականի Ամասիայի սահմանին. արևելյան ճակատում հավասարակշռությունը վերականգնվեց։", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Բացվեց Սուլթան Ահմեդի մզկիթը", "e39dfd43"], "d": ["Իր վեց մինարեներով և կապույտ իզնիկյան ջնարակապատ սալիկներով «Կապույտ մզկիթը» դասական շրջանի վերջին մեծ սուլթանական համալիրն է։", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Սուլթան Իբրահիմի սպանությունը", "bc4eb452"], "d": ["Շռայլության և կառավարման ճգնաժամի պատրվակով զորաբանակի և ուլեմաների դաշինքը գահընկեց արեց Իբրահիմին. տասը օր անց ֆեթվայով նրան խեղդամահ արեցին։ Գահ բարձրացավ յոթամյա Մեհմեդ IV-ը. իշխանությունը փաստացի անցավ մեծ վալիդե Քյոսեմ սուլթանի ձեռքը։", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Քյաթիբ Չելեբիի մահը", "e167e89d"], "d": ["«Քեշֆ ազ-զունուն» մատենագիտությամբ և «Ջիհաննումա» աշխարհագրությամբ նա օսմանյան գիտության պատմության գագաթային անունն է. հայտնի է եվրոպական աղբյուրներից օգտվող առաջամարտիկ մոտեցմամբ։", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Էդիրնեի դեպքը — Մուստաֆա II-ի գահազրկումը", "0291c1cd"], "d": ["Փադիշահի՝ Էդիրնեում նստելը և Ֆեյզուլլահ էֆենդիի ազդեցության դեմ զայրույթը վերածվեցին բանակի և արհեստավորների մեծ ապստամբության. շեյխ ուլ-իսլամը ամբոխահարվեց, փադիշահը գահընկեց արվեց, պալատը վերադարձավ Ստամբուլ։", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Դեսպան Փարիզում՝ Յիրմիսեքիզ Մեհմեդ Չելեբի", "26312a3f"], "d": ["Ֆրանսիա ուղարկված մեծ դեսպանությունը դարձավ Արևմուտքը տեղում ուսումնասիրող առաջին համակարգված դիտարկումը. նրա «Սեֆարեթնամեն» ոգեշնչեց Կակաչների դարաշրջանի նորացումը։", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Հիմնվեց առաջին օսմանյան տպարանը", "4943f7e5"], "d": ["Թույլտվություն տրվեց թուրքերեն գիրք տպագրելու. առաջին գործը՝ Վանքուլուի բառարանը, տպագրվեց 1729 թվականին։ Տպարանը Կակաչների դարաշրջանի նորացման ամենամնայուն ժառանգությունն է։", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Կապիտուլյացիաները դարձվեցին մշտական", "d044a79e"], "d": ["Ֆրանսիային տրված արտոնությունները, դադարելով սահմանափակվել փադիշահի կյանքով, կապվեցին մշտական պայմանագրի. միակողմանի չեղարկման ենթակա չդարձած կապիտուլյացիոն ռեժիմը կարողացավ վերանալ միայն Լոզանում։", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Հիմնվեց կայսերական ծովային ինժեներական դպրոցը (Mühendishâne-i Bahrî-i Hümâyun)", "9bf3f439"], "d": ["Չեշմեի աղետից հետո ժամանակակից ծովային սպաներ պատրաստելու համար հիմնված ինժեներական դպրոցը արևմտյան ոճի տեխնիկական կրթության առաջին մշտական հաստատությունն է. ցամաքային ինժեներական դպրոցը հետևեց 1795 թվականին։", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Առաջին մշտական դեսպանությունը Լոնդոնում", "6b5630eb"], "d": ["Որպես Նիզամ-ը Ջեդիդ ծրագրի մաս՝ եվրոպական մայրաքաղաքներում բացվեցին մշտական դեսպանություններ. օսմանյան դիվանագիտությունն անցավ փոխադարձության սկզբունքին։", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Ալեմդար Մուստաֆա փաշայի մահը", "4426534e"], "d": ["1808 թվականի նոյեմբերի 15-ի գիշերը սկսված ենիչերիական ապստամբության ժամանակ Բարձր Դռանը պաշարված բարեփոխիչ մեծ վեզիրը, երբ սպասած օգնությունը չեկավ, հաջորդ օրը, պայթեցնելով զինապահեստը, զոհվեց հարյուրավոր հարձակվողների հետ. Սենեդ-ի Իթթիֆաքի կարգը և բարեփոխումների առաջին փորձը թաղվեցին նրա հետ։", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Առաջին պաշտոնական թերթը՝ «Թաքվիմ-ի Վեքայի»", "c637f623"], "d": ["Սկսեց հրատարակվել պետության պաշտոնական թերթը. սա ժամանակակից հասարակական կարծիքի և պաշտոնական հաղորդագրությունների ավանդույթի սկիզբն է։", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Բալթա Լիմանիի առևտրային պայմանագիրը", "e790b383"], "d": ["Անգլիային նույնիսկ ներքին առևտրում ճանաչվեց ամենաարտոնյալ դիրք, վերացվեց մենաշնորհի (yed-i vahit) կարգը. մինչ տեղական արտադրությունը մնում էր անպաշտպան, պայմանագիրը դարձավ օսմանյան շուկայի՝ ազատ առևտրին լիովին բացվելու փաստաթուղթը։", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Լիբանանի ամիրայության ավարտը — Բաշիր III Շիհաբի պաշտոնազրկումը", "f85ae454"], "d": ["Քրիստոնյա-դրուզական պայքարը և Շուֆի շրջանի ներքին հավասարակշռությունները չկարողանալով վերահսկել՝ էմիր Բաշիր II-ը (III) 1842 թվականի հունվարին պաշտոնազրկվեց. 1516 թվականից (Մաան-օղլուների և ապա Շիհաբ-օղլուների ձեռքով) շարունակվող տեղական ամիրայության կարգն ավարտվեց, և շրջանն անցավ ուղղակի օսմանյան կառավարման, ապա երկկայմակամության համակարգի։", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Դրամի ուղղումը (Tashîh-i sikke)՝ մեջիդիեի կարգը", "c77be809"], "d": ["Դրամական բարեփոխմամբ հավաքվեցին հարգը խաթարված դրամները. ստեղծվեց ոսկե լիրայի (մեջիդիե) վրա հիմնված կայուն երկմետաղյա կարգ։", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Բաալբեքում Հարֆուշ ընտանիքի տեղական իշխանության ավարտը", "8438f4ae"], "d": ["1521 թվականից (Ջանբիրդի Ղազալիի ապստամբությունից հետո) Բաալբեքում որպես փոքր տեղական հարստություն իշխող Հարֆուշ ընտանիքի ազդեցությունը Բարձր Դռան նոր վարչական կարգավորմամբ ավարտվեց. քաղաքը դարձավ Դամասկոսի վիլայեթին ենթակա սովորական կազայի կենտրոն։", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Հիմնվեց «Շիրքեթ-ի Խայրիյե» ընկերությունը", "462830e7"], "d": ["Բոսֆորում շոգենավեր շահագործելու համար հիմնված ընկերությունը համարվում է առաջին օսմանյան բաժնետիրական ընկերությունը. շոգենավերի նավամատույցներն իրենց կնիքը դրեցին քաղաքային կյանքի վրա։", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Առաջին արտաքին փոխառության պայմանագիրը", "9017c579"], "d": ["Ղրիմի պատերազմի ֆինանսավորման համար Լոնդոնի շուկայից վերցվեց առաջին արտաքին փոխառությունը. 21 տարում 15 փոխառությամբ հասած կետը եղավ 1875 թվականի մորատորիումը և Պետական պարտքի վարչությունը։", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Հեռագրային գիծը Ստամբուլում", "d320f39f"], "d": ["Ղրիմի պատերազմի կարիքներից ելնելով անցկացված առաջին հեռագրային գիծը գործարկվեց. մի քանի տասնամյակում կայսրությունն ունեցավ աշխարհի ամենաընդարձակ հեռագրային ցանցերից մեկը։", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Հողային կանունամեն", "6bae243a"], "d": ["Հողային իրավունքը արդիականացրած կանունամեն պետական հողի (միրի) փաստացի տիրապետումը կապեց տապուի (հողի վկայագրի) հետ. այսօրվա Մերձավոր Արևելքի սեփականության կարգի հիմնարար փաստաթղթերից մեկն է։", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Առաջին դասերը Դարուլֆունունում", "08f74066"], "d": ["Համալսարանական մակարդակի կրթություն տալու կոչված Դարուլֆունունը սկսեց աշխատել հանրային դասախոսություններով. ընդմիջումներով շարունակված հաստատությունը 1900 թվականին վերջնականապես բացվեց և դարձավ Ստամբուլի համալսարանի միջուկը։", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Վիլայեթների կանոնադրությունը", "ad20853b"], "d": ["Էյալեթային կարգի փոխարեն ֆրանսիական օրինակով ստեղծվեց վիլայեթային կազմակերպությունը. Միդհաթ փաշայի Դանուբի վիլայեթի փորձը որպես օրինակ վերցնելով տարածվեց ողջ երկրով։", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Աբդուլազիզի եվրոպական ճանապարհորդությունը", "9ff0fa1e"], "d": ["Օսմանյան փադիշահի խաղաղ նպատակով եվրոպական առաջին ճանապարհորդությունը. Փարիզի ցուցահանդեսը և Լոնդոն այցելությունը ծառայեցին որպես և՛ դիվանագիտության, և՛ արդիականացման ցուցափեղկ։", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Բացվեց Ղալաթասարայի կայսերական լիցեյը", "f9688524"], "d": ["Ֆրանսերենով կրթություն տվող լիցեյը, իր ուսանողական կազմով, որ խտրություն չէր դնում կրոնի և ազգի միջև, դարձավ Թանզիմաթի կրթական հավասարության իդեալի խորհրդանիշը։", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Մեջելլեի առաջին գիրքն ուժի մեջ է", "6475461c"], "d": ["Իսլամական իրավունքի պարտավորությունների և գույքային իրավունքի ոլորտը ժամանակակից օրենսդրական տեխնիկայով ամփոփող Մեջելլեն համարվում է առաջին իսլամական քաղաքացիական օրենսգիրքը. Ջևդեթ փաշայի նախագահությամբ հանձնաժողովը 16 գիրքն ավարտեց 1876 թվականին։", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Աբդուլազիզի գահազրկումը", "eb7397ea"], "d": ["Սահմանադրական կարգի կողմնակից պետական գործիչները և զինվորական ղեկավարությունը անձայն հեղաշրջմամբ գահազրկեցին Աբդուլազիզին. հինգ օր անց նրա կասկածելի մահը և դրան հաջորդած Չըրաղանի դեպքերը ծնեցին տարիներ տևելիք հաշվեհարդարներ։", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Չըրաղանի հարձակումը (Ալի Սուավիի դեպքը)", "d2a9ac87"], "d": ["Լրագրող Ալի Սուավին, Մուրադ V-ին կրկին գահ բարձրացնելու համար, հարձակվեց Չըրաղան պալատի վրա. հարձակումը ճնշվեց արյունալի կերպով, Աբդուլ Համիդի վարչակարգը մշտապես խստացրեց անվտանգության օղակը։", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Հիմնվեց Ռեժի վարչությունը (ծխախոտի մենաշնորհ)", "bad9b030"], "d": ["Ծխախոտի եկամուտները փոխանցվեցին Պետական պարտքի վարչության կազմում գործող օտար կապիտալով Ռեժի ընկերությանը. գյուղացու և պահակների միջև «Ռեժիի մաքսանենգության» ընդհարումները տևեցին տասնամյակներ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Զեյլա։", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Կայզեր Վիլհելմ II-ի այցը Ստամբուլ և Երուսաղեմ", "2988cd06"], "d": ["Գերմանական կայսեր երկրորդ այցը ամրապնդեց օսմանա-գերմանական մերձեցումը. բացվեց Բաղդադի երկաթուղու կոնցեսիայի ճանապարհը, Դամասկոսում հնչեց «երեք հարյուր միլիոն մուսուլմանի բարեկամի» ճառը։", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Հիջազի երկաթուղին Մեդինայում", "95009b9c"], "d": ["Միայն մուսուլմանների նվիրատվություններով և տեղական ինժեներությամբ կառուցված 1464 կմ երկարությամբ գիծը հասավ Մեդինա. ուխտագնացության ճանապարհորդությունը շաբաթներից կրճատվեց օրերի։ Սա Աբդուլ Համիդ II-ի շրջանի ամենամեծ ենթակառուցվածքային գործն է։", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Մարտի 31-ի դեպքը", "1d7c2bb2"], "d": ["Սահմանադրական կարգի դեմ մեծ ապստամբությունը գրավեց Ստամբուլը. Սալոնիկից եկած Գործողությունների բանակը ճնշեց ապստամբությունը, և Աբդուլ Համիդ II-ը գահընկեց արվեց։", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Սկսվեց Էդիրնեի պաշարումը", "234d9b28"], "d": ["Շյուքրյու փաշայի հինգ ամիս տևած պաշտպանությունը դարձավ Բալկանյան աղետի մեջ դիմադրության էպոս. քաղաքն ընկավ սովից, հետ վերցվեց 1913 թվականի հուլիսին։", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Բարձր Դռան հարձակումը", "b304d02d"], "d": ["Էդիրնեն հանձնելու նախապատրաստվող կառավարությունը տապալվեց իթթիհադականների զինված հարձակմամբ. սպանվեց ռազմական նախարար Նազըմ փաշան։ Սկսվեց «Միություն և առաջադիմություն» կոմիտեի լիակատար իշխանության շրջանը։", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Լեռնային Լիբանանի մութասարիֆության վերացումը", "b5639051"], "d": ["1861 թվականի Règlement organique-ով հիմնված և 1864 թվականին վերանորոգված միջազգային արձանագրության վրա հիմնված ինքնավար մութասարիֆության կարգը Առաջին համաշխարհային պատերազմի ժամանակ Օսմանյան պետության կողմից միակողմանիորեն չեղարկվեց. ներքին գործերի նախարարությունը սկսեց շրջան ուղղակիորեն նշանակել մուսուլման մութասարիֆներ։ Այսպիսով փակվեց 1861-1915 թվականների ինքնավարության շրջանը, որի ընթացքում պաշտոնավարեցին ութ մութասարիֆ։", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Երկրի բաժանումը շահզադեների միջև", "82f26bfb"], "d": ["Անկարայի ջախջախումից հետո Սուլեյման Չելեբին անցավ Ռումելի և Էդիրնեում հռչակեց սուլթանություն. Իսա Չելեբին իր ձեռքում պահեց Բուրսան, իսկ Չելեբի Մեհմեդը՝ Ամասիա-Թոքաթ-Սեբաստիա շրջանը։ Քարտեզում այս երեք բաժինները ցույց են տրվում առանձին գույներով։", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Գելիբոլուի պայմանագիրը՝ Սև ծովի ափը մինչև Մեսեմբրիա թողնվեց Բյուզանդիային", "a4164eca"], "d": ["Անկարայի ջախջախումից հետո Ռումելիում դիմանալ ցանկացող էմիր Սուլեյմանը Գելիբոլուում պայմանագիր ստորագրեց բյուզանդական կայսր Մանուելի հետ։ Նա Բյուզանդիային թողեց Քարթալը, Պենդիկը և Գեբզեն ու որոշ կղզիներ, Ռումելիում՝ Սալոնիկը և Թեսալիան, Սև ծովում՝ մինչև Մեսեմբրիա ձգվող ափամերձ շերտը. վերացվեց նաև այն հարկը, որ Բյուզանդիան վճարում էր օսմանցիներին։ Ստրանջայի ափի Ահտոպոլը, Իղնեադան և Ռեզվեն այսպիսով քսանմեկ տարի մնացին բյուզանդական կառավարման տակ. Մուրադ II-ը 1424 թվականի հաշտությամբ հետ վերցրեց այս վայրերի մեծ մասը։", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Յըլդըրըմ Բայազիդի մահը գերության մեջ", "7e968d83"], "d": ["Թեմուրի գերության մեջ գտնվող փադիշահը մահացավ Աքշեհիրում. նրա դին բերվեց Բուրսա և թաղվեց։ Նրա մահը շահզադեների միջև գահակալական պայքարը դարձրեց անշրջելի։", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Գելիբոլուի պայմանագիրը — զիջումներ Բյուզանդիային", "dfacbd00"], "d": ["Ռումելիում իր դիրքն ապահովել ցանկացող Սուլեյման Չելեբին, համաձայնության գալով Բյուզանդիայի և լատինական պետությունների հետ, վերադարձրեց Սալոնիկը, Մարմարայի ափերը և որոշ կղզիներ. նա նույնիսկ համաձայնեց խարաջ վճարել։", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Ուլուբաթի ընդհարումը — Իսա Չելեբիի պարտությունը", "500c5d24"], "d": ["Բուրսան ձեռքում պահող Իսա Չելեբին Ուլուբաթում պարտվեց եղբորը՝ Մեհմեդին. վերականգնվելու մի քանի փորձն էլ անարդյունք մնաց։", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Իսա Չելեբիի վերանալը ասպարեզից", "0effa11e"], "d": ["Սուլեյման Չելեբիի աջակցությամբ մի քանի անգամ Անատոլիա վերադարձած Իսա Չելեբին իր վերջին պարտությունից հետո անհետացավ. նրա բաժինն անցավ Չելեբի Մեհմեդին, և քարտեզում Մեհմեդի տարածքն ընդարձակվեց դեպի արևմուտք։", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Մուսա Չելեբին անցավ Վալախիա", "8441267a"], "d": ["Սուլեյման Չելեբիի դեմ Բուրսան և Անկարան կորցրած ու Թոքաթ-Ամասիա նահանջած Չելեբի Մեհմեդը եղբորը՝ Մուսային, խրախուսեց գնալ Ռումելի։ Մուսան, ընդունելով Վալախիայի վոյևոդ Միրչայի հրավերը, ծովով հասավ Վալախիա. այստեղից նա ձեռնամուխ էր լինելու պայքարի, որը Սուլեյմանին թողնելու էր երկու ճակատի միջև։", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Չելեբի Մեհմեդը կրկին գրավեց Բուրսան և Անկարան — անատոլիական բաժինը դուրս եկավ Սուլեյման Չելեբիի ձեռքից", "bfb69f12"], "d": ["Մուսա Չելեբիի՝ Ռումելիում հաջողությունների (Յամբոլ, 1410 թվականի փետրվարի 13) առիթով Անատոլիայում գտնվող էմիր Սուլեյման Չելեբին անցավ Ռումելի։ Անատոլիայից Սուլեյմանի հեռանալուց հետո Մեհմեդ Չելեբին կրկին գրավեց Բուրսայի շրջանը՝ ներառյալ Անկարան, և որպես գահ բարձրանալու նշան հատեց 813 թվականով դրամ։ Քարտեզում Մարմարայի անատոլիական ափը էմիր Սուլեյմանի բաժնից անցնում է Չելեբի Մեհմեդի գույնին։", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Կոսմիդիոնի ճակատամարտը", "0efc2caa"], "d": ["Բյուզանդական աջակցությամբ Ստամբուլի պարիսպների առջև մղված ճակատամարտում Սուլեյման Չելեբին հաղթեց եղբորը՝ Մուսային. սակայն Ռումելիում նրա աջակցությունն արդեն սկսել էր արագորեն հալվել։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Ալասոնյա (Elassona), Այդոս (Aytos), Բոլայիր (քարտեզում Ռումելիում Մուսայից Սուլեյմանին անցած վայրերը)։", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Մուսա Չելեբիի Ստամբուլի պաշարումը", "4932f586"], "d": ["Սուլեյմանին աջակցած Բյուզանդիային պատժել ցանկացող Մուսա Չելեբին պաշարեց Ստամբուլը. այս պաշարումը Բյուզանդիային մղեց դաշինքի Չելեբի Մեհմեդի հետ։", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Էմիր Սուլեյմանի մահը — Մուսան՝ Ռումելիի տեր", "325c1549"], "d": ["Էդիրնեից փախչելիս բռնված Սուլեյման Չելեբին սպանվեց. ամբողջ Ռումելին անցավ Մուսա Չելեբիի ձեռքը։ Քարտեզում Ռումելին կապույտ գույնից դառնում է մանուշակագույն։", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Չամուրլուի ճակատամարտը — միասնության վերականգնումը", "0b23173e"], "d": ["Բյուզանդիայի, Սերբական դեսպոտության և Ռումելիի բեյերի աջակցությունն ստացած Չելեբի Մեհմեդը Չամուրլուում վճռական պարտության մատնեց եղբորը՝ Մուսային. Մուսան սպանվեց փախչելիս։ Մուսայի ձեռքում եղած Ռումելին Էդիրնեի հետ անցավ Մեհմեդին, և Մեհմեդ Չելեբին Էդիրնեում իրեն հռչակեց Օսմանյան պետության միակ տիրակալ։ Տասնմեկամյա միջգահակալության շրջանն ավարտվեց, և քարտեզի շահզադեական բաժինները միավորվեցին մեկ մարմնի մեջ։", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Վիեննայի արշավանքի որոշումը — Վաշվարի հաշտությունը չվերանորոգվեց, թիրախը Դյորից (Յանըքքալե) տեղափոխվեց Վիեննա", "1bf278f2"], "d": ["Լեոպոլդ I կայսրը ցանկանում էր վերանորոգել Վաշվարի պայմանագիրը, որի ժամկետը դեռ չէր լրացել, և Մեհմեդ IV-ը ևս խաղաղության կողմնակից էր թվում։ Իսկ մեծ վեզիր Մերզիֆոնցի Կարա Մուստաֆա փաշան, պատճառաբանելով Միջին Հունգարիայի թագավոր հռչակել տված Իմրե Թյոքյոլիի գանգատները, թույլ չտվեց վերանորոգել հաշտությունը. գլխավորապես Վանի Մեհմեդ էֆենդիին և քարոզիչներին շարժման մեջ դնելով՝ համոզեց փադիշահին պատերազմել։ Անցկացված խորհրդակցությունում որոշվեց, որ փադիշահը մնա Բելգրադում, իսկ գլխավոր սերդարը առաջանա Դյորը գրավելու. սակայն Սեկեշֆեհերվարի (İstolni Belgrad) խորհրդակցությունում, չնայած Ղրիմի խան Մուրադ Գիրեյի և Բուդայի կուսակալ Ուզուն Իբրահիմ փաշայի առարկություններին, թիրախը փոխվեց Վիեննայի պաշարման։", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Սկսվեց Վիեննայի երկրորդ պաշարումը — բանակը Վիեննայի մոտ է", "bb542e49"], "d": ["Մեծ վեզիր Կարա Մուստաֆա փաշայի հրամանատարությամբ օսմանյան բանակը 1683 թվականի հուլիսի 14-ին հասավ Վիեննայի մատույցները։ Լեոպոլդ I կայսրը, քաղաքի պաշտպանությունը թողնելով Շտարհեմբերգին, նահանջեց Ավստրիայի խորքերը։ Ի տարբերություն առաջինի՝ ուղղակիորեն Վիեննան թիրախ դարձրած այս երկրորդ պաշարումը տևելու էր մինչև սեպտեմբերի 12-ը։", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Պարկանի ջախջախումը և Էստերգոմի կորուստը", "a7366740"], "d": ["Վիեննայից նահանջող բանակը Պարկանում երկրորդ անգամ ջախջախվեց. ապա ընկավ Հունգարիայի բանալի ամրոցներից Էստերգոմը։ Նահանջը սկսեց վերածվել փլուզման։", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Մերզիֆոնցի Կարա Մուստաֆա փաշայի մահապատիժը", "ce8b10ac"], "d": ["Վիեննայի ջախջախման մեղավոր համարված մեծ վեզիրը խեղդամահ արվեց Բելգրադում. սակայն նրա մահապատիժը ո՛չ ճակատը շտկեց, ո՛չ էլ վերադարձրեց պետության խարխլված հեղինակությունը։", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Կազմվեց Սրբազան լիգան", "060280d0"], "d": ["Պապականության նախաձեռնությամբ Ավստրիայի, Լեհաստանի և Վենետիկի միջև օսմանցիների դեմ կազմվեց Սրբազան լիգան. 1686 թվականին միացավ նաև Ռուսաստանը։ Այսպիսով կայսրությունը մտավ տասնվեց տարի տևելիք բազմաճակատ պատերազմի մեջ։", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Բուդայի առաջին պաշտպանությունը", "ccc43630"], "d": ["Սրբազան լիգայի բանակի Բուդայի առաջին պաշարումը հետ մղվեց ամրոցի չորս ամիս տևած համառ պաշտպանությամբ. սակայն Հունգարիայի ամրոցները շարունակում էին ընկնել մեկը մյուսի հետևից։", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Ույվարի կորուստը", "689ab78c"], "d": ["Քսաներկու տարի օսմանյան ձեռքում մնացած և Եվրոպայում առածի վերածված Ույվարի ամրոցն ընկավ. օսմանյան ներկայությունը Վերին Հունգարիայում քայքայվեց։", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Թյոքյոլիի ձերբակալությունը Վարադում — Միջին Հունգարիայի թագավորությունը ցրվեց, Վերին Հունգարիայի ամրոցները հանձնվեցին", "1741aaaf"], "d": ["Վիեննայի ջախջախումից հետո օսմանցիները սկսել էին Թյոքյոլիին ևս համարել պատերազմի և պարտության պատճառ դարձածների թվում։ 1685 թվականի հոկտեմբերի 15-ին սերդար Մելեք Իբրահիմ փաշայի հրամանով Վարադի բեյլերբեյ Ահմեդ փաշան ձերբակալել տվեց օգնության եկած Թյոքյոլիին. հույս կար նրան հանձնելով Հաբսբուրգներին ձեռք բերել ավելի լավ խաղաղության պայմաններ։ Երբ տարածվեց ձերբակալության լուրը, բացի նրա կնոջ՝ Իլոնա Զրինիի պաշտպանած Մունկաչից, Միջին Հունգարիայի թագավորության բոլոր ամրոցներն ու քաղաքները հանձնվեցին Հաբսբուրգներին. կուրուց զինվորների մեծ մասն անցավ հաբսբուրգյան բանակ։ Երբ Թյոքյոլին 1686 թվականի հունվարի 2-ին Բելգրադում ազատ արձակվեց, թագավորությունն արդեն վերացել էր։", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Բուդայի կորուստը — 145-ամյա հունգարական մայրաքաղաքը", "70800e2b"], "d": ["Յոթանասունութ օր տևած պաշարման վերջում Բուդան ընկավ. վերջին բեյլերբեյ Աբդուրռահման Աբդի փաշան նահատակվեց պարիսպների վրա։ 1541 թվականից օսմանյան կառավարման տակ գտնվող քաղաքի կորուստը համարվում է Հունգարիայի ձեռքից գնալու խորհրդանիշ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Պեշտ։", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Մոհաչի երկրորդ (Հարշանի) ջախջախումը — Տրանսիլվանիայի և Մոհաչի կորուստը", "a7922681"], "d": ["1526 թվականին մեծ հաղթանակ տարած դաշտում այս անգամ ծանր պարտություն կրեցին. բանակը ցրվեց, ապստամբած զինվորները պաշտոնազրկել տվեցին մեծ վեզիրին։ Պարտությունը հանգեցրեց նաև Տրանսիլվանիայի կորստին։", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Աթենքի կորուստը և Պարթենոնի պայթյունը", "b6691730"], "d": ["Վենետիկյան հրետանու արձակած ռումբը օդ հանեց Պարթենոնը, որն օսմանցիներն օգտագործում էին որպես զինապահեստ. երկու հազարամյա տաճարը վերածվեց ավերակի։ Քաղաքն անցավ Վենետիկի ձեռքը (հետ վերցվելու է 1688 թվականին)։", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Մեհմեդ IV-ի գահազրկումը և Սուլեյման II-ի գահակալումը", "9f53037c"], "d": ["Ճակատի աղետների և բանակի ապստամբության հետևանքով 39-ամյա գահակալությունից հետո Մեհմեդ IV-ը գահազրկվեց. նրա փոխարեն գահ բարձրացվեց քառասուն տարի «վանդակում» (kafes) պահված նրա եղբայր Սուլեյման II-ը։", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Բելգրադի առաջին կորուստը — Սրբազան լիգայի պաշարումը", "c6b9b19a"], "d": ["1521 թվականից օսմանյան ձեռքում գտնվող Բելգրադը հանձնվեց Սրբազան լիգայի բանակին. Սերբիայի դարպասները բացվեցին թշնամու առաջ, և վտանգը հասավ Նիշ-Սոֆիա գծին։ Նույն ամսաթվին ատլասում Օսմանյան պետությունից Հաբսբուրգներին անցած մյուս բնակավայրը՝ Հիսարջըք (Գրոցկա). հետևում է Բելգրադի ավագ կենտրոնի շղթային (TDV belgrad. հայտարարված մոտավորություն)։", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Բադենը Պոժարևացի մոտ անցավ Մորավան — Պոժարևացն անցավ Ավստրիային", "bcf3fc59"], "d": ["Բադենի մարկգրաֆ Լյուդվիգը 1689 թվականի օգոստոսին Պոժարևացի մոտ անցնելով Մորավան՝ առաջացավ դեպի Նիշ. քաղաքը մինչև 1690 թվականի ամառը մնաց Ավստրիայի ձեռքում (TDV suleyman-ii-ն ասում է, որ Պոժարևացը հետ վերցվել է 1690 թվականին)։ Օրը և Ռյոդերի ընթերցումը այս նիստում վերստին չեն հաստատվել։", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Նիշի կորուստը — հաբսբուրգյան (Հունգարիայի թագավորության թագի) առաջխաղացումը, ամենակրիտիկական տարին", "c5e27b3f"], "d": ["Հաբսբուրգյան (Հունգարիայի թագավորության թագի) առաջխաղացումը Նիշը ևս հանեց օսմանյան կառավարումից. ասպատակությունները հասան մինչև Սկոպյե և Պրիշտինա։ Իսկ Վիդինն ընկավ դրանից հետո՝ 1689 թվականի հոկտեմբերին (առանձին գրառում)։ Պատերազմի ամենամութ տարում պետությունն իրեն սպառնալիքի տակ զգաց նույնիսկ մայրաքաղաքում։", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Օրշովան և Ֆեթհյուլիսլամը վերցվեցին ավստրիական կայազորի տակ", "ee8dd875"], "d": ["Վիդինի առանց կռվի գրավումից (1689 թվականի հոկտեմբեր, TDV vidin) հետո Բադենը 1689 թվականի հոկտեմբերի 25-ին վերանորոգեց Օրշովան և Ֆեթհյուլիսլամը ու կայազոր տեղադրեց. Օրշովան մինչև 1690 թվականի աշունը մնաց Ավստրիային։ Օրը հիմնված է Bánlaky/Röder-ի վրա, այս նիստում վերստին չի հաստատվել։", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Նիշը կրկին օսմանյան է", "0c4f44eb"], "d": ["Ֆազըլ Մուստաֆա փաշան 1690 թվականի հուլիսին ելավ արշավանքի. Շեհիրքյոյը, Պոժարևացը և Գյուվերջինլիքը գրավելուց հետո պաշարված Նիշը 1690 թվականի սեպտեմբերի 27-ին անցավ օսմանցիների ձեռքը (TDV semendire)։ Նույն ժամանակ հետ էր վերցվել նաև Վիդինը։ Նույն ամսաթվին ատլասում Հաբսբուրգներից օսմանցիներին վերադարձած մյուս բնակավայրեր՝ Յագոդինա (Jagodina) և Պրոկուպլյե (Prokuplje). քանի որ բնակավայրի մակարդակով օրը չի գտնվել, վերցված է Նիշի օրը (TDV semendire. հայտարարված մոտավորություն. Röder 1842-ը գրում է, որ վեզիրը Յագոդինայով անցել է սեպտեմբերի 8-24-ին, հակասությունը լուծված չէ)։", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Սմեդերևոյում ավստրիական զորամասերը հանձնվեցին", "90da20c4"], "d": ["1690 թվականի սեպտեմբերի 27-ին Նիշի գրավումից հետո չորսօրյա պաշարմամբ Սմեդերևոյի ավստրիական զորամասերը հանձնվեցին (TDV semendire)։ Bánlaky/Röder-ը նշում են սեպտեմբերի 24. աղբյուրները հակասում են, հիմք ընդունվեց TDV-ն։", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Բելգրադը հետ վերցվեց", "ab435838"], "d": ["Մեծ վեզիր Քյոփրյուլյուզադե Ֆազըլ Մուստաֆա փաշան 1690 թվականի հոկտեմբերի 8-ին Բելգրադը հետ վերցրեց Ավստրիայից. 1688 թվականին կորցրած քաղաքն այսպիսով վերադարձավ օսմանցիներին (TDV suleyman-ii)։ Նույն ամսաթվին ատլասում Հաբսբուրգներից օսմանցիներին վերադարձած մյուս բնակավայրը՝ Հիսարջըք (Գրոցկա). հետևում է Բելգրադի ավագ կենտրոնի շղթային (TDV suleyman-ii. հայտարարված մոտավորություն)։", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Սլանկամենի ջախջախումը — Ֆազըլ Մուստաֆա փաշան նահատակվեց", "10d626f1"], "d": ["Դարի ամենաարյունալի դաշտային ճակատամարտերից մեկում մեծ վեզիրը ճակատին ստացած գնդակից նահատակվեց. բանակը ցրվեց։ Վերականգնվելու հույսը մարեց այս ճակատամարտի հետ։", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Քիոս կղզու կորուստը", "07c084f8"], "d": ["Վենետիկյան նավատորմը գրավեց Քիոսը. օսմանյան տիրապետությունը Էգեյան ծովում հայտնվեց սպառնալիքի տակ։ Կղզին հաջորդ տարի հետ վերցվելու էր։", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Մուստաֆա II-ի՝ անձամբ արշավանքի ելնելու որոշումը", "61c3ba9c"], "d": ["Նոր փադիշահը, հետևելով իր նախնիների ուղուն, հայտարարեց, որ բանակի գլուխ անցած արշավանքի կելնի. այս որոշումը բարձրացրեց բանակի ոգին և սկիզբ դրեց երկու տարի տևելիք անձնական արշավանքների շրջանին։", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Քիոսի հետգրավումը", "6b496fca"], "d": ["Քոյուն կղզիների ծովամարտերում վենետիկյան նավատորմին հաղթած Մեզոմորտո Հուսեյն փաշան հետ վերցրեց Քիոսը. սա դարձավ օսմանյան ծովագնացության կարճատև վերածննդի նշան։", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Լուգոժի հաղթանակը — Մուստաֆա II-ի առաջին ավստրիական արշավանքը", "d5ee9b34"], "d": ["Փադիշահի անձամբ մասնակցած առաջին արշավանքում հետ վերցվեց Լիպովան, իսկ Լուգոժում պարտության մատնվեցին ավստրիական ուժերը. տարիներ շարունակ ձգվող պարտությունների շղթայում տեղի ունեցավ առաջին բեկումը։ Ատլասը նաև Կարանշեբեշը (Caransebeş) այս արշավանքում համարում է Հաբսբուրգներից օսմանցիներին վերադարձած. աղբյուրը տալիս է միայն 1695 թվականի սեպտեմբերը (TDV mustafa-ii), ատլասի օրը վերցված է Լուգոժի գրառումից (հայտարարված մոտավորություն)։", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Ազովի ամրոցի կորուստը", "2b78b5cd"], "d": ["Սև ծով դուրս գալու նպատակ ունեցող Պետրոս I-ը իր երկրորդ պաշարման ժամանակ գրավեց Ազովը. Ռուսաստանն առաջին անգամ մշտապես հաստատվեց օսմանյան ամրոցում և ծովային ուժ դառնալու ճանապարհին արեց իր առաջին քայլը։", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Ուլաշի (Olaşin) հաղթանակը", "02ac9ca8"], "d": ["Փադիշահի երկրորդ արշավանքում Դանուբի ափին տարած հաղթանակը խափանեց Տեմեշվարը գրավելու ավստրիական ծրագիրը. սակայն պատերազմի ընդհանուր հավասարակշռությունը չփոխեց։", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Զենտայի ջախջախումը — որոշվեց պատերազմի ճակատագիրը", "475c4a7b"], "d": ["Տիսա գետն անցնելիս բանակը ենթարկվեց արքայազն Եվգենիի հանկարծակի հարձակմանը. գետի երկու ափերին բաժանված ուժերը մի քանի ժամում ոչնչացվեցին, զոհվեցին հազարավոր զինվորներ և պետական գործիչներ, այդ թվում՝ մեծ վեզիր Էլմաս Մեհմեդ փաշան։ Օսմանյան պատմության ամենածանր ջախջախումներից մեկը եղած Զենտան խաղաղության բանակցությունների սեղանն անխուսափելի դարձրեց։", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Սկսվեցին Կառլովիցի խաղաղության բանակցությունները", "1f395cf3"], "d": ["Անգլիայի և Հոլանդիայի միջնորդությամբ սկսված բանակցություններում օսմանյան պատվիրակությունն առաջին անգամ ստիպված եղավ ընդունել «uti possidetis» (ինչ ձեռքում է, մնում է) սկզբունքը. յոթանասուներկու նիստ տևած բանակցությունները համարվում են ժամանակակից օսմանյան դիվանագիտության ծնունդը։", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Կավալացի Մուհամմեդ Ալին ոտք դրեց Եգիպտոս", "514c943f"], "d": ["Ֆրանսիական օկուպացիայի տակ գտնվող Եգիպտոսը հետ վերցնելու ուղարկված օսմանյան բանակի մեջ կար նաև Կավալայից հավաքված կամավորների ջոկատ։ Երեսունն անց Մուհամմեդ Ալին այդ ջոկատի երկրորդ հրամանատարն էր. նա Եգիպտոս ոտք դրեց ոչ թե որպես կուսակալ, այլ որպես վաշտի սպա։", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Ալբանացի զինվորները տապալեցին Եգիպտոսի կուսակալին", "c76a0ec2"], "d": ["Ռոճիկները չստացած ալբանական զորամասերը ապստամբեցին և Խյուսրև փաշա կուսակալին ստիպեցին փախչել ամրոցից։ Ֆրանսիացիների նահանջով առաջացած դատարկության մեջ մամլուք բեյերը, ալբանական զորաբանակը և Բարձր Դռան նշանակած կուսակալները եռանկյուն պայքարի մեջ մտան. Մուհամմեդ Ալին այս եռանկյունու մեջ հավասարակշռություններ ստեղծելով առաջ եկավ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Թաիֆ։", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Կահիրեի ուլեմաները Մուհամմեդ Ալիին հռչակեցին կուսակալ", "a16752f2"], "d": ["Հարկային ճնշումից տառապող Կահիրեի արհեստավորներն ու ուլեմաները նաքիբ ուլ-աշրաֆ Օմար Մաքրամի առաջնորդությամբ ապստամբեցին, հայտարարեցին, որ չեն ճանաչում Խուրշիդ փաշա կուսակալին, և Մուհամմեդ Ալիին նստեցրին կուսակալի աթոռին։ Օսմանյան պատմության մեջ կուսակալի՝ ժողովրդի կողմից ընտրվելը հազվագյուտ իրադարձություն է։", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Բարձր Դուռն ընդունեց կատարված փաստը՝ Եգիպտոսի կուսակալության ֆերմանը", "b86736a3"], "d": ["Եգիպտոսում իր թեկնածուին պահելու ուժ չունեցող Բարձր Դուռը Մուհամմեդ Ալիին վեզիրության աստիճանով ուղարկեց Եգիպտոսի կուսակալության ֆերմանը։ Քարտեզում Եգիպտոսը այս ամսաթվից սկսած անցնում է ենթակա (բաց երանգի) շերտ. իրավաբանորեն օսմանյան հող է, փաստացի՝ Կավալացու հարստության երկիր։ Նույն ամսաթվին ենթակա շերտ անցած այլ բնակավայրեր՝ Կահիրե, Ալեքսանդրիա, Դամիետտա, Ասյուտ, Ասուան, Իբրիմ, Սուեզ, Ռաշիդ (Rosetta)։", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Անգլիական Ֆրեյզերի արշավախումբը ափ իջավ Ալեքսանդրիայում", "4d6c31be"], "d": ["Օսմանյան պետության՝ Ֆրանսիային մերձենալուն ի պատասխան՝ Անգլիան Եգիպտոս ուղարկեց ափհանման ուժ։ Մուհամմեդ Ալին այդ ժամանակ Վերին Եգիպտոսում զբաղված էր մամլուքներով. արագ վերադառնալով՝ կազմակերպեց պաշտպանությունը։", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Ռաշիդի (Rosetta) ջախջախումը — անգլիացիները հետ մղվեցին", "3636004c"], "d": ["Ռաշիդ ավան մտած անգլիական շարասյունը փողոցային ընդհարումներում ծանր կորուստներ ունեցավ. սեպտեմբերին ուժերը ամբողջությամբ լքեցին Եգիպտոսը։ Այս հաղթանակը ամրապնդեց Մուհամմեդ Ալիի հեղինակությունը թե՛ Եգիպտոսում, թե՛ Ստամբուլում։", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Ամրոցի դեպքը՝ մամլուք բեյերի ոչնչացումը", "84030b97"], "d": ["Հիջազի արշավանքի առիթով կազմակերպված հանդիսավոր շքերթին հրավիրված մամլուք բեյերը Կահիրեի ամրոցի նեղ անցուղում թակարդն ընկնելով ոչնչացվեցին։ Այսպիսով ավարտվեց հինգդարյա մամլուքական ազդեցությունը, և Եգիպտոսում Մուհամմեդ Ալիի առաջ մրցակից չմնաց։", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Սկսվեց Հիջազի արշավանքը — բանակը ծովով Սուեզից, իսկ ուխտագնացության ճանապարհով ցամաքով շարժվեց Յանբու", "1c05c159"], "d": ["1803 թվականից սաուդյան-վահաբիական կառավարման տակ գտնվող երկու սրբավայրերը (Հարամեյնը) հետ վերցնելը Մահմուդ II-ի լեգիտիմության ամենամեծ խնդիրն էր. երբ Բարձր Դռան ուժերը չբավարարեցին, առաջադրանքը տրվեց Եգիպտոսի կուսակալին։ Մուհամմեդ Ալին բանակի գլուխ ուղարկեց իր տասնվեցամյա որդի Թուսունին։", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Յանբուն հանձնվեց — Հիջազի արշավանքի առաջին ափամերձ հենակետը", "179bc78d"], "d": ["Սուեզից նորակառույց նավերով ճանապարհ ընկած շուրջ երկու հազար ալբանացի հետևակը 1811 թվականի հոկտեմբերին ափ իջավ Յանբուի մոտ. ավանը երկու օրվա թույլ դիմադրությունից հետո հանձնվեց։ Թուսունի հրամանատարությամբ հեծելազորը ցամաքով հետևեց ուխտագնացության ճանապարհին և Աքաբայի և Վաջհի վրայով Յանբու հասավ միայն երկու շաբաթ անց։ Յանբուն դարձավ Մեդինայի և Մեքքայի վրա շարժվելիք եգիպտական բանակի առաջին հենակետը Հիջազում։", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Առաջին ջախջախումը Սաֆրա-Ջեդիդեի կիրճում", "99ef804d"], "d": ["Նեղ լեռնային անցումներում դարանի մեջ ընկած եգիպտական առաջապահ ուժը ցրվեց։ Պարտությունը դարձավ արշավանքի մարտավարական դասը. հասկացվեց, որ առանց բեդվին ցեղերի աջակցության Հիջազում առաջանալ հնարավոր չէ։", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Մեդինան հետ վերցվեց", "6f6a5d55"], "d": ["Երկարատև պաշարումից հետո Մեդինան հանձնվեց։ Մարգարեի քաղաքի հետգրավումը Ստամբուլում նշվեց թնդանոթային տոնախմբություններով. Մուհամմեդ Ալիին որպես պարգև տրվեց նաև Ջիդդայի կուսակալությունը։", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Մեքքան հետ վերցվեց — բացվեց ուխտագնացության ճանապարհը", "3d6d66a0"], "d": ["Մեքքա մտած եգիպտական ուժերը Քաաբայում կրկին օսմանյան փադիշահի անունով խուտբա կարդացնել տվին։ Տասը տարի ընդհատված ուխտագնացության քարավանները կարողացան կրկին ճանապարհ ընկնել։ Քարտեզում Հիջազը վերադառնում է օսմանյան տիրապետության, սակայն քանի որ կառավարումը Կահիրեում էր, ցույց է տրվում ենթակայության երանգով։ Նույն ամսաթվին ենթակա կառավարման անցած այլ վայր՝ Ջիդդա։", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Թաիֆի հետգրավումը — Հիջազի արշավանքի ավարտը", "6315fb31"], "d": ["Մեդինայից (1812 թվականի դեկտեմբեր) և Մեքքայից (1813 թվականի հունվար) հետո Թուսուն փաշայի հրամանատարությամբ եգիպտական բանակը վերջինը Թաիֆը հետ վերցրեց վահաբիներից։ Տասը տարի տևած սաուդյան տիրապետությունն ավարտվեց, և Հիջազի բոլոր երեք սրբազան կենտրոնները կրկին անցան օսմանա-եգիպտական վերահսկողության տակ։", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Մուհամմեդ Ալին անձամբ անցավ Հիջազ", "fda0ea2d"], "d": ["Տեսնելով, որ արշավանքը դանդաղ է ընթանում, կուսակալը կառավարումը վերցրեց իր ձեռքը. ցեղապետերի հետ սակարկելով՝ փորձեց ներսից քայքայել սաուդյան ճակատը։ Այս արշավանքով մեծացավ նաև Եգիպտոսի մասնաբաժինը Կարմիր ծովի առևտրում։", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Բիսելի ճակատամարտը՝ սաուդյան ուժերը ջախջախվեցին", "9c9ab91f"], "d": ["Դաշտային ճակատամարտում ծանր պարտություն կրած սաուդները նահանջեցին ներքին շրջաններ։ Կնքված զինադադարը կայուն չեղավ. երկու տարի անց գործողությունները տեղափոխվելու էին Նեջդի սիրտը։ Ատլասը այս հաղթանակից հետո Թաիֆից արևելք գտնվող Թուրաբան և Խուրման համարում է սաուդյան ձեռքից դուրս եկած (իրադարձության աղբյուրը՝ Lorimer, Gazetteer. բնակավայրերին հատուկ վկայությունը և հունվարի 13 օրը հայտարարված մոտավորություն են)։", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Իբրահիմ փաշան ելավ Նեջդի արշավանքի", "d5ed80d1"], "d": ["Եղբոր՝ Թուսունի մահից հետո հրամանատարությունն ստանձնած Իբրահիմ փաշան անապատում ձեռնամուխ եղավ երկու տարի տևած ծանր երթի։ Ջրհոր առ ջրհոր առաջացող բանակը, ցեղերին մեկ առ մեկ վերացնելով, հասավ սաուդյան մայրաքաղաքի մատույցները։", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Դիրիյան ընկավ — առաջին սաուդյան պետությունն ավարտվեց", "aa96206d"], "d": ["Վեց ամիս տևած պաշարումից հետո Դիրիյան հանձնվեց և ավերվեց։ Էմիր Աբդուլլահ իբն Սաուդը ուղարկվեց Ստամբուլ և մահապատժի ենթարկվեց։ Օսմանյան դրոշն առաջին անգամ այդքան խորը հասավ Արաբիայի ներսը. Նեջդի կայազորը մնաց մինչև 1824 թվականը։ Նույն ամսաթվին միացած այլ վայրեր՝ Դիրիյա (Նեջդ)։", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Սկսվեց Սուդանի արշավանքը", "b1fc6905"], "d": ["Մուհամմեդ Ալիի նպատակը եռակի էր՝ բանակի համար զինվոր հավաքել, հասնել Սեննարի ոսկուն և ոչնչացնել մամլուքների փախած մնացորդները։ Նրա որդի Իսմայիլ փաշայի հրամանատարությամբ ուժը, հետևելով Նեղոսին, իջավ հարավ։", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["Դոնգոլան առանց բռնության անցավ եգիպտական բանակին (մամլուքները լքել էին այն 1820 թվականի հունիսին)", "bc5942c0"], "d": ["Նեղոսի մեծ ոլորանի վրա գտնվող Դոնգոլան, 1820 թվականի հունիսին մամլուքների լքելուց հետո, առանց բռնության անցավ Իսմայիլ փաշայի եգիպտական բանակի ձեռքը։ Քարտեզում Սուդանը այս ամսաթվից հայտնվում է ենթակայության շերտում. նվաճողը Կահիրեն է, կառավարողն էլ լինելու է Կահիրեն։", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["Ջաբալ ադ-Դայքայի ճակատամարտը — Շայքիյա դաշնությունը վճռական պարտություն է կրում եգիպտական բանակից", "befc9539"], "d": ["Մուհամմեդ Ալի փաշայի որդի Իսմայիլ փաշայի բանակը Քուրտիի առաջին ընդհարումից մեկ ամիս անց Ջաբալ ադ-Դայքայի մոտ երկրորդ և վճռական ճակատամարտում հաղթեց Շայքիյային։ Շայքիյայի առաջնորդ Մաքք Սուբայրը հանձնվեց. Մաքք Շավիշը շարունակեց դիմադրությունը։ Եգիպտոսի տիրապետությունը Նեղոսի ոլորանում դրանից հետո դարձավ մշտական։", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Սեննարի (Ֆունջ) սուլթանությունը հանձնվեց", "3cac7dd2"], "d": ["Երեքդարյա Ֆունջ հարստությունը հանձնվեց առանց ընդհարման։ Նույն տարի Նեղոսի երկու ճյուղերի միախառնման կետում հիմնված ռազմակայանը կարճ ժամանակում վերածվեց Սուդանի վարչական կենտրոն Խարտումի։ Նույն ամսաթվին միացած այլ վայրեր՝ Սեննար։", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Գրավվեց Կորդոֆանը", "06440602"], "d": ["Արևմուտք ուղարկված երկրորդ շարասյունը Բարայում (Bâra) պարտության մատնեց Դարֆուրի ուժերին և գրավեց Կորդոֆանը՝ Նուհուդի շրջակայքի հետ։ Այսպիսով Եգիպտոսի տիրապետությունը Սուդանում Նեղոսի հովտից ընդարձակվեց դեպի արևմտյան տափաստաններ։", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Եգիպտական ուժերը ափ իջան Կրետեում", "835aee90"], "d": ["Երբ հունական ապստամբությունը տարածվեց Կրետե, Բարձր Դուռը խնդրեց եգիպտական ուժ ուղարկել կղզի։ Մուհամմեդ Ալիի ազդեցությունը կղզում սկսվեց այս միջամտությամբ և ութ տարի անց ավարտվեց նրան Կրետեի կուսակալությունը տալով։", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Իսմայիլ փաշայի սպանությունը Շենդիում", "223860c9"], "d": ["Ծանր հարկերի և զինվոր պահանջելու դեմ զայրացած տեղական էմիր Նիմրը, հրկիզելով նրա իջևանած տունը, այրեց Իսմայիլ փաշային և նրա շքախումբը։ Վրեժխնդրության արշավանքը շրջանը վերածեց արյան լճի. դրանից հետո Սուդանի կառավարումը հիմնվեց խստության վրա։", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Մահմուդ II-ը Մորեայի համար օգնություն խնդրեց Մուհամմեդ Ալիից", "03594a42"], "d": ["Ենիչերիական բանակով երեք տարում չճնշվող Մորեայի ապստամբության համար փադիշահը դիմեց եվրոպական ձևով մարզված եգիպտական բանակին։ Փոխարենը խոստացվեց Մորեայի կուսակալությունն ու Կրետեն։ Այս խնդրանքը կայսրության՝ սեփական վիլայեթին կարոտ դառնալու առաջին բացահայտ խոստովանությունն էր։", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Իբրահիմ փաշան ափ իջավ Մոդոնում", "9c993dba"], "d": ["Եգիպտական նավատորմի պաշտպանությամբ ափհանման ուժը ոտք դրեց Մորեայի հարավարևմտյան ծայրին։ Կանոնավոր հետևակով և դաշտային հրետանիով զինված այս բանակը կարճ ժամանակում գերակշռություն հաստատեց ապստամբ խմբերի նկատմամբ։", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Տրիպոլիցան հետ վերցվեց — Մորեայի կենտրոնն ընկավ", "8a478c11"], "d": ["Ապստամբության վարչական կենտրոն Տրիպոլիցայի անկմամբ Մորեայի մեծ մասը կրկին անցավ վերահսկողության տակ։ Քարտեզում թերակղզին, քանի որ եգիպտական ուժերի ձեռքում է, հայտնվում է ենթակայության երանգով։", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Միսսոլոնգին (Մեսոլոնգի) ընկավ", "07257f87"], "d": ["Մեկ տարի տևած պաշարումից հետո քաղաքը գրավվեց։ Սակայն պաշտպանության արձագանքը եվրոպական մամուլում հունական գործի հանդեպ համակրանքը հասցրեց գագաթնակետին և հող նախապատրաստեց մեծ տերությունների միջամտության համար։", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Աթենքի Ակրոպոլիսը հանձնվեց", "3b19f946"], "d": ["Ակրոպոլիսի անկմամբ հունական ապստամբությունը ռազմական առումով գրեթե ավարտվել էր։ Հենց այդ կետում հարցը ներքին ապստամբություն լինելուց դուրս եկավ և դարձավ եվրոպական դիվանագիտության թեմա։", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Լոնդոնի պայմանագիրը՝ երեք պետությունները պարտադրեցին հունական ինքնավարություն", "7ce46fd8"], "d": ["Անգլիան, Ֆրանսիան և Ռուսաստանը որոշեցին միասին գործել՝ օսմանցիների և հույների միջև հրադադարի և ինքնավարության պայմանն ընդունել տալու համար. տեղեկացվեց, որ մերժման դեպքում իրենց նավատորմերը կմիջամտեն։ Բարձր Դուռը մերժեց առաջարկը։", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Ալեքսանդրիայի համաձայնագիրը՝ Եգիպտոսի՝ Մորեայից դուրս գալու որոշումը", "cc978f37"], "d": ["Նավարինում նավատորմը կորցրած Մուհամմեդ Ալին, առանց Ստամբուլի հետ խորհրդակցելու, ուղղակիորեն համաձայնության գալով անգլիական ծովակալի հետ՝ ընդունեց իր ուժերը դուրս բերել Մորեայից։ Կուսակալի՝ մեծ տերությունների հետ ինքնուրույն պայմանագիր կնքելը գալիք ճգնաժամի նախանշանն էր։", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Եգիպտական ուժերը դատարկեցին Մորեան", "8fb742dd"], "d": ["Վերջին զորամասերը բարձրացվեցին նավերի վրա. թերակղզին փաստացի ձեռքից գնաց և 1830 թվականի Լոնդոնի արձանագրությամբ դարձավ անկախ Հունաստանի միջուկը։ Իսկ Մուհամմեդ Ալին չէր ստացել խոստացված Մորեայի կուսակալությունը և փոխարենը կորցրել էր մեծ նավատորմ և բանակ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Մոդոն, Կորոն։", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Կրետեի կառավարումը թողնվեց Մուհամմեդ Ալիին", "7f76396d"], "d": ["Որպես Մորեայի կորստի փոխհատուցում՝ Կրետեի կուսակալությունը տրվեց Մուհամմեդ Ալիին։ Կղզին տասը տարի կառավարվեց Կահիրեից. քարտեզում այդ ժամանակահատվածում երևում է ենթակայության երանգով։ Նույն ամսաթվին միացած այլ վայրեր՝ Կանդիա (Կրետե)։", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Իբրահիմ փաշան մտավ Սիրիա — սկսվեց առաջին ճգնաժամը", "1a5cc386"], "d": ["Պատրվակը Աքքայի կուսակալն էր, որը չէր վերադարձնում Եգիպտոսից փախած ֆելլահներին. իրական պատճառը Սիրիայի փայտանյութի, նավահանգիստների և մարդկային ռեսուրսների՝ Մուհամմեդ Ալիի կարիքն էր։ Բանակը, անցնելով Սինայը, արագորեն գրավեց Պաղեստինի ծովափը։", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Սկսվեց Աքքայի պաշարումը", "b211d96d"], "d": ["1799 թվականին Նապոլեոնին կանգնեցրած ամրոցը վեց ամիս դիմադրեց։ Պաշարումը եգիպտական բանակի ժամանակակից հրետանու առաջին մեծ փորձությունն էր։", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Աքքան ընկավ", "0f47917b"], "d": ["Պարիսպները ռմբակոծող մարտկոցները բացվածք արեցին, և ամրոցը գրավվեց։ Բացվել էր Սիրիայի դուռը. Բարձր Դուռը նույն օրերին Մուհամմեդ Ալիին հայտարարեց ապստամբ և վերացրեց նրա կուսակալությունը։", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Դամասկոսը հանձնվեց", "48da3b62"], "d": ["Քաղաքը հանձնվեց առանց կռվի։ Իբրահիմ փաշան, հայտարարելով հարկային կարգը և ոչ մուսուլմաններին ճանաչված հավասարությունը, փորձեց շահել տեղական աջակցությունը. նույն քաղաքականությունը մի քանի տարի անց դառնալու էր նաև նրա դեմ ապստամբությունների պատճառ։ Նույն օրերին միացած այլ վայրեր՝ Բեյրութ, Տրիպոլի (Լիբանան), Սիդոն։", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Հոմսի ճակատամարտը", "867810ee"], "d": ["Սիրիան փրկելու ուղարկված օսմանյան բանակը ջախջախվեց բաց տեղանքում։ Պարզվեց, որ ենիչերիության վերացումից վեց տարի անց ստեղծված նոր բանակը դեռ պատրաստ չէր։", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Գրավվեց Հալեպը", "9c0ead76"], "d": ["Հյուսիսային Սիրիայի առևտրի և կառավարման կենտրոնը ևս ընկավ։ Այսպիսով եգիպտական բանակը հասավ Տավրոսի ստորոտներին և շարժվեց դեպի Անատոլիայի դռան լեռնանցքները։", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Բելենի (Beylan) լեռնանցքի ջախջախումը — բացվեց Կիլիկիան", "4bae872b"], "d": ["Ամանոս լեռների նեղ լեռնանցքում պաշտպանության գիծը ճեղքվեց։ Անտիոքը, Ադանան և Տարսոնը անցան եգիպտական ուժերին (Մարաշի օկուպացիան, ըստ TDV-ի, 1833 թվականն է, առանձին գրառում). քարտեզում Կիլիկիան անցնում է ենթակայության երանգի։ Անատոլիայի խորքերը տանող ճանապարհն այժմ անպաշտպան էր։", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Գյուլեքի կիրճն ընկավ — Իչելի ծովափը (Մերսին, Սիլիֆքե) անցավ եգիպտական վերահսկողության", "d9049b5b"], "d": ["Տավրոսի՝ դեպի Կիլիկիա դուռը՝ Գյուլեքի կիրճը, անցավ եգիպտական բանակի ձեռքը։ Իբրահիմ փաշան Իչելի սանջակում նշանակեց իր մյութեսելիմին (կառավարիչ), և ծովափի բոլոր նավամատույցներն անցան եգիպտական վերահսկողության տակ։ Քարտեզում Մերսինը և Սիլիֆքեն այս օրվանից (ստորին սահման. նշանակման օրը աղբյուրում նշված չէ) ցույց են տրվում Եգիպտոսին ենթակա. քանի որ Քյոթահիայի որոշմամբ անցավ միայն Ադանայի մուհասսըլությունը, այս վերահսկողությունն ավարտվում է Անատոլիայի դատարկմամբ։", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Կոնիայի Էրեղլին եգիպտական օկուպացիայի տակ — Կոնիա–Ադանա ճանապարհի տավրոսյան մուտքը", "fb908900"], "d": ["Գյուլեքի կիրճն անցած եգիպտական բանակի՝ Կոնիա տանող ճանապարհի վրա գտնվող Էրեղլին 1832 թվականին մտավ Իբրահիմ փաշայի օկուպացիայի տակ և 1833 թվականի Քյոթահիայի կարգավորմամբ դատարկվելուց հետո կրկին միացվեց Կարամանի վիլայեթին։ Քարտեզում այն Ադանայի և Կոնիայի միջև օկուպացիայի գծի աղբյուրով հիմնավորված միջանկյալ կետն է. Ուլուքըշլայի և Քարափընարի համար քաղաքի մակարդակով վկայություն չի գտնվել։", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Եգիպտական բանակը մտավ Կոնիա", "13952a2d"], "d": ["Տավրոսն անցած բանակը հասավ Կենտրոնական Անատոլիա։ Առաջին անգամ օսմանյան կուսակալի ուժերը առաջանում էին կայսրության միջուկային հողերում։ Նույն ամսաթվին միացած այլ վայրեր՝ Կարաման։", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Կոնիայի դաշտային ճակատամարտը՝ մեծ վեզիրը գերի ընկավ", "ec82cc9a"], "d": ["Մառախլապատ եղանակին ցրված օսմանյան բանակը ծանր պարտություն կրեց, և մեծ վեզիր Ռեշիդ Մեհմեդ փաշան գերի վերցվեց։ Պետության կենտրոնական բանակն այլևս գոյություն չուներ. Ստամբուլի և եգիպտական ուժերի միջև կանգնող ուժ չէր մնացել։", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Մարաշը ենթարկվեց եգիպտական օկուպացիայի", "f558e383"], "d": ["Ըստ TDV-ի՝ Մարաշը 1833 թվականին ենթարկվեց Կավալացի Իբրահիմ փաշայի օկուպացիային և մոտ տասնինը ամիս մնաց նրա կառավարման տակ։ Քանի որ Մարաշը Քյոթահիայի կարգավորման էյալեթային սահմաններից դուրս էր, այս կառավարումը իրավաբանական չէ, այլ փաստացի։", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Քարահիսար-ը Սահիբը (Աֆյոն) ենթարկվեց եգիպտական օկուպացիայի — Կոնիա–Քյոթահիա ճանապարհը", "ae0c2c78"], "d": ["Կոնիայի դաշտային ճակատամարտից հետո դեպի Քյոթահիա առաջացող եգիպտական բանակի ճանապարհի վրա գտնվող Քարահիսար-ը Սահիբը 1833 թվականին որոշ ժամանակ մնաց Իբրահիմ փաշայի ձեռքում։ Քարտեզում այն Կոնիայի և Քյոթահիայի միջև օկուպացիայի գծի աղբյուրով հիմնավորված միջանկյալ կետն է. Աքշեհիրի, Ըլգընի և Իսհակլըի համար քաղաքի մակարդակով վկայություն չի գտնվել, դրանք օսմանյան գույնով են։", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Եգիպտական բանակը հասավ Քյոթահիա", "214f8df6"], "d": ["Իբրահիմ փաշան կանգ առավ Ստամբուլից երեք օթևան հեռավորության վրա գտնվող Քյոթահիայում։ Նրա՝ առաջ չգնալու պատճառը ոչ թե ռազմական, այլ քաղաքական էր. հաշվի էին առնվել ռուսական միջամտությունը և Եվրոպայի արձագանքը։", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Ռուսական նավատորմը Բյույուքդերեի առջև", "6f836d61"], "d": ["Անգլիայից և Ֆրանսիայից օգնություն չստացած Մահմուդ II-ը դիմեց իր երեկվա թշնամուն՝ Ռուսաստանին։ Փադիշահի «խեղդվողը օձից էլ կկառչի» խոսքով հիշվող այս որոշումը հանգեցրեց ռուս զինվորների ափհանմանը նեղուցներում և տագնապի ահազանգ հնչեցրեց Եվրոպայում։", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Քյոթահիայի փոխզիջումը (բանավոր) — Սիրիան և Ադանան՝ Կավալացուն", "25fe9985"], "d": ["Բարձր Դուռը Եգիպտոսից, Կրետեից և Հիջազից բացի Մուհամմեդ Ալիին թողեց Դամասկոսի, Հալեպի, Տրիպոլիի (Լիբանան) և Սիդոնի կուսակալությունները, իսկ Ադանայի մուհասսըլությունը՝ Իբրահիմ փաշային։ Փոխարենը բանակը հետ քաշվեց Տավրոսից հարավ։ Սա պայմանագիր չէր, այլ փադիշահի՝ կուսակալին տված ֆերմանների տեսքով էր. հարցը չէր լուծվել, այլ հետաձգվել էր։", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Եգիպտական բանակի նահանջը Անատոլիայից ավարտվեց Գյուլեքի կիրճով", "a53ac2a3"], "d": ["Քյոթահիայի կարգավորումից հետո եգիպտական ուժերը դատարկեցին Անատոլիան. մոտ հունիսի կեսերին բանակն ամբողջությամբ Գյուլեքի կիրճով անցավ Կիլիկիա։ Իչելի ծովափը (Մերսին, Սիլիֆքե) կրկին վերադառնում է օսմանյան կառավարման. Ադանայի մուհասսըլությունը և Սիրիան մնում են Եգիպտոսին։", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Հյունքյար Իսքելեսիի պայմանագիրը", "da741d5c"], "d": ["Ռուսաստանի հետ ստորագրվեց ութամյա փոխադարձ պաշտպանական դաշինք։ Ըստ գաղտնի հոդվածի՝ եթե Ռուսաստանը ենթարկվեր հարձակման, Օսմանյան պետությունը նեղուցները փակելու էր ռազմանավերի առաջ։ Սա դարձավ օսմանյան դիվանագիտության ամենավիճելի որոշումներից մեկը և Անգլիային ակտիվացրեց եգիպտական հարցում։", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Պաղեստին-Նաբլուսի ապստամբությունը եգիպտական կառավարման դեմ", "4fe43e27"], "d": ["Պարտադիր զինվորական ծառայությունը, զենքի հավաքումը և նոր հարկերը Պաղեստինում հանգեցրին լայն ապստամբության։ Ապստամբությունը դաժանորեն ճնշվեց. եգիպտական կառավարման աջակցությունը տեղական ժողովրդի աչքում արագ հալվեց։", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Մարաշում եգիպտական կառավարման ավարտը (մոտավոր)", "bb46ca42"], "d": ["TDV-ի «մոտ տասնինը ամիս» տևողությունը 1833 թվականի օկուպացիայից հաշվելով՝ եգիպտական կառավարումն ավարտվում է մոտ 1834 թվականի ամռանը։ Այն, որ Քյուչյուքալի-օղլուներից Մուստաֆա բեյը 1834 թվականին, չկարողանալով դիմակայել եգիպտական բանակին, քաշվեց դեպի Մարաշի կողմերը, ցույց է տալիս, որ Մարաշն այդ ժամանակ եգիպտական վերահսկողությունից դուրս ապաստարան էր։", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Ջաբալ ադ-Դուրուզի ապստամբությունը", "12e74626"], "d": ["Դրուզական շրջանում ծագած դիմադրությունը տևեց երկու տարի։ Սիրիայում կուտակված դժգոհությունը 1840 թվականին, երբ դաշնակից նավատորմերը ափ իջան, դատարկելու էր եգիպտական բանակի թիկունքը։", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Մուհամմեդ Ալին հայտնեց անկախության մտադրությունը", "48633bbd"], "d": ["Կուսակալը մեծ տերությունների հյուպատոսներին հայտնեց, որ մտածում է հռչակել Եգիպտոսի և Սիրիայի անկախությունը։ Անգլիան վճռականորեն դեմ արտահայտվեց. Միջերկրական ծովում հզոր և Ֆրանսիային մոտ պետության ծնունդը կսպառնար Հնդկաստանի ճանապարհին։", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Օսմանյան բանակն անցավ Եփրատը", "9af1ea69"], "d": ["Մահմուդ II-ը, Քյոթահիայում կորցրածը հետ վերցնելու համար, իր բանակը մղեց Սիրիայի սահման։ Բանակում որպես խորհրդական գտնվող պրուսացի սպա Մոլտկեն առարկեց դիրքերի ընտրությանը և վաղաժամ հարձակմանը. նրա առարկությունները չլսվեցին։", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Նիզիպի ճակատամարտը — օսմանյան բանակը ցրվեց", "156b3cdf"], "d": ["Վատ դասավորված օսմանյան բանակը մի քանի ժամում ջախջախվեց։ Մինչ պարտության լուրը կհասներ Ստամբուլ, փադիշահը մահացավ. մի քանի օրվա ընթացքում պետությունը կորցնելու էր իր բանակը, տիրակալին, ապա նաև նավատորմը։", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Մահմուդ II-ի մահը", "07eccfff"], "d": ["Երեսունմեկ տարվա գահակալության ընթացքում ենիչերիությունը վերացրած և կենտրոնական կառավարումը վերականգնած փադիշահը մահացավ՝ չհաղթելով իր ամենամեծ հակառակորդին։ Նրա հիվանդությունը ճիշտ չէր ախտորոշվել։ Նրա մահը, ենիչերիական մտածելակերպի շարժման մեջ մտնելու վախից, թաքցվեց մինչև հունիսի 30-ը, մինչ քաղաքում ռազմական միջոցներ ձեռնարկվեցին։", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Աբդուլմեջիդի գահակալումը և Մահմուդ II-ի հուղարկավորությունը", "d0f3d2cc"], "d": ["Հոր մահից հետո գահ բարձրացավ տասնվեցամյա Աբդուլմեջիդը։ Նույն օրը Մահմուդ II-ի դին բերվեց Թոփքափի պալատ. վախեցած խառնակությունը տեղի չունեցավ, մուսուլման և ոչ մուսուլման լայն զանգվածներ մասնակցեցին հուղարկավորության թափորին։", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Նավատորմի հանձնումը Ալեքսանդրիային", "a53e6103"], "d": ["Կապուդան փաշա Ահմեդ Ֆևզի փաշան, կասկածելով, որ մեծ վեզիր Քոջա Խյուսրև փաշան նավատորմը տալու է Ռուսաստանին, նավատորմը տարավ Ալեքսանդրիա և հանձնեց Մուհամմեդ Ալիին։ Օսմանյան պետությունը նույն ամսվա ընթացքում մնաց առանց բանակի, առանց փադիշահի և առանց նավատորմի։", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Մեծ տերությունների համատեղ նոտան", "2a3b8316"], "d": ["Հինգ պետությունները նոտա հանձնեցին Բարձր Դռանը՝ խնդրելով եգիպտական հարցում միայնակ համաձայնագիր չկնքել։ Այսպիսով ներքին հարցը պաշտոնապես դարձավ «եվրոպական հարց». Օսմանյան պետությունը փաստացի կորցրեց իր սեփական վիլայեթի վերաբերյալ որոշում կայացնելու իրավասությունը։", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Լոնդոնի պայմանագիրը՝ չորս պետություն օսմանցիների կողքին", "a517f775"], "d": ["Ֆրանսիան դուրս թողնելով ստորագրված պայմանագիրը վերջնագիր ներկայացրեց Մուհամմեդ Ալիին. եթե տասը օրում ընդուներ՝ ժառանգական կուսակալություն Եգիպտոսում և ցմահ իրավունքով Աքքան. եթե քսան օրում ընդուներ՝ միայն Եգիպտոսը. եթե մերժեր՝ ոչինչ։ Կուսակալը մերժեց։", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Բեյրութի ռմբակոծումը և դաշնակիցների ափհանումը", "0905ce92"], "d": ["Անգլո-ավստրիական նավատորմը ռմբակոծեց Բեյրութը. Լիբանանի լեռներում եգիպտական կառավարման դեմ ապստամբած ժողովրդին զենք բաժանվեց։ Իբրահիմ փաշայի վերահսկողությունը Սիրիայում փլուզվեց ներքին ապստամբության և արտաքին միջամտության միջև։", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Բեյրութը և ափամերձ քաղաքները ձեռքից գնացին", "09bdaf23"], "d": ["Բաալբեքի ուղղությամբ ընդհարումներից հետո եգիպտական ուժերը նահանջեցին ափից։ Քարտեզում Լիբանանի ափը դուրս է գալիս ենթակայության երանգից և վերադառնում ուղղակի օսմանյան կառավարման։", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Աքքան ընկավ երկու ժամում", "5aec21f0"], "d": ["Դաշնակից նավախմբի ռմբակոծությունից ամրոցի զինապահեստը պայթեց, և Աքքան մի քանի ժամում հանձնվեց։ Ամրոցը, որ ութ տարի առաջ Իբրահիմ փաշան կարողացել էր գրավել միայն վեց ամսում, ցույց տվեց ծովային հրետանու գերազանցությունը։", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Ալեքսանդրիայի կոնվենցիան", "85cb47b0"], "d": ["Մուհամմեդ Ալին համաձայնեց հրաժարվել Սիրիայից, Ադանայից, Կրետեից և Հիջազից, վերադարձնել օսմանյան նավատորմը և ճանաչել փադիշահի գերիշխանությունը. փոխարենը երաշխավորվեց Եգիպտոսի ժառանգական կուսակալությունը։", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Եգիպտական բանակը դատարկեց Սիրիան և Կիլիկիան", "719a28dc"], "d": ["Ինը տարի տևած օկուպացիան ավարտվեց. Իբրահիմ փաշայի բանակը Սինայի վրայով վերադարձավ Եգիպտոս։ Քարտեզում Հալեպից Գազա, Ադանայից Կրետե ձգվող լայն գոտին կրկին անցնում է ուղղակի օսմանյան կառավարման։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Ուրֆա, Մարաշ, Տարսոն, Անտիոք, Կանդիա (Կրետե), Համա, Դամասկոս, Երուսաղեմ, Յաֆա, Նաբլուս։", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Ֆերման՝ Եգիպտոսի կուսակալությունը ժառանգաբար թողնվեց Կավալացու ընտանիքին", "87b89ff8"], "d": ["Փադիշահի ֆերմանը ճանաչեց կուսակալությունը՝ հարստության ներսում հորից որդի անցնող. փոխարենը բանակի թվակազմը կրճատվեց մինչև տասնութ հազար, հարկը կապվեց Ստամբուլին, վերացվեցին դրամ հատելու և պայմանագրեր կնքելու իրավասությունները։ Եգիպտոսը մնաց որպես վիլայեթ, բայց այժմ առանձին հարստության երկիր էր։ Հիջազի և երկու սրբավայրերի կառավարումը վերադարձավ Բարձր Դռանը։ Նույն ամսաթվին ենթակայության շերտից ուղղակի շերտ վերադարձած այլ բնակավայրեր՝ Մեքքա, Մեդինա, Ջիդդա, Յանբու։", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Լոնդոնի նեղուցների կոնվենցիան", "0e95a1ea"], "d": ["Հյունքյար Իսքելեսիին փոխարինած կոնվենցիան սահմանեց, որ խաղաղ ժամանակ նեղուցները փակ լինեն բոլոր ռազմանավերի առաջ։ Այսպիսով Ռուսաստանի միայնակ ձեռք բերած արտոնությունը վերածվեց Եվրոպայի համատեղ երաշխիքի. նեղուցների հարցն ստացավ միջազգային կարգավիճակ։", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Իբրահիմ փաշան փաստացի դարձավ Եգիպտոսի կուսակալ", "9e14f5d9"], "d": ["Ծերացող և մտավոր ունակությունները կորցնող Մուհամմեդ Ալիի փոխարեն կուսակալությունը հանձնվեց նրա որդի Իբրահիմ փաշային։ Սակայն մի քանի ամիս անց՝ 1848 թվականի նոյեմբերին, նա մահացավ հորից առաջ։", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Կավալացի Մուհամմեդ Ալի փաշայի մահը", "871310e0"], "d": ["Կավալայում ծնված, Եգիպտոսում հարստություն հիմնած, կայսրությունը երկու անգամ անդունդի եզրին հասցրած կուսակալը մահացավ ութսուն տարեկանում։ Նրա հիմնած հարստությունը իշխեց Եգիպտոսում մինչև 1953 թվականը. իսկ պետությունը, տեսնելով, որ նրա բացած վերքը կարողացել է փակել եվրոպական միջամտությամբ, առաջ գնաց Թանզիմաթի ուղիով։", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Սուլեյման բ. Քութալմիշը պարտվեց և զոհվեց Այն Սեյլեմում. Անտիոքը դուրս եկավ Անատոլիայի սելջուկների ձեռքից", "0412dfa1"], "d": ["1084 թ. Անտիոքը Բյուզանդիայից գրաված Սուլեյման բ. Քութալմիշը զոհվեց Սիրիայի սելջուկ տիրակալ Թութուշի դեմ Այն Սեյլեմի ճակատամարտում. քաղաքն անցավ Մեծ սելջուկների սուլթան Մելիքշահի վերահսկողության տակ, և կուսակալ նշանակվեց Յաղըսյանը։", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Մելիքշահը մահացավ. Անտիոքը Յաղըսյանի հետ ենթարկվեց Սիրիայի սելջուկ Թութուշին", "c61da1b4"], "d": ["Մեծ սելջուկների սուլթան Մելիքշահի մահից հետո պետությունը բաժանվեց ժառանգների միջև. Անտիոքի կուսակալ Յաղըսյանը ենթարկվեց Սիրիայի տիրակալ Թութուշին։", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Նիկիան հանձնվեց խաչակիրներին. սելջուկյան կենտրոնը տեղափոխվեց Կոնիա, Բյուզանդիան սկսեց վերագրավել արևմտյան Անատոլիան", "8a4e90fa"], "d": ["Խաչակիրների կողմից Նիկիայի (Իզնիկ) պաշարումից հետո քաղաքը 1097 թ. հունիսի 19-ին հանձնվեց Բյուզանդիային. սելջուկ սուլթան Քըլըչ Արսլան I-ը իր կենտրոնը տեղափոխեց երկրի խորքը՝ Կոնիա, իսկ Բյուզանդիան վերագրավեց արևմտյան Անատոլիայի ափերի այնպիսի վայրեր, ինչպիսին է Եփեսոսը։", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Քըլըչ Արսլան II-ը Բյուզանդիայից գրավեց Դորիլեոնը (Էսքիշեհիր) և Քյոթահիան", "3ddee6c2"], "d": ["Միրիոկեֆալոնից (1176) հետո Անատոլիայի ներսում գտնվող բյուզանդական Դորիլեոն և Քյոթահիա բերդերը Մանուելի վերջին տարիներին/մահից հետո՝ 576/1180 թ., անցան Քըլըչ Արսլան II-ի ձեռքը։", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Կարամանօղլու Մեհմեդ բեյը նշանակվեց Էրմենեքի սուբաշի և իր կառավարման տակ վերցրեց Իչ Իլը", "6d62be11"], "d": ["Կարամանօղլու Մեհմեդ բեյը 675 (1276) թ. նշանակվեց Էրմենեքի սուբաշի և իր կառավարման տակ վերցրեց Իչ Իլը. Էրմենեքը դարձավ հաջորդ տարի Կոնիայի վրա շարժվելու Կարամանօղուլների առաջին կենտրոնը։", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Էրթուղրուլ Ղազիի մահը և Օսման բեյի՝ բեյլիքի գլուխ անցնելը — Սոյութի և Դոմանիչի ժառանգությունը", "395fb9fa"], "d": ["Ըստ TDV-ի՝ Էրթուղրուլ Ղազին մահացել է 680 (1281-82) թվականին. հոդվածը նշում է, որ տրվում են նաև 1288 և 1289 թվականները։ Օսման բեյը հորից ստացավ ոչ թե նվաճված քաղաք, այլ սելջուկյան սուլթանի՝ սահմանամերձ շրջանի ամենաառաջ գծում տեղավորած Էրթուղրուլին տված երկու հատկացումները՝ Սոյութում ձմեռանոց (yurtluk) և Դոմանիչում ամառանոց։ Այսինքն՝ բեյլիքն իր գործը սկսել է ոչ թե նվաճման ժառանգությամբ, այլ երկու արոտավայրի հատկացմամբ. քարտեզում այս երկու վայրերը ցույց են տրվում ոչ թե որպես «նվաճում», այլ որպես «ժառանգություն»։", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Սիցիլիական երեկոյան — Անժու հարստությունը կորցրեց Սիցիլիա կղզին", "547db635"], "d": ["Պալերմոյում Զատկի երկուշաբթի օրը, երեկոյան աղոթքի ժամին, Շառլ I Անժուացու կառավարման դեմ բռնկված ապստամբությունը Սիցիլիա կղզին պոկեց Անժու հարստությունից։ Սիցիլիայի թագավորությունը բաժանվեց երկու մասի. կղզին ուղղվեց դեպի Արագոն, իսկ Անժու հարստությունը պահպանվեց Նեապոլ կենտրոնով մայրցամաքային թագավորությունում։ Հարստության ադրիատիկյան և միջերկրածովյան արտաքին տիրույթները ևս մնացին կապված այս թագավորությանը. 1267 թվականից իրենց ձեռքում գտնվող Կորֆուն և 1270-ականներից պահվող Դուրեսը շարունակեցին մնալ Նեապոլի թագավորության մաս. Ալբանիայի ափի Վլյորա, Կանինա և Խիմարա ամրոցները ևս մնացին Նեապոլ կենտրոնով թագավորությունում (Վլյորայի հրամանատար John of Taxis-ը 1282 թվականի ողջ ընթացքում դիմադրեց բյուզանդացիներին. Դուրեսը, Վլյորան և Կանինան, ամենայն հավանականությամբ, 1285 թվականի սկզբին անցան Բյուզանդիային)։ Իսկ Մալթան անցավ արագոնացիների ձեռքը միայն 1284 թվականին։", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Կուլաջահիսարի հարձակումը — Օսման բեյի առաջին ռազմական գործողությունը", "79b00b14"], "d": ["TDV-ի «Օսման I» հոդվածը. «Ինեգյոլի մոտ փոքր Կուլաջա Հիսարը թալանեց և հրի մատնեց (684/1285)»։ Սա Օսման բեյի՝ աղբյուրներում թվագրելի առաջին ռազմական գործողությունն է։ Մշտական բնակավայր չի գրավվել, ամրոցը թալանվել և այրվել է. հետևաբար դա ոչ թե նվաճում, այլ դասական սահմանային ասպատակություն է։ Համարվում է բեյլիքի ռազմական գործունեության ելակետը։", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Քարաջահիսարի նվաճումը — առաջին քաղաքային ձեռքբերումը և տիրապետությունը Էսքիշեհիրին", "178ae619"], "d": ["TDV-ի «Օսման I» հոդվածը. Օսման բեյը 687 (1288) թվականին «նվաճելով Քարաջահիսարը՝ տիրեց Էսքիշեհիրին»։ Սա բեյլիքի առաջին իրական քաղաքային ձեռքբերումն է, և ըստ ավանդության՝ այս հաջողությամբ Օսման բեյը սահմանամերձ շրջանում բարձրացել է սանջակի բեյության. պատմվում է, որ նրա անունով առաջին ուրբաթօրյա խուտբան ընթերցվել է Քարաջահիսարում, և այստեղ նշանակվել է առաջին կադին։ TDV-ի «Էսքիշեհիր» հոդվածը նշում է, որ օսմանյան ավանդույթը տալիս է 1291 թվականը, սակայն դրա ճշմարտացիությունը կասկածելի է։", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Աքքայի անկումը մամլուքների ձեռքը — խաչակիրների վերացումը Սիրիայի ափից՝ Սիդոն և Բեյրութ", "3ca7a464"], "d": ["Երկար ժամանակ Երուսաղեմի խաչակիր թագավորության կենտրոնը եղած Աքքան նվաճեց մամլուքների սուլթան ալ-Մալիք ալ-Աշրաֆ Խալիլը, և խաչակիրների տիրապետությունը Պաղեստինում ավարտվեց։ Աքքայից նահանջած տամպլիեր ասպետները ապաստանեցին Սիդոնում. մամլուքների բանակի մոտենալուն պես նրանք լքեցին ծովային ամրոցը և փախան Կիպրոս, և քաղաքը նույն ամառը անցավ մամլուքներին։ 1197 թվականից խաչակիրների ձեռքում գտնվող Բեյրութը ևս 1291 թվականին գրավեց Դամասկոսի կուսակալ Սինջար ալ-Շուջաին։ Այսպիսով խաչակիրների երկու դարի ներկայությունը ջնջվեց Սիրիա-Պաղեստինի ափից։", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Բիլեջիքի և Յարհիսարի նվաճումը գիշերային հարձակմամբ", "f461b0af"], "d": ["TDV-ի «Բիլեջիք» հոդվածը. «Թեև Բիլեջիքի տեքֆուրը, այդ թվում նաև շրջանի մյուս տեքֆուրները, Օսման Ղազիի դեմ մահափորձ նախապատրաստեցին, երբ այդ դավադրությունը հայտնի դարձավ, օսմանյան ուժերը հանկարծակի հարձակմամբ նվաճեցին Յարհիսարը և Բիլեջիքը (1299)»։ Երկու ամրոցները գրավվել են մեկ գործողությամբ, նույն գիշերային հարձակմամբ։ Այս ամսաթիվը շրջադարձային կետ է, որն ընդունվում է որպես Օսմանյան պետության հիմնադրման տարի։ Նույն ամսաթվին միացած այլ վայրեր՝ Ինեգյոլ։", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Քոյունհիսարի (Բաֆեոս) ճակատամարտը — բյուզանդական բանակի դեմ առաջին մեծ հաղթանակը", "584a9512"], "d": ["TDV-ի «Օսման I» հոդվածը. Օսման բեյը 1302 թվականի հուլիսի 27-ին Բաֆեոսում (Քոյունհիսար) կռվեց բյուզանդական բանակի դեմ և հաղթեց նրան։ Այս հաղթանակը շրջադարձային կետ է, որը Օսման բեյին տարածաշրջանային սահմանամերձ բեյից բարձրացրեց հարստության հիմնադրի կարգավիճակի։ Ճակատամարտից հետո Բուրսայի դաշտավայրն անցավ օսմանյան վերահսկողության տակ, սկսվեց Իզնիկի շրջափակումը։", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Դիմբոսի հաղթանակը և այնուհետև Քիթեի ու Ուլուբաթի գրավումը", "e168ab64"], "d": ["TDV-ի «Օսման I» հոդվածը. 702 (1303) թվականին Բուրսայի, Քեսթելի, Քիթեի և Ադրանոսի տեքֆուրների կազմած դաշինքը ջախջախվեց Դիմբոսի կիրճում. թշնամին կռվելով նահանջեց մինչև նեղ կիրճը, և Քեսթելի տեքֆուրը զոհվեց մարտադաշտում։ Հաղթանակից անմիջապես հետո գրավվեցին Քիթեի և Ուլուբաթի ամրոցները՝ կտրելով Բուրսայի ցամաքային կապը և խստացնելով նրա շրջափակումը։ Երիտասարդ Օրհանը ևս մասնակցել է այս ճակատամարտին։", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Սաքարիայի արշավանքը՝ Լեբլեբիջիհիսարի, Լեֆքեի, Մեքեջեի և Գեյվեի գրավումը", "a51ba4d3"], "d": ["TDV-ի «Օսման I» հոդվածը տալիս է 704 (1304) թվականի Սաքարիայի արշավանքի հաջորդականությունը. «Երբ հասավ Լեբլեբյուջի ամրոցին, տեքֆուրը հնազանդվեց... Հասավ Լեֆքե... Հասավ Մեքեջե... Գնաց Գեյվե և գրավեց ամրոցը, որը դատարկ գտավ»։ Լեֆքեն Սաքարիայի հովտի՝ դեպի Բիլեջիք բացվող դարպասն է։ Այս մեկ արշավանքով, հովտի երկայնքով ձգվող ամրոցների շղթան անցնելով օսմանյան վերահսկողության, փակվեց Իզնիկի ավազանի արևելյան թևը։", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Քիոսն անցավ ջենովացի Ձակկարիա ընտանիքի վերահսկողության տակ", "9eebe4de"], "d": ["Այդընօղուլների սպառնալիքի պայմաններում Բյուզանդիայի կայսրը օգնություն խնդրեց ջենովացի Բենեդետտո Ձակկարիայից. կղզին անցավ նրա վերահսկողության տակ (անվանական բյուզանդական վասալություն)։ Ձակկարիաների տիրապետությունը տևեց մինչև 1329 թ.։", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Սամոսն անցավ Քիոսի ջենովացիների (Ձակկարիա) սեփականության տակ", "0e6f51e3"], "d": ["Քիոսը վերահսկողության տակ վերցրած ջենովացի Ձակկարիա ընտանիքը իր սեփականությանը միացրեց նաև գրեթե ամայացած Սամոսը (TDV. 1304-1329)։", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Գեյվեի կիրճի ամրոցների նվաճումը՝ Քարաչեփյուշ, Քարաթիգին և Աբսու", "76907c78"], "d": ["TDV-ի «Օրհան» հոդվածը. Օրհանը 705 (1305) թվականի Սաքարիայի արշավանքում «նվաճեց Քարաչեփյուշի (Katoikia), Իզնիկի առջևի Քարաթիգինի և Աբսուի (Hypsu՝ Գեյվեի կիրճում) ամրոցները»։ Այս երեք ամրոցը, փակելով Սաքարիայի հովտի և Իզնիկի ավազանի միջև անցումը, ամբողջությամբ կտրեցին Իզնիկի ցամաքային օգնությունը։ Գեյվեի կիրճի Քարաչեփյուշում և Աբսուում տեղավորվեց Ղազի Աբդուրռահմանը. քաղաքն այլևս կարող էր ընկնել միայն սովից։", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Ադրանոսի (Օրհանելի) արշավանքը — Օսման բեյի վերջին արշավանքը", "4811546c"], "d": ["TDV-ի «Օրհան» հոդվածը 1323 թվականի աշնան Ադրանոսի ամրոցի արշավանքը գրանցում է որպես Օսման բեյի վերջին արշավանք։ Ադրանոսի տեքֆուրը այն տեքֆուրների դաշինքի անդամն էր, որը քսան տարի առաջ Դիմբոսում կազմվել էր օսմանցիների դեմ. այս արշավանքը նշանակում էր այդ հաշիվը փակել։ Ամրոցի վերջնական նվաճման օրն անհայտ է. գործողությունները շարունակել է Օրհան բեյը։", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Օսման Ղազիի մահը և Օրհան բեյի՝ բեյլիքի գլուխ անցնելը", "021487cd"], "d": ["Բեյլիքին իր անունը տված Օսման Ղազին, ըստ Ասփորչա խաթունի և Մեքեջեի վակֆնամեների վկայության, մահացել է 724 (1324) թվականին։ 1305 թվականից արշավանքներում բանակի գլուխ կանգնած նրա որդի Օրհանը հոր մահից հետո առանց որևէ գահակալական կռվի անցավ բեյլիքի գլուխ։ Հիմնադիր սերնդի՝ դրոշը առանց ցնցումների փոխանցելը ցույց է տալիս, որ սահմանամերձ բեյլիքից դեպի պետություն ձգվող ճանապարհին հարստությունն իր առաջին մեծ փորձությունն անցավ հանգիստ։", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Քիոսը վերցվեց Ձակկարիայից և միացվեց Բյուզանդիային", "f6741b26"], "d": ["Անդրոնիկոս III կայսրը Ձակկարիային հեռացրեց կղզուց և կղզին, Բենեդետտո III-ի կուսակալությամբ, միացրեց Բյուզանդիային։ 1346 թ. կղզին օկուպացնելու էր ջենովացի Սիմոնե Վինյոզին։", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Սամոսը Ձակկարիայից վերադարձավ Բյուզանդիային (Քիոսի շղթա)", "08034974"], "d": ["Ձակկարիաների լորդության անկումով (1329 թ. Քիոսի միացումը Բյուզանդիային) Սամոսում ջենովական սեփականությունը նույնպես դադարեց։", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Պելեկանոնի (Մալթեփե) ճակատամարտը և ամբողջ Քոջաելիի գրավումը", "389e7bd4"], "d": ["TDV-ի «Օրհան» հոդվածը. ճակատամարտի առաջին օրը Օրհան Ղազին բյուզանդական բանակը դեպի իրեն գրավելու համար ուղարկեց երեք հարյուր հոգուց բաղկացած ուժ. երկրորդ օրը Փազարլուի հրամանատարության ներքո ջոկատների հարթավայր իջնելով ճակատամարտը մեծացավ, և կայսեր նետով վիրավորվելուց բյուզանդական բանակում խուճապ սկսվեց։ Արդյունքը վճռական էր. «Օրհանը գրավեց ամբողջ Քոջաելին. հաղթանակից հետո իզնիկցիների ոչ մի հույս չմնաց»։ Հերեքեից մինչև Ուսկյուդար ծովափնյա ավաններն անցան օսմանյան իշխանության տակ, Գեբզեն դարձավ շրջանի կենտրոն։ Սա Ստամբուլը փրկելու եկած բյուզանդական կայսերական վերջին բանակն էր։", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Իզնիկում առաջին օսմանյան մեդրեսեի հիմնադրումը", "c85fb625"], "d": ["Իզնիկը գրավելուց անմիջապես հետո Օրհան բեյը այստեղ կադի նշանակեց Չանդարլը Կարա Հալիլին, մի բազիլիկա վերածեց մզկիթի և կողքին իմարեթ ու մեդրեսե կառուցել տալով՝ սկիզբ դրեց քաղաքի վերաշինությանը։ Ըստ TDV-ի «Դավուդ-ի Կայսերի» հոդվածի՝ մեդրեսեի շինարարությունն ավարտվեց 1336 թվականին, և Օրհան Ղազին նրա դասախոսի (մյուդեռիսի) պաշտոնին, օրական 30 ակչեով, բերեց Դավուդ-ի Կայսերիին։ Այս մեդրեսեն օսմանյան գիտական կյանքի առաջին ինստիտուցիոնալ քայլն է. բեյլիքը նվաճման ուժի կողքին ավելացրեց նաև գիտական ավանդույթ։ Նվաճմամբ վերցված բյուզանդական մայրաքաղաքի վերածվելը իսլամական գիտական կենտրոնի օսմանցիների՝ նստակյաց պետություն դառնալու հավակնության առաջին կոնկրետ նշանն էր։", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Բյուզանդիայի խարաջատու դառնալը — Իզմիթի պաշարումը և պայմանագիրը", "0c1ec8d3"], "d": ["TDV-ի «Օրհան» հոդվածը. Օրհանը 733 (1333) թվականի ամռանը մեծ բանակով և քարանետ մեքենաներով պաշարեց Իզմիթը, կայսրը համաձայնեց պայմանագրի։ Պաշարումից հրաժարվելու դիմաց Բյուզանդիան համաձայնեց Օրհանին տարեկան վճարել 12.000 ոսկի (հիպերպիրոն). «այսպիսով օսմանյան էմիրի աչքում Բյուզանդիան վերածվեց խարաջատու երկրի»։ Փոխարենը Օրհանը լինելու էր կայսեր բարեկամը և չէր հարձակվելու Բյուզանդիային ենթակա քաղաքների վրա։ Սահմանամերձ բեյլիքի՝ Արևելյան Հռոմին հարկատու դարձնելը ուժերի հավասարակշռության ինչքան փոխվելու հռչակումն էր։", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Սամոթրակեն վենետիկցիներից անցավ ջենովացի Գատիլուզիո ընտանիքին", "c499ed5f"], "d": ["1204 թ. ի վեր կղզին իրենց ձեռքում պահող վենետիկցիներին ջենովացի Գատիլուզիո ընտանիքը դուրս մղեց կղզուց։", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Կարեսիի բեյլիքի բռնակցումը՝ Բալըքեսիր, Բերգամա, Բիղա, Էդրեմիթ և Էրդեք", "c7cb0511"], "d": ["TDV-ի «Օրհան» հոդվածը (Ինալջըք) բռնակցումը դնում է 735 (1334-35) թվականին. Դեմիրհան բեյի մահից հետո Կարեսիի ղազիները և Հաջի Իլբեյը, գահի հրավիրելով Դուրսուն բեյին, օգնություն խնդրեցին Օրհանից։ Օրհանը նախ շարժվեց Բալըքեսիրի վրա. երբ խաղաղության բանակցության գնացած Դուրսուն բեյը մահացավ Բերգամայի ամրոցից արձակված նետից, բեյլիքն ամբողջությամբ միացավ օսմանյան երկրին։ Նույն գործողությունների ընթացքում հնազանդվեցին Քիրմաստին և Միհալիչը, գրավվեց Գյոլյազըն, և նախկինում անվտանգության երաշխիքով թողնված Ուլուբաթը վերջնականապես զավթվեց։ Օրհանը Կարեսիի սանջակում նշանակեց Սուլեյման փաշային և Բիղան դարձրեց սահմանամերձ կենտրոն. այսպիսով ձեռք բերվեց Ռումելի անցնելու ծովային կադրը։ Նշում. TDV-ի «Կարեսի-օղլուներ» հոդվածը նույն իրադարձության համար տալիս է 746 (1345) թվականը. հանրագիտարանը հակասում է ինքն իրեն։ Նույն ամսաթվին միացած այլ վայրեր՝ Չանաքքալե։", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Սամոսն անցավ Քիոսի Մահոնայի սեփականության տակ", "01628b2f"], "d": ["Այն բանից հետո, երբ ջենովացի Սիմոնե Վինյոզին գրավեց Քիոսը, և կառավարումը հանձնվեց Մահոնա ընկերությանը, Սամոսը նույնպես անցավ Քիոսի ջենովացիների (Մահոնա) սեփականության տակ (TDV. 1346-1475)։", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Օրհան Ղազիի առաջին կապիտուլյացիան ջենովացիների հետ", "e64cb196"], "d": ["Վենետիկա-ջենովական պատերազմի ժամանակ ջենովացիների հետ համաձայնության եկած Օրհան Ղազին 1352 թվականի փետրվարի Բոսֆորի ճակատամարտից հետո Պերայի պաշտպանությանն ուղարկեց 1000 նետաձիգ և զինվորների տեղափոխման համար տրամադրեց 60.000 ոսկի. փոխարենը ջենովացիներին շնորհեց առաջին կապիտուլյացիան։ Պայմանագրի ամբողջական տեքստը մեր օրերը չի հասել։ Սա օսմանցիների՝ եվրոպական ծովային ուժի հետ կնքած առաջին պաշտոնական համաձայնագիրն է, որը երեսունհինգ տարի անց՝ 1387 թվականին, վերանորոգվելու էր։", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Գելիբոլուի գրավումը — մշտական պլացդարմ Ռումելիում", "ba51a160"], "d": ["1349-1352 թվականներին որպես Կանտակուզենոսի դաշնակից շրջակայքին ծանոթացած օսմանցիները 1354 թվականին գրավեցին Գելիբոլուն. հնարավորությունը ստեղծել էր քաղաքի պարիսպները ավերած մեծ երկրաշարժը։ Այսպիսով Չիմփեի նեղ պլացդարմը վերածվեց նեղուցի ռումելիական ափի իրական հենակետի, և դեպի Թրակիա բացվող դուռը լայն բացվեց։ Գելիբոլուն 1366 թվականին Սավոյայի խաչակրաց արշավանքով ձեռքից գնալու էր, բայց 1376 թվականի երկրորդ նվաճմամբ վերջնականապես անցնելու էր օսմանյան տիրապետության տակ։ Նույն ամսաթվին միացած այլ վայրեր՝ Քիլիթբահիր։", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Ռումելիի նվաճող Սուլեյման փաշայի մահը", "2dc98228"], "d": ["Օրհան բեյի ավագ որդին և Ռումելիի նվաճումների ճարտարապետ Սուլեյման փաշան աղբյուրներում 758 (1357), 759 և 760 (1359) թվականներով տրվող ամսաթվերից առավել ընդունվածը եղած 1357 թվականի աշնանը որսի ժամանակ ձիուց ընկնելով մահացավ։ 1352-1354 թվականների անցումներով Ռումելիում մշտական օսմանյան ներկայությունը հիմնած շահզադեի մահը գահաժառանգության հերթը թողեց եղբորը՝ Մուրադին։ Բոլայիրում թաղված Սուլեյման փաշայի դամբարանը մնաց որպես Եվրոպայում օսմանյան հնագույն հարստական հուշարձան։", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Փենջիքի օրենքը — ենիչերիական զորաբանակի հիմքի դրումը", "e5877c2d"], "d": ["Ռումելիի նվաճումներից հետո ուլեմաներից Կարամանցի Կարա Ռուստեմի խորհրդով ուժի մեջ մտավ փենջիք համակարգը, որը նախատեսում էր պետությանը հատկացնել ռազմագերիների մեկ հինգերորդը կամ դրա դրամական համարժեքը։ Այս գերիներից ընտրվածների՝ թուրքական ընտանիքների մոտ դաստիարակվելով զինվորագրվելով ձևավորվեց ուղղակիորեն փադիշահին ենթակա մշտական հետևակային ուժի՝ ենիչերիական զորաբանակի միջուկը։ Ցեղային հեծելազորի վրա հիմնված սահմանամերձ բեյլիքի՝ կենտրոնացված բանակ ունեցող պետության վերափոխումը սկսվեց այս կարգավորմամբ։", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Իջնելը Արևմտյան Թրակիա՝ Գյումյուլջինեի նվաճումը", "9ef69221"], "d": ["Էդիրնեի գրավումից հետո Մարիցայից արևմուտք շարժված սահմանապահ ուժերը Ղազի Էվրենոս բեյի հրամանատարությամբ գրավեցին Արևմտյան Թրակիայի կենտրոն Գյումյուլջինեն։ Քաղաքը դարձավ առաջապահ ռազմակայան, որտեղից Էվրենոս բեյը իր ասպատակությունները տանելու էր Մակեդոնիա։ Այսպիսով Թրակիայի՝ դեպի Էգեյան ծովի ափ ձգվող հատվածն անցավ օսմանյան վերահսկողության, և բացվեց Սալոնիկի ճանապարհը։", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Վառնան անցավ Դոբրուջայի իշխանապետությանը և դարձավ մայրաքաղաք", "2bfe73f9"], "d": ["Բուլղարական ցարության տրոհման գործընթացում Սև ծովի ափի Վառնան միացավ Դոբրոտիչի հիմնած Դոբրուջայի իշխանապետությանը և դարձվեց այս փոքր պետության մայրաքաղաքը։", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Ֆիլիպեից արևմուտք՝ Թաթարփազարջըղի և Իհթիմանի միացումը", "1664d0e1"], "d": ["1372 թվականին Ֆիլիպեի գրավումից հետո Մարիցայի հովտի վերին ծայրի Թաթարփազարջըղը և դեպի Սոֆիա բացվող լեռնանցքը պահող Իհթիմանը կապվեցին օսմանյան կառավարմանը։ Չիրմենի ճակատամարտից հետո վասալացած տեղական իշխանների ձեռքում գտնվող այս գիծը, անցնելով ուղղակի կառավարման, Ֆիլիպե-Սոֆիա ուղին դարձրեց անընդհատ։ Այս առաջխաղացումը տասներկու տարի անց Սոֆիայի նվաճմանը տանող ճանապարհի նախապատրաստությունն է։", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Սավջի բեյի ապստամբությունը — շահզադեի և բյուզանդական գահաժառանգի համատեղ խռովությունը", "75198c33"], "d": ["Մուրադ I-ի որդի Սավջի բեյը և բյուզանդական կայսր Հովհաննես V-ի որդի Անդրոնիկոս Պալեոլոգոսը 1373 թվականի մայիսի սկզբին Բուրսայում և Ստամբուլում միաժամանակ ապստամբեցին իրենց հայրերի դեմ։ Երկու հարստությունների գահաժառանգներին միավորող այս դաշինքը արագորեն ճնշվեց. Սավջի բեյը ձերբակալվեց, աչքերին շիկացած շյուղ քաշեցին և մահապատժի ենթարկեցին։ Օսմանյան ավանդության՝ ապստամբության համար տված 787 (1385) թվականը սխալ է. իրադարձությունը ընկնում է Բյուզանդիայի՝ օսմանյան վասալության մեջ մտնելուն անմիջապես հաջորդող տարիներին և ցույց է տալիս, թե որքան էին իրար խառնվել երկու արքունիքները։", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Ստրումայի և Մեստայի հովիտները՝ Քյոսթենդիլի, Պետրիչի, Նևրոկոփի և Դրամայի միացումը", "8c0980c4"], "d": ["Չիրմենի հաղթանակից հետո օսմանցիներին խարաջ վճարել սկսած սերբ և բուլղար տեղական իշխանների ձեռքում գտնվող Ստրումայի և Մեստայի հովիտները, սահմանապահ բեյերի առաջխաղացմամբ, անցան ուղղակի օսմանյան կառավարման։ Քյոսթենդիլի, Պետրիչի, Նևրոկոփի և Դրամայի միացմամբ բացվեց Մակեդոնիայի արևելյան կեսը, և Սալոնիկն ու Սերեզը մտան պաշարման օղակի մեջ։ Քարտեզում Ռումելիի հարավարևմտյան ընդարձակումը այս գործողությունների արդյունքն է։", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["Էրեթնայի բեյլիքի ավարտը և Կադի Բուրհանեդդինի պետության հիմնադրումը", "60dcaf57"], "d": ["1335 թվականին իլխանական կուսակալությունից ծնված և Սեբաստիա ու Կեսարիա կենտրոնով Կենտրոնական Անատոլիան քառասունվեց տարի կառավարած Էրեթնա-օղլուները քայքայվեցին պալատական ներքին պայքարներից։ 1378 թվականի մայիսին վեզիր դարձած Կադի Բուրհանեդդինը, վերացնելով իր մրցակիցներ Քըլըջարսլանին և Հաջի Շադգելդիին, 1381 թվականի աշնանը հռչակեց իր սուլթանությունը, վերջ դրեց բեյլիքին և հիմնեց իր անունը կրող պետությունը։ Այսպիսով օսմանցիների արևելյան հարևանը փոխվեց. Սեբաստիա-Կեսարիա գիծը դրանից հետո տասնյոթ տարի մնալու էր Կադի Բուրհանեդդինի ձեռքում։", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Թեմուրը գրավեց Հերաթը՝ Քերթ հարստության ավարտը և Խորասանի անցումը Թեմուրյաններին", "15f6019e"], "d": ["Խորասանը 1380 թվականին բաժանված էր սարբադարների, քերթերի և մուզաֆարյանների միջև պայքարով։ Թեմուրը, որդի Միրան շահին շրջան ուղարկելուց հետո, ինքը շարժվեց Հերաթի վրա և որոշ ժամանակ պաշարելուց հետո քաղաքն ընդունեց Քերթի մելիք Ղիյաս ադ-Դին Փիր Ալիից։ Նրա մեկնելուց հետո ծագած ապստամբությունը Միրան շահը արյան մեջ ճնշեց, և վերջ դրվեց 1255 թվականից Հերաթում իշխող Քերթ հարստությանը։ Այս ամսաթվին ամբողջ Խորասանը՝ Մաշհադից մինչև Նիշապուր, անցավ թեմուրյան կառավարման։", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Առաջխաղացումը Մակեդոնիայի խորքը՝ Մանաստիրի և Օհրիդի նվաճումը", "63bb7838"], "d": ["Via Egnatia-ի վրա գտնվող Մանաստիրը և լճի ափի Օհրիդը Ալբանիայի ուղղությամբ ասպատակությունների ժամանակ անցան օսմանյան կառավարման։ Երկուսն էլ Ադրիատիկ ձգվող ճանապարհի բանալի կետերն էին. Օհրիդը նաև Բալկանների հնագույն ուղղափառ արքեպիսկոպոսության կենտրոնն էր։ TDV-ն նշում է, որ Օհրիդի նվաճման ամսաթվի վերաբերյալ հստակ տեղեկություն չկա, առաջ են քաշվել 787 (1385) թվականը և Կրալևիչ Մարկոյի մահից հետո եկող 797 (1395) թվականը. այստեղ հիմք է ընդունված 1385-ը։ Հետագա դարերում Մանաստիրը լինելու էր Ռումելիի ամենակարևոր ռազմական կենտրոններից մեկը։", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Սավրայի ճակատամարտը — Ալբանիայի դարպասների բացումը", "dda6671b"], "d": ["Բալշա հարստության դեմ նեղը ընկած ալբանացի բեյ Կառլո Թոփիայի օգնության կանչով օսմանյան ուժերը Սավրայի դաշտում ջախջախեցին Բալշա II-ի բանակը. Բալշան զոհվեց մարտադաշտում։ Տեղացի բեյի հրավերով մղված այս ճակատամարտը օսմանցիներին բերեց առաջին մշտական ազդեցությունը մինչև Ադրիատիկի ափերը ձգվող ալբանական հողերում։ Տարածաշրջանի բեյերի՝ իրար դեմ ելնելը հնարավորության վերածող այս քաղաքականությունը առաջիկա հարյուրամյակում լինելու էր բալկանյան նվաճումների անփոփոխ մեթոդը։", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["Թեմուրի «եռամյա արշավանքը»՝ Ատրպատականի և Հյուսիսային Իրանի գրավումը", "2a98ec51"], "d": ["Խորասանի արշավանքների ընթացքում Իրանի ցրված վիճակը մոտիկից տեսած Թեմուրը 788 թվականին (1386) շարժվեց դեպի արևմուտք։ «Եռամյա արշավանք» անվանված 1386-1388 թվականների գործողություններում Մազանդարանի, Լուրիստանի և Վրաստանի վրայով անցնելով Ատրպատական՝ հասավ Ղարաբաղ. Թավրիզը, Արդաբիլը, Ուրմիան և Նախիջևանը անցան թեմուրյան կառավարման։ Հյուսիսային Իրանի և Ատրպատականի գրավումը, ինչպես ժամանակին Ջոչիի ուլուսի և Իլխանների միջև էր, սկիզբ դարձավ նաև Ոսկե Հորդայի հետ երկարատև հակամարտության։", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Ֆրենքյազըսըի ճակատամարտը և Կոնիայի պաշարումը — առաջին կարամանյան արշավանքը", "af4e5d77"], "d": ["Կարաման-օղլու Ալաեդդին Ալի բեյի դեմ, որը, թեև իր փեսան էր, անհանգստանում էր Արևմտյան Անատոլիայում օսմանյան ընդարձակումից, Մուրադ I-ն անձամբ ելավ արշավանքի. Ֆրենք Յազըսը կոչվող վայրում տեղի ունեցած ճակատամարտում մարզված և փորձառու օսմանյան բանակը հաղթեց կարամանյան ուժերին։ Այնուհետև պաշարվեց Կոնիայի ամրոցը, սակայն Ալաեդդին բեյին ներելով բեյլիքը լիովին չվերացվեց։ Այս արշավանքը օսմանցիների և Կարամանի միջև մեկ դար տևելիք և միայն 1468 թվականին վերջնական բռնակցմամբ ավարտվելիք երկար հաշվեհարդարի բացման արարն է։", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Մուշը Կարա-Կոյունլուների կառավարումից անցավ Լենկթեմուրի իշխանության տակ (789/1387)", "ed2e7a11"], "d": ["Մոնղոլական շրջանից հետո Կարա-Կոյունլուների կառավարման տակ անցած Մուշը 789 (1387) թ. անցավ Կարա-Կոյունլուների հողերին տիրացած Լենկթեմուրի կառավարման տակ։ Ատլասում Մուշն այդ տարում գրանցված է որպես Կարա-Կոյունլուներից Թեմուրյաններին անցած։", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Գելիբոլուի նավաշինարանի հիմնադրումը — օսմանյան նավատորմի ծնունդը", "47546241"], "d": ["Օսմանյան պետության առաջին կազմակերպված նավաշինարանը 1390 թվականին Յըլդըրըմ Բայազիդը հիմնեց Գելիբոլուում՝ Բյուզանդիայից մնացած նավաշինարանի տեղում։ Արևմտյան Անատոլիայի բեյլիքների ծովային ժառանգությունը ստանձնած օսմանցիները այսպիսով առաջին անգամ դարձան իրենց նավը իրենք կառուցող ծովային ուժ։ Դարդանելի նեղուցի բանալի կետում տեղադրված նավաշինարանը, Ստամբուլի պաշարումից մինչև Էգեյան արշավանքները, մեկուկես դար ծառայեց որպես օսմանյան նավատորմի գլխավոր հենակետ։", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Համիդ գավառը միացավ օսմանցիներին՝ Իսպարթա, Բուրդուր, Ուլուբորլու, Էյիրդիր", "e3da7de5"], "d": ["Կարաման-օղլու Ալաեդդին բեյի՝ Համիդ գավառի վրա հարձակման և ժողովրդի գանգատի առիթով արշավանքի ելած Յըլդըրըմ Բայազիդը գրավեց Համիդ-օղլուների մնացած բոլոր հողերը և դրանց կառավարումը տվեց իր որդի Իսա Չելեբիին։", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Մուզաֆարյան հարստության ավարտը՝ Շահ Մանսուրի պարտությունը Շիրազի մոտ", "5fd14eb8"], "d": ["1318 թվականից Յազդում, Ֆարսում, Սպահանում և Քերմանում իշխող Մուզաֆարյանների վերջին հզոր տիրակալ Շահ Մանսուրը, իր ազգականների հետ միավորվելով, շարժվեց Թեմուրի դեմ։ Շիրազի մոտ տեղի ունեցած ճակատամարտում, երբ նրա էմիրներից մեկն անցավ թշնամու կողմը, կորցրեց իր ուժերի մեծ մասը, պարտվեց և սպանվեց։ Թեմուրի՝ դրանից հետո նաև հարստության բոլոր անդամներին սպանել տալով ավարտվեց մուզաֆարյան իշխանությունը, և Ֆարսն ու Քերմանը միացան թեմուրյան կառավարմանը։", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Ամասիայի միացումը օսմանյան հողերին", "fe2860cf"], "d": ["Յըլդըրըմ Բայազիդի՝ Կենտրոնական Անատոլիայի գործողությունների ժամանակ պաշարված Ամասիայի էմիրը քաղաքը հանձնեց օսմանցիներին, և Բայազիդը 1393 թվականին մտավ քաղաք։ Սուլթանը դրա կառավարումը թողեց որդի Մեհմեդ Չելեբիին. որպես շահզադեական սանջակ՝ Ամասիան դրանից հետո դարձավ օսմանյան հարստության ամենակարևոր դաստիարակության օջախներից մեկը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Լադիկ (Ամասիա), Մերզիֆոն, Օսմանջըք, Չորում։ Այս ընտրությունը վճռորոշ լինելու էր հետագա միջգահակալության շրջանում. Չելեբի Մեհմեդը պետությունը վերամիավորելու պայքարը վարելու էր հենց այս ամասիական հենքից։", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Թեմուրը գրավեց Բաղդադը — Ջալայիրյանները փախան Անատոլիա", "4d5602b3"], "d": ["Թեմուրը երկարատև պաշարումից հետո գրավեց Բաղդադը. քաղաքի տերը՝ ջալայիրյան սուլթան Ահմեդը, փախչելով արևմուտք, ապաստան գտավ նախ մամլուքների, ապա օսմանյան պալատում։ Թեմուրի արևմտյան ընդարձակումը այսպիսով առաջին անգամ ուղղակի շփվեց օսմանյան ազդեցության գոտու հետ։ Երկու տիրակալների թշնամանքի առաջին օղակը սկսվում է այստեղից։", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Վառնայի գրավումը Սև ծովի ափին", "a84b2abf"], "d": ["Բուլղարական ցարության՝ Դանուբի և Սև ծովի միջև գտնվող հողերի սեղմման ժամանակ ափի ամենամեծ նավահանգիստ Վառնան անցավ օսմանյան կառավարման։ Նավահանգստի գրավումը բացեց Դոբրուջայի ուղղությամբ առաջխաղացման ճանապարհը և օսմանցիներին Սև ծովի արևմտյան ափին բերեց առաջին մեծ նավամատույցը։ Վառնան հիսունմեկ տարի անց դառնալու էր նաև 1444 թվականի հաղթանակի բեմը, երբ ոչնչացվելու էր խաչակիր բանակը։", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Նևշեհիրի և Ուրգյուփի շրջանը Կարամանօղուլներից անցավ օսմանցիների ձեռքը", "06ff59e8"], "d": ["Կարամանօղուլների դեմ Յըլդըրըմ Բայազիդի արշավանքների ընթացքում Նևշեհիրի (Մուշքարա) և Ուրգյուփի շրջանը 800/1398 թ. անցավ օսմանյան կառավարման տակ. 1402 թ. Անկարայի ճակատամարտից հետո Լենկթեմուրը տարածքը վերադարձրեց Կարամանօղուլներին։", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Կադի Բուրհանեդդինի պետության կործանումը", "b13391e3"], "d": ["Ակ-կոյունլուների տիրակալ Կարայուլուք Օսման բեյին գերի ընկած Կադի Բուրհանեդդինը, թեև առաջարկեց ազատ արձակվել Սեբաստիան հանձնելու դիմաց, քաղաքի բնակչությունը դիմադրեց, և սուլթանը մահապատժի ենթարկվեց պարիսպների առջև։ Սեբաստիայի ավագները, թեև գլուխ անցկացրին նրա որդի Ալաեդդին Ալի Չելեբիին, ակ-կոյունլուների ճնշման դիմաց օգնություն խնդրեցին Յըլդըրըմ Բայազիդից. Սուլեյման Չելեբիի հրամանատարությամբ օսմանյան ուժերը, հաղթելով Կարայուլուքին, տիրեցին քաղաքին։ Այսպիսով Կադի Բուրհանեդդինի պետությունն անցավ պատմության գիրկը, և Սեբաստիան, Թոքաթը, Նիկսարն ու Կեսարիան միացան օսմանյան հողերին։ Նույն ամսաթվին միացած այլ վայրեր՝ Քըրշեհիր, Չորում։", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Թեմուրի առճակատումը՝ փախստականների վերադարձը մերժվեց", "33790bc8"], "d": ["Թեմուրի ճնշման հետևանքով ջալայիրյան սուլթան Ահմեդը և կարա-կոյունլուների առաջնորդ Կարա Յուսուֆը ապաստանեցին օսմանյան հողերում. Թեմուրը պահանջեց վերադարձնել այս երկու փախստականներին, Յըլդըրըմ Բայազիդը մերժեց։ Դրա հետևանքով երկու տիրակալների միջև սկսվեց փոխադարձ ծանր վիրավորանքներ պարունակող նամակների փոխանակություն։ Պատերազմի գաղափարական հիմքը ստեղծվեց այս նամակագրությամբ՝ դեռ մեկ զինվոր էլ շարժման մեջ չմտած։", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Յըլդըրըմի հիվանդանոցը Բուրսայում — առաջին օսմանյան հիվանդանոցը", "5f0dc59a"], "d": ["Այն տարիներին, երբ Յըլդըրըմ Բայազիդը կառուցել էր տալիս Բուրսայի փառահեղ Ուլու մզկիթը, քաղաքին պարգևեց նաև հիվանդանոց (դարուշշիֆա). իմարեթից, մեդրեսեից, իջևանատնից և կամրջից բաղկացած բարեգործական լայն ծրագրի բժշկությանը հատկացված օղակն էր սա։ Պետության հիմնած առաջին հիվանդանոցը եղած այս կառույցը, ծառայելով նաև որպես բժիշկներ պատրաստող բժշկական դպրոց, որոշեց օսմանյան առողջապահական հաստատությունների օրինակը։ Անկարայի աղետից ընդամենը երկու տարի առաջ ավարտված այս գործը Յըլդըրըմի՝ Բուրսան կայսերական մայրաքաղաքի վերածելու պատկերացման վերջին օղակներից է։", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Թեմուրը հողին հավասարեցրեց Սեբաստիան", "f4d79de6"], "d": ["Ակ-կոյունլու Կարայուլուք Օսման բեյի և Երզնկայի էմիր Մութահարտենի առաջնորդությամբ Սեբաստիա շարժված Թեմուրը քաղաքը պաշարեց տասնութ օր և, ոչ մեկի արյունը չթափելու խոստումով այն ընդունելուց հետո, մեծ կոտորած արեց. պաշտպաններին լցրեց խրամատները և ողջ-ողջ ծածկել տվեց հողով։ Ավերվեցին քաղաքի կարևոր կառույցները՝ առաջին հերթին պարիսպները, և Սեբաստիան ժողովրդագրական առումով փլուզվեց։ Սա Անկարայի ճակատամարտից երկու տարի առաջ Թեմուրի՝ օսմանյան հողերին հասցրած առաջին մեծ հարվածն է։", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Յըլդըրըմ Բայազիդը հետ վերցրեց Երզնկան և Կամախը", "7047ca08"], "d": ["Թեմուրի՝ սիրիական արշավանքի ելնելը օգտագործելով՝ Յըլդըրըմ Բայազիդը Թեմուրին ենթակա Երզնկայի էմիր Մութահարտենի ձեռքից վերցրեց Երզնկան և Կամախը։ Թեև Սեբաստիայի ավերմանը չէր միջամտել, այս քայլը նշանակում էր ուղղակի մարտահրավեր նետել Թեմուրի ազդեցությանն Արևելյան Անատոլիայում։ Դրանից հետո երկու տիրակալների հարաբերությունները դարձան անուղղելի։", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Թեմուրի վերջնագիրը Թավրիզից — չորս պայման", "3e1ac50e"], "d": ["Թեմուրը Թավրիզից ուղարկած դեսպանի միջոցով չորս պայման ներկայացրեց. Կամախը վերադարձնել Մութահարտենին, Անատոլիայի բեյերից վերցրած հողերը վերադարձնել տերերին, որպես պատանդ ուղարկել օսմանյան շահզադե և ընդունել գլխանոցն ու գոտին որպես հպատակության նշան, հանձնել Կարա Յուսուֆին։ Բայազիդը դրանցից և ոչ մեկը չընդունեց. չնայած պետական գործիչների պնդումներին և Մութահարտենի միջնորդությանը՝ բանակցությունները տապալվեցին։ Թեմուրը վճռական էր Չինաստան արշավանքի ելնելուց առաջ վերջնականապես փակել անատոլիական հարցը։", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Սարուխանյանները վերականգնվեցին — Մանիսան դուրս եկավ օսմանյան կազմից", "ac747b05"], "d": ["Անկարայի ջախջախումից երեք շաբաթ անց Թեմուրի աջակցությամբ Օրհան բեյը գլուխ անցավ բեյլիքի, և Սարուխան գավառը կրկին անկախացավ։ Մանիսա կենտրոնով շրջանը 1390 թվականի օսմանյան բռնակցումից տասներկու տարի անց դուրս եկավ քարտեզից։ Սա Թեմուրի՝ բեյլիքները վերակենդանացնելու քաղաքականության առաջին կիրառություններից է, որի ամսաթիվը հստակ հայտնի է։", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Էմիր Սուլեյմանը պետական գանձարանով փախավ Ռումելի", "0a2b7363"], "d": ["Բուրսայի պետական գանձարանը, արխիվները, ընտանիքն ու եղբայրներին իր հետ վերցնելով՝ էմիր Սուլեյմանը Գեմլիքից նավով անցավ Գյուզելջեհիսար (Անատոլու Հիսարը), այնտեղից հասնելով Գելիբոլու՝ Էդիրնեում հռչակեց իր իշխանությունը։ Պետական արխիվի և գանձարանի տեղափոխումը Ռումելի սկիզբն է մեկ սերնդի ընթացքում օսմանյան ծանրության կենտրոնի՝ Բալկաններ տեղափոխվելու։ Քարտեզում Ռումելին այս ամսաթվից գծվում է էմիր Սուլեյմանի սեփական գույնով։", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Թեմուրը վերականգնեց Անատոլիայի բեյլիքները — թուրքական միասնությունը ցրվեց", "15187774"], "d": ["Անկարայի հաղթանակից հետո Թեմուրը իր մոտ գտնվող բեյերին վերադարձրեց իրենց նախկին հողերը։ Կարաման-օղլու Մեհմեդ և Ալի բեյերին տրվեցին Կարաման գավառը՝ Կեսարիայով, Քըրշեհիրով, Սիվրիհիսարով և Բեյշեհիրով. Գերմիյան-օղլու Յաքուբ II բեյին՝ Քյոթահյան և Գերմիյան գավառը. Ջանդար-օղլու Իսֆենդիյար բեյին՝ Կաստամոնու-Սինոպ գծից բացի Չանքըրըն և Քալեջիքը։ Այդըն, Մենթեշե և Թեքե գավառները ևս վերադարձան իրենց նախկին հարստություններին։ Յըլդըրըմ Բայազիդի տասը տարում ստեղծած անատոլիական թուրքական միասնությունը ցրվեց մեկ ամառվա ընթացքում. քարտեզում այս բեյլիքները կրկին հայտնվում են իրենց գույներով։ Նույն գործընթացում ձեռքից ձեռք անցած այլ բնակավայրեր՝ Աքսարայ, Դենիզլի, Էրեղլի (Կոնիա), Էրմենեք, Ըլգըն, Քարափընար, Կեսարիա, Կոնիա, Քըրշեհիր, Քյոթահյա, Սիվրիհիսար, Սյոքե։", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Թեմուրը Իզմիրը վերցրեց Սուրբ Հովհաննեսի ասպետներից", "66dd1dd4"], "d": ["Քյոթահյայի, Դենիզլիի, Այդընի, Այասուլուքի և Տիրեի վրայով դեպի արևմուտք իջած Թեմուրը պաշարեց և գրավեց 1344 թվականից քրիստոնյաների ձեռքում գտնվող ծովափնյա Իզմիրը։ Այս ամրոցը, որը Յըլդըրըմ Բայազիդը տարիներով չէր կարողացել գրավել, կարճ ժամանակում գրաված Թեմուրը, շրջակա ամրոցներն ևս գրավելուց հետո, Այդըն գավառը թողեց նախկին տերերին և վերադարձավ արևելք։ Դրանից հետո քաղաքն անցավ Այդըն-օղլու Ջյունեյդ բեյի կառավարմանը։", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Իսա Չելեբին գրավեց Բուրսան — ծնվեց անատոլիական բաժինը", "955128c1"], "d": ["Անկարայի ջախջախումից հետո Կարեսիի կողմերը քաշված Իսա Չելեբին, երբ Թեմուրը Իզմիրում էր, գրավեց Բուրսան։ Թեմուրի զինվորների թալանած և այրած նախկին մայրաքաղաքում նա հռչակեց իր իշխանությունը և իր անունով դրամ հատել տվեց. 1403 թվականի հունվարին Անատոլիայում ճանաչվում էր որպես «թուրքերի տիրակալ»։ Քարտեզում Մարմարայի ասիական ափի երկայնքով ձգվող այս բաժինը երևում է Իսա Չելեբիի սեփական գույնով։", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Թեմուրի հեռանալը Անատոլիայից", "93a98839"], "d": ["Ստանալով լուրը, որ Յըլդըրըմ Բայազիդը մահացել է Աքշեհիրում, Թեմուրը, համարելով իր անատոլիական գործն ավարտված, շարժվեց դեպի արևելք։ Նրա ետևում մնացին իրեն հավատարմություն հայտնած բեյլիքները և միմյանց դեմ ելած օսմանյան շահզադեները. Սեբաստիայի նման որոշ քաղաքներ թողնվեցին Թեմուրին ենթակա էմիրների՝ Մեզիդ բեյի նմանների ձեռքում։ Թեմուրը այլևս չվերադարձավ Անատոլիա, սակայն նրա ստեղծած այս մասնատված կարգը տևեց տասը տարի։", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Էմիր Սուլեյմանն անցավ Անատոլիա՝ Բուրսան անցավ նրա ձեռքը", "9b27aa5f"], "d": ["Իսա Չելեբիի պարտության մասին լսելով՝ էմիր Սուլեյմանը Չանդարլը Ալի փաշայի հետ հզոր բանակով անցավ Անատոլիա և գրավեց Բուրսան. 1404 թվականի մարտի գրառումները ցույց են տալիս, որ Կարադենիզ Էրեղլին ևս նրա կառավարման տակ էր։ Կարճ ժամանակում թե՛ Ռումելիին, թե՛ Անատոլիայի մեծ մասին տիրած Սուլեյմանի դեմ Չելեբի Մեհմեդը չկարողացավ դիմադրել։ Նույն գործընթացում Չելեբի Մեհմեդից էմիր Սուլեյմանին անցած այլ բնակավայրեր՝ Աքյազը, Անատոլու Հիսարը, Աբսու (Հիփսու), Ադրանոս (Օրհանելի), Աքհիսար (Փամուքովա), Արմութլու, Այդոս ամրոց, Այվալըք, Բալըքեսիր, Բեհրամքալե (Ասոս), Բերգամա, Բեյքոզ, Բիղա։ Քարտեզում այս ամսաթվից մինչև Չելեբի Մեհմեդի կողմից Բուրսայի հետգրավումը (1410) երկու ափերը երևում են մեկ գույնով՝ էմիր Սուլեյմանի բաժնում։", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Ենիշեհիրի դաշտի ճակատամարտը — Չելեբի Մեհմեդը քաշվեց Ամասիա", "f1568288"], "d": ["Բուրսան և Անկարան կորցրած Չելեբի Մեհմեդը Ենիշեհիրի դաշտում պարտվելով էմիր Սուլեյմանին՝ կորցրեց Արևմտյան Անատոլիայի բոլոր ձեռքբերումները և քաշվեց Թոքաթ-Ամասիա հենակետ։ Այս պարտությունից հետո նա, խուսափելով ուղղակի ընդհարումից, ձեռնամուխ եղավ Անատոլիայի խորքերում իր իշխանության ամրապնդմանը։ Այսպես սկսվեց միջգահակալության ամենաերկար անշշուկ փուլը։", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Էմիր Սուլեյմանը Անկարան վերցրեց Չելեբի Մեհմեդից", "d6a2acd6"], "d": ["Թեմուրի՝ Անատոլիայից հեռանալուց հետո Չելեբի Մեհմեդի ձեռքում մնացած Անկարան 1406 թվականին պաշարեց էմիր Սուլեյմանը։ Ամրոցի պահապան Յաքուբ բեյը որոշ ժամանակ դիմացավ, սակայն մեծ վեզիր Չանդարլը Ալի փաշայի խորամանկությամբ ամրոցը հանձնեց Սուլեյմանին։ Դրա հետևանքով Չելեբի Մեհմեդը, համաձայնության գալով Կարաման-օղլու Մեհմեդ բեյի հետ, շարժման մեջ մտավ Սուլեյմանի դեմ։", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Չելեբի Մեհմեդը Սեբաստիան հետ վերցրեց Թեմուրյան Մեզիդ բեյից", "90079b0c"], "d": ["Թեմուրի արշավանքից հետո Սեբաստիայի կառավարումը թողնվել էր Թեմուրին ենթակա Մեզիդ բեյին։ Ամասիայում գտնվող Չելեբի Մեհմեդը իր հրամանատար Բայազիդ փաշային ուղարկեց քաղաքը գրավելու, և կատաղի դիմադրությունից հետո Սեբաստիան երկրորդ անգամ անցավ օսմանյան հարստության ձեռքը։ Այսպիսով Մեհմեդի բաժինը Անկարայի ճակատամարտից վեց տարի անց արևելքում հասավ իր նախկին սահմանին։", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Արթուքյան հարստության ավարտը՝ Մարդինի հանձնումը կարա-կոյունլուներին", "15b06f33"], "d": ["1106 թվականից Մարդինում իշխող և հարստության ամենաերկարակյաց ճյուղը եղած Արթուքյանները չկարողացան դիմանալ ակ-կոյունլուների ճնշմանը։ Հասկանալով, որ չի կարող պաշտպանել քաղաքը, մելիք Ահմեդը համաձայնության գալով կարա-կոյունլուների տիրակալ Կարա Յուսուֆի հետ՝ Մարդինը հանձնեց նրան։ Այսպիսով ավարտվեց երեք դարն անց արթուքյան տիրապետությունը. Մարդինը և նրա շրջակայքը, մինչև մեկ դար անց օսմանցիներին անցնելը, դարձան կարա-կոյունլու-ակ-կոյունլու պայքարի բեմ։", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Յամբոլի ճակատամարտը — Մուսա Չելեբին մտավ Էդիրնե", "8f978408"], "d": ["Վալախիայի վրայով Ռումելի անցած Մուսա Չելեբին վալախական և սերբական աջակցությամբ Յամբոլում ջախջախեց էմիր Սուլեյմանի ուժերը և մտավ Էդիրնե։ Միջգահակալության շրջանում Ռումելին առաջին անգամ դուրս եկավ էմիր Սուլեյմանի ձեռքից։ Սակայն նրա իշխանությունը մշտական չեղավ. չորս ամիս անց Կոսմիդիոնում պարտվելով՝ նա քաշվելու էր Բալկանների խորքերը։", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Ինջեղիզի ճակատամարտը — Չելեբի Մեհմեդի առաջին ռումելիական պարտությունը", "3c35cd43"], "d": ["Բյուզանդիայի նավերով Ռումելի անցած Չելեբի Մեհմեդը Ինջեղիզում կռվի բռնվեց Մուսա Չելեբիի հետ. Մուսան իր հրամանատարության տակ գտնվող յոթ հազար ենիչերիներով պարտության մատնեց Մեհմեդին, և Մեհմեդը ստիպված եղավ վերադառնալ Անատոլիա։ Այս պարտությունը Մեհմեդին ուղղեց ուղղակի պատերազմի փոխարեն Ռումելիի սահմանապահ բեյերին և Սերբական դեսպոտությունը իր կողմը գրավելու ռազմավարության։ Ինը ամիս հետո Չամուրլուի հաղթանակի հիմքը նախապատրաստվեց այս դիվանագիտությամբ։", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Կոնիայի պաշարումը և պայմանագիրը Կարամանյանների հետ — հետ վերցվեցին Համիդ և Սայիդ գավառները, Բեյշեհիրը, Սեյդիշեհիրը և Աքշեհիրը", "0996257e"], "d": ["Միջգահակալության շրջանում օսմանյան հողերի վրա հարձակված և Բուրսան պաշարած ու այրած Կարամանյանների դեմ Չելեբի Մեհմեդը կազմակերպեց մեծ արշավանք և 818 թվականի Մուհառամին պաշարեց Կոնիան։ Կարաման-օղլու Մեհմեդ II բեյը ստիպված եղավ խաղաղություն խնդրել. պայմանագրի արդյունքում Համիդ գավառը (Իսպարթայի շրջանը) և Սայիդ գավառը կրկին միացան օսմանյան հողերին, վերադարձվեցին նաև Բեյշեհիրը, Սեյդիշեհիրը և Աքշեհիրը. օսմանցիներին վերադարձավ նաև Սիվրիհիսարը, որը Թեմուրը 1402 թվականին տվել էր Կարամանյաններին։ Այս արշավանքը, որով սկսեց կարկատվել Անկարայի ճակատամարտով ցրված անատոլիական միասնությունը, Չելեբի Մեհմեդին «երկրորդ հիմնադիր» համարելու կոնկրետ հիմքերից է։", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Իզմիրի գրավումը Այդըն-օղլու Ջյունեյդ բեյից", "2377ca51"], "d": ["Միջգահակալության ողջ ընթացքում շահզադեների միջև անընդհատ կողմ փոխող Այդըն-օղլու Ջյունեյդ բեյի կենտրոն Իզմիրը տասնօրյա պաշարումից հետո գրավեց Չելեբի Մեհմեդը. Ջյունեյդը ներում ստացավ և ուղարկվեց Նիկոպոլիսի սանջակի բեյ։ 1402 թվականին Թեմուրի կողմից Այդըն-օղլուներին վերադարձված քաղաքը այսպիսով տասներեք տարի անց վերադարձավ օսմանցիներին։ Ջյունեյդը 1422 թվականին կրկին գրավելու էր քաղաքը, և հարցը 1424-1426 թվականներին միայն Մուրադ II-ը փակելու էր։", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Թորլաք Քեմալի մահապատիժը — Սարուխանը վերջնականապես օսմանյան է", "8a09dbf1"], "d": ["Շեյխ Բեդրեդդինի շարժման արևմտաանատոլիական թևը ղեկավարող Թորլաք Քեմալը Մանիսայի շրջանում պարտության մատնվեց և մահապատժի ենթարկվեց։ Այս ամսաթվից հետո Սարուխանի շրջանը վերջնականապես անցավ օսմանյան վերահսկողության, և 1402 թվականին Թեմուրի վերակենդանացրած բեյլիքն անցավ պատմության գիրկը։ Այսպիսով մաքրվեցին միջգահակալության շրջանի վերջին քաղաքական մնացորդները Արևմտյան Անատոլիայում։", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Վլյորայի, Բերաթի և Կանինայի նվաճումը", "1e1949b8"], "d": ["Օսմանցիները 1417 թվականին Ադրիատիկի ափի Վլյորան, երկրի ներքին մասի Բերաթ քաղաքի և Կանինա ամրոցի հետ միասին, վերցրին իրենց տիրապետության տակ։ Մեկ տարի անց Վենետիկի՝ քաղաքը հետ վերցնելու փորձը ձախողվեց, և այստեղ ստեղծվելով սանջակային կառույց՝ օսմանյան իշխանությունը դարձավ մշտական։ Վլյորայի գրավումը առաջին անգամ օսմանցիներին դարձրեց Ադրիատիկում ուղղակի նավահանգստի տեր՝ Իտալիայի դեմ ձեռք բերելով ծովից այն կողմ ցատկատախտակ։", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Կենտրոնական Անատոլիայի հետգրավումը՝ Կեսարիա և Քըրշեհիր", "204eacb3"], "d": ["Միջգահակալության շրջանում Կարամանյանների ձեռքն անցած կենտրոնաանատոլիական քաղաքները Չելեբի Մեհմեդի՝ պետությունը վերականգնելու արշավանքների ընթացքում վերադարձան օսմանյան կառավարման։ Կեսարիայի և Քըրշեհիրի միացմամբ Անկարայի ճակատամարտում կորցրած Կըզըլըրմաքի ավազանը մեծ մասամբ հետ վերցվեց։ Այս առաջխաղացումը չորս տարի առաջ Կոնիայի պաշարմամբ սկսված դեպի արևելք շարժվելու քաղաքականության շարունակությունն է։", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Մամլուքները Կեսարիան տվեցին Դուլկադիրյան Նասրեդդին Մուհամմեդին", "aad4b00c"], "d": ["Կարաման-օղլու Մեհմեդ բեյի դեմ արշավանքի ելած մամլուքների բանակը գրավեց Կեսարիան. մամլուք հրամանատարը, քաղաքն ու նրա շրջակայքը թողնելով Դուլկադիրյան Նասրեդդին Մուհամմեդին, վերադարձավ իր երկիրը։", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Մեհմեդ I-ի մահը և Մուրադ II-ի գահակալումը", "98acac77"], "d": ["Գահակալական կռիվների շրջանին (Ֆեթրեթ) վերջ դրած և օսմանյան երկիրը կրկին մեկ ձեռքում միավորած Մեհմեդ I-ը մահացավ 1421 թ. հունիսի 25-ին Ադրիանապոլսում (Էդիրնե), և նրա որդի Մուրադը գահ բարձրացավ Բուրսայում։ Նրա մահից առաջ Բյուզանդիայի հետ կնքված պայմանավորվածության համաձայն՝ նրա կրտսեր որդիները պատանդ պետք է ուղարկվեին կայսեր մոտ, իսկ կայսրը ազատ չպետք է արձակեր իր ձեռքում պահվող գահի հավակնորդ Մուստաֆա Չելեբիին. Մուրադ II-ը հրաժարվեց իր եղբայրներին ուղարկել կայսրին։", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Թեքե-օղլուների վերջնական վերացումը՝ Անթալիայի գրավումը", "e65565b2"], "d": ["Անկարայի ճակատամարտից հետո Թեմուրի վերակենդանացմամբ վերականգնված Թեքե-օղլուների բեյլիքը վերացավ Համզա բեյի հրամանատարությամբ օսմանյան ուժերի՝ Անթալիան պաշարելով. բեյլիքի վերջին կարևոր անձը՝ Օսման Չելեբին, վերացվեց։ Այսպիսով Միջերկրական ծովի ափի Թեքե գավառը քսանմեկ տարվա անջատումից հետո վերջնականապես միացավ օսմանցիներին։ Բեյլիքը, որպես Համիդ-օղլուներից անջատված ճյուղ, 1321 թվականից իշխում էր Անթալիայում։", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Թուրահան բեյի Մորեայի արշավանքը և Հեքսամիլիոն պարսպի կործանումը", "c6c2706d"], "d": ["Բյուզանդիայի՝ գահի մրցակից Մուստաֆա Չելեբիին աջակցելու առիթով Մուրադ II-ը Թուրահան բեյին ուղարկեց Մորեայի վրա։ Թուրահան բեյը, քանդելով Կորնթոսի պարանոցը ծայրից ծայր փակող Հեքսամիլիոն պարիսպը, մտավ թերակղզի և մեծ ավերածություններ պատճառեց։ Խաղաղությունը ձեռք բերվեց այն պայմանով, որ պարիսպն այլևս չկառուցվի և վճարվի տարեկան հարկ. Մորեայի դեսպոտությունը այսպիսով, ռազմական առումով անպաշտպան թողնվելով, 1460 թվականի վերջնական նվաճման հիմքը նախապատրաստվեց երեսունյոթ տարի առաջ։", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Աթոս լեռան (Այնարոզ) վանքերի անցումը օսմանյան հովանավորության տակ", "562de5ea"], "d": ["Սալոնիկի պաշարման տարիներին Խալկիդիկեի արևելյան թերակղզու Աթոսի վանական հանրապետությունը դիմեց Մուրադ II-ին, հովանավորություն խնդրեց և ընդունեց օսմանյան տիրապետությունը։ Վանականների սեփականության և պաշտամունքի իրավունքները երաշխավորվեցին. վանքերը հարկի դիմաց թողնվեցին ներքին գործերում ազատ։ Այս կարգը դարձավ օսմանցիների՝ ուղղափառ հաստատությունների հետ հաստատած հովանավորական հարաբերության ամենաերկարակյաց օրինակը և տևեց հինգ դար։", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Թաջեդդին-օղլուների բեյլիքի բռնակցումը՝ Նիկսար", "370ffd47"], "d": ["Ամասիայի բեյլերբեյ Յորգյուչ փաշայի ճնշման հետևանքով Թաջեդդին-օղլու Հյուսամեդդին Հասան բեյը 830 (1427) թվականին հանձնեց Նիկսար կենտրոնով իր երկրի բանալիները. նրան Ռումելիում սանջակ տրվեց։ Այսպիսով ավարտվեց XIV դարի երկրորդ կեսին հիմնված և սահմաններով ժամանակ առ ժամանակ մինչև Քելքիթ, Ամասիա, Սամսուն, Օրդու և Կիրասոն ձգվող բեյլիքը։ Նույն տարում Հաջիէմիր-օղլուներին պատկանող հողերը ևս հաշվառվեցին (թահրիր) և կապվեցին Ջանիքի սանջակին. Միջին Սևծովյան շրջանում փակվեց բեյլիքների դարաշրջանը։", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Բելգրադի թողնվելը Հունգարիային. Տատայի պայմանագիրը", "62481183"], "d": ["Սերբ դեսպոտ Ստեֆան Լազարևիչի մահից հետո Հունգարիայի թագավոր Սիգիզմունդի և նրա ժառանգ Գեորգ Բրանկովիչի միջև կնքված Տատայի պայմանագրի համաձայն՝ Բելգրադի բերդը փոխանցվեց Հունգարիային։ Դանուբի և Սավայի միախառնման կետում կանգնած բերդը մինչ այդ գտնվում էր սերբական դեսպոտության ձեռքում և Օսմանյան պետության համար դեպի Կենտրոնական Եվրոպա բացվող դռան փականն էր։ Այս փոխանցումը Բելգրադը հարյուր տարով դարձրեց օսմանյան առաջխաղացման առջև ամենակոշտ խոչընդոտը. 1440 և 1456 թվականների պաշարումները ձախողվելու էին, և բերդն ընկնելու էր միայն 1521 թվականին։", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Մարդինը կարա-կոյունլու պահապանից անցավ ակ-կոյունլու Կարայուլուք Օսման բեյին", "d82bc97f"], "d": ["1409 թվականին Կարա Յուսուֆի գրաված Մարդինը կարա-կոյունլուները կառավարեցին կուսակալներով. որպես պահապան թողնված էմիր Նասիրը 835 (1432) թվականին քաղաքը հանձնեց ակ-կոյունլու Կարայուլուք Օսման բեյին։ Ակ-կոյունլուների կառավարումը տևեց մինչև XVI դարի սկիզբը։", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Կարամանյանները Կեսարիան վերցրին Դուլկադիրյաններից", "2b09e8e8"], "d": ["Կարամանի բեյը Դուլկադիրյանների դեմ տարած հաղթանակով իր երկրին միացրեց Կեսարիան, Ուրգյուփը, Դևելի Քարահիսարը և Ուչհիսարը։", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Բուչուքթեփեի դեպքը — ենիչերիների առաջին ապստամբությունը և Մուրադ II-ի վերադարձը գահին", "6388dda1"], "d": ["Էդիրնեում բռնկված և պատմությանը հայտնի առաջին ենիչերիական ապստամբությունը եղած Բուչուքթեփեի դեպքը սկսվեց ռոճիկները կես ակչեով ավելացնելու պահանջով և ավարտվեց երիտասարդ Մեհմեդ II-ի գահազրկմամբ։ Մուրադ II-ը 850 թվականի Սաֆարի 8-ին, շտապ ճանապարհ ելնելով Մանիսայից, սկսեց իր երկրորդ գահակալությունը։ Իրադարձությունը դարձավ առաջին նշանն այն բանի, որ կապիկուլու (արքունական) զորաբանակն այժմ գահի հարցում ձայն ունեցող ուժ էր դարձել, և ձևավորեց Ֆաթիհի՝ ենիչերիների նկատմամբ ողջ կյանքում տևելիք զգուշավորությունը։", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Էպիրոսի ափի միացումը՝ Արտա և Պրևեզա", "796f7ecf"], "d": ["1430 թվականին Յանինայի հանձնումից տասնինը տարի անց Էպիրոսի դեսպոտության ափամերձ հատվածի Արտան և Պրևեզան ևս անցան օսմանյան կառավարման։ Այսպիսով վերահսկողության տակ վերցվեց Իոնիական ծով բացվող Ամբրակիայի ծոցը, և ամբողջացավ Յանինայի ծովային կապը։ Պրևեզան այն ծոցի բանալի կետն է, որը իննսուն տարի անց իր անունը տալու էր Բարբարոսայի պատմության մեջ մտնելիք հաղթանակին։", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Մուրադ II-ի մահը և Մեհմեդ II-ի երկրորդ գահակալումը", "8f8256ad"], "d": ["Որդու հարսանիքից հետո հիվանդացած Մուրադ II-ը 855 թվականի Մուհառամի 1-ին (1451 թվականի փետրվարի 3) մահացավ Էդիրնեում։ Տասնինը տարեկան Մեհմեդ II-ը 855 թվականի Մուհառամի 16-ին (1451 թվականի փետրվարի 18) երկրորդ անգամ բարձրացավ օսմանյան գահ՝ այս անգամ մշտապես։ Հինգ տարի առաջ Բուչուքթեփեում գահազրկված երիտասարդ տիրակալի վերադարձը սկիզբն է այն գահակալության, որը երկու տարի անց պսակվելու էր Կոստանդնուպոլսի նվաճմամբ և Օսմանյան բեյլիքը վերածելու էր համաշխարհային կայսրության։", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Օսմանա-ղրիմյան միացյալ ուժերի առաջին պաշարումը Կաֆայի", "e346d163"], "d": ["1454 թվականի հունիսին սուլթան Մեհմեդ Ֆաթիհի հետ համաձայնության եկած Ղրիմի խան Հաջի Գիրեյը իր 7000 ձիավորով ցամաքից պաշարեց Կաֆան. հիսուն-վաթսուն գալերաներից բաղկացած օսմանյան նավատորմը ևս դիրք գրավեց բաց ծովում։ Ջենովական Կաֆան խարաջ վճարելով վերացնել տվեց պաշարումը, և վերջնական նվաճումը մնաց քսանմեկ տարի հետո՝ 1475 թվականին։ Այս առաջին համատեղ գործողությունը օսմանա-ղրիմյան ռազմական համագործակցության առաջին օրինակն էր, որը հետագայում կրկնվելու էր Կաֆայի վերջնական նվաճման ժամանակ։", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Հյուսիսէգեյան կղզիների գրավումը՝ Տենեդոս, Իմբրոս և Թասոս", "76575895"], "d": ["Կոստանդնուպոլսի նվաճումից անմիջապես հետո սուլթան Մեհմեդ Ֆաթիհը, նոր մայրաքաղաքի ծովային ճանապարհն ապահովելու համար, ուղղվեց Դարդանելի նեղուցի էգեյան մուտքի կղզիներին. Տենեդոսը և Իմբրոսը վերցվեցին Բյուզանդիայից, իսկ Թասոսը՝ ջենովական ծագմամբ Գատիլուզիո ընտանիքից։ Նեղուցի երկու ափերը կողպող այս կղզիները դրանից հետո դարձան Ստամբուլի պարենավորման և պաշտպանության գծի առաջին օղակը։ Պապականության և Վենետիկի նավատորմերի միջամտություններով տիրապետությունը որոշ ժամանակ ձեռքից ձեռք էր անցնում և վերջնականապես հաստատվեց միայն 1459 թվականին։", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Կոսովոյի նվաճումը՝ Պրիշտինայի և Ենիփազարի գրավումը", "d7ed2345"], "d": ["Սերբական դեսպոտության վրա շարժված օսմանյան բանակը գրավեց Կոսովոյի դաշտի Պրիշտինան և Ռաշկայի շրջանի կենտրոն Ենիփազարը. նույն գործողությունների ընթացքում գրավվեց նաև արծաթի հանքերով հայտնի Նովո Բրդոն։ Այսպիսով Սերբիայի հարավային կեսը կապվեց ուղղակի օսմանյան կառավարմանը, և Սմեդերևոյի դեսպոտությունը կտրվեց իր կենտրոնական հողերից։ Այս նվաճումը որոշիչ քայլն էր դեպի Սերբիայի՝ չորս տարի անց ամբողջական բռնակցումը տանող ճանապարհին։", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Պեչը (İpek) անցավ օսմանյան կառավարման — Դուկագինի սանջակի կենտրոններից", "19511588"], "d": ["1455 թվականին սուլթան Մեհմեդ Ֆաթիհի սերբական արշավանքից անմիջապես հետո սերբական պատրիարքության կենտրոն Պեչը անցավ օսմանյան կառավարման. օսմանյան աղբյուրներում այս անցման մասին գրառում չկա։ Ավանը ժամանակի ընթացքում դարձավ փոքր մուսուլմանական ավան և Դուկագինի սանջակում եղավ սանջակբեյի նստավայրերից մեկը։", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Էնեզի և Սամոթրակեի նվաճումը — Արևմտյան Թրակիայի ափի ամբողջացումը", "106e723b"], "d": ["Մարիցա գետի ծով թափվելու վայրի Էնեզը վերցվեց ութսուն տարի այն իր ձեռքում պահած ջենովական ծագմամբ Գատիլուզիո ընտանիքից. դրան կապված Սամոթրակե կղզին ևս գրավվեց նույն գործողությունների ընթացքում։ Էնեզի անկմամբ Արևմտյան Թրակիայի ափամերձ շերտը Սալոնիկից մինչև Գելիբոլու դարձավ անընդհատ օսմանյան հող։ Գատիլուզիո ընտանիքի ձեռքում մնաց միայն Լեսբոսը. այն էլ վեց տարի անց վերցվելու էր։", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Բելգրադի պաշարման ձախողումը", "3d53a604"], "d": ["Սուլթան Մեհմեդ Ֆաթիհը Կոստանդնուպոլսի նվաճումից հետո պաշարեց Կենտրոնական Եվրոպայի բանալին համարվող Բելգրադը. սակայն Յանոշ Հունյադիի՝ Դանուբով բերած համալրումը և խաչակրաց քարոզիչ Կապիստրանոյի հավաքած կամավորները կանխեցին ամրոցի անկումը։ Փադիշահը, չնայած պաշարման ժամանակ ցուցաբերած անձնական հերոսությանը, վիրավորվելով ստիպված եղավ նահանջել։ Այս ձախողումը Հունգարիայի սահմանը վաթսունհինգ տարի փակելու էր օսմանյան առաջխաղացման առաջ. Բելգրադը միայն 1521 թվականին կարող էր գրավել Քանունին։", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Հյուսիսային Մորեայի նվաճումը՝ Բալյաբադրա (Պատրաս)", "c08a8509"], "d": ["Սերբիայի բռնակցման հետ նույն տարիներին Մորեայի դեսպոտության դեմ ուղղված սուլթան Մեհմեդ Ֆաթիհի ուժերը գրավեցին թերակղզու հյուսիսարևմուտքի Բալյաբադրան։ Կորնթոսի ծոցի մուտքը պահող այս նավահանգիստը Մորեա ցամաքով մտնելու բանալին է. դրա գրավումը հիմք նախապատրաստեց երկու տարի հետո կատարված վերջնական նվաճման համար։ Քաղաքը բյուզանդական դեսպոտների՝ լատինական աշխարհի հետ կապ հաստատող վերջին մեծ նավամատույցն էր։", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Արևմտյան Սևծովյան ափի գրավումը՝ Ամասրա", "f43608fc"], "d": ["Արևմտյան Սևծովյան ափի ամրացված ջենովական գաղութ Ամասրան, սուլթան Մեհմեդ Ֆաթիհի նավատորմի և ցամաքային ուժերի համատեղ ճնշման հետևանքով, հանձնվեց առանց դիմադրության։ Բարթըն-Զոնգուլդակ ափի այս նավահանգիստը որպես լատինական գրպան մնում էր Ջանդարյանների և օսմանյան հողերի միջև. դրա գրավմամբ ափը ամբողջացավ։ Ամասրայի անկումը երկու տարի հետո (1461) Սինոպի և Տրապիզոնի վրա ուղղվելիք մեծ սևծովյան արշավանքի առաջին քայլն է։", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Լեսբոս կղզու նվաճումը", "fe17aeba"], "d": ["Սուլթան Մեհմեդ Ֆաթիհի հրամանատարությամբ օսմանյան բանակը 866 թվականի Զու-լ-հիջջային կարճ, բայց կատաղի պաշարումից հետո Լեսբոսը խլեց ջենովական ծագմամբ Գատիլուզիո ընտանիքի ձեռքից և բռնակցեց։ Հյուսիսային Էգեյանի ամենամեծ կղզու անկումը վերացրեց նաև ջենովացիների՝ շրջանի վերջին կարևոր հենակետը։ Կղզին, Անատոլիայի ափին իր մոտիկության շնորհիվ, դրանից հետո օսմանյան նավատորմի համար ծառայելու էր որպես առաջապահ պահակակետ և միաժամանակ ծովագնացության պատմության մեջ մտնելու էր որպես Բարբարոսա եղբայրների ծնունդի ու դաստիարակության վայր։", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Տասնվեցամյա օսմանա-վենետիկյան պատերազմի սկիզբը", "563ddb68"], "d": ["Վենետիկցիները, օսմանցիների՝ Մորեայում և Էգեյան ծովում առաջխաղացումը կանգնեցնելու համար, դաշնակցելով Կարամանի և Ակ-Կոյունլուի ղեկավարների հետ, 1463 թվականին սկսեցին պատերազմը։ Արևելքում Ուզուն Հասանի, արևմուտքում Վենետիկի և միջանկյալ Կարամանի միջոցով ստեղծված այս շրջապատման ռազմավարությունը Ֆաթիհին ստիպեց միաժամանակ կռվել մի քանի ճակատներում։ Տասնվեց տարի տևած պայքարը ընդգրկելու էր ժամանակաշրջանի բոլոր մեծ գործողությունները՝ Օթլուքբելիից մինչև ալբանական արշավանքները, և ավարտվելու էր միայն 1479 թվականի Ստամբուլի պայմանագրով։", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Հերցեգովինայի մեծ մասի նվաճումը՝ Տրեբինյե և Մոստար", "f54c0100"], "d": ["Բոսնիայից առանձին կառավարում հաստատած Հերցեգովինայի դուքս Ստեփան Վուկչիչ-Կոսաչայի հողերը Բոսնիայի թագավորության կործանումից երեք տարի անց մեծ մասամբ անցան օսմանյան կառավարման. հարավում Տրեբինյեն 1466 թվականին գրավվեց «գրեթե ամբողջ Հերցեգովինայի շրջանի հետ»։ Նեռետվա կամրջի երկու փոքր ամրոցների շուրջ ձևավորված Մոստարը ևս, հավանաբար, վերցվել է Հերցեգովինայի կենտրոն Բլագայի 1466-1468 թվականների նվաճումից քիչ առաջ. 1468-1469 թվականների բոսնիական ամփոփ հաշվառման (իջմալ թահրիրի) մեջ այն գրանցված է «Köprülü Hisar» անունով։ Դքսության մնացած ամրոցների հետ Հերցեգովինայի նվաճումն ավարտվեց 1483 թվականին։", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Ալբանական երկրորդ արշավանքը — Ֆաթիհի անձամբ արշավը Սկանդերբեգի դեմ", "9cdd2bfa"], "d": ["Սկանդերբեգի ավելի քան քառորդ դար տևած դիմադրությունը կոտրելու համար սուլթան Մեհմեդ Ֆաթիհը 1466-1467 թվականներին կազմակերպեց մեծ արշավանքներ, որոնք անձամբ ղեկավարեց։ Օսմանյան բանակը պաշարեց Կրույան (Akçahisar) և, շրջանը վերահսկողության տակ առնելու համար, կառուցեց Էլբասանի (İlbasan) ամրոցը։ Արշավանքը, թեև կոտրեց ալբանական դիմադրության մեջքը, չկարողացավ գրավել ամրոցը. շրջանի լիակատար հպատակությունը պահանջելու էր Սկանդերբեգի մահից հետո ևս տասը տարի։", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Ակ-Կոյունլուների առաջապահ ուժերը Բինգյոլի բերդը գրավեցին Կարա-Կոյունլուներից", "51b94cbc"], "d": ["Ուզուն Հասանի դեմ Ջիհան Շահի ձեռնարկած արշավանքի վերջին շաբաթներին Ակ-Կոյունլուների առաջապահ ուժերը գրավեցին Բինգյոլի բերդը. 1467 թ. նոյեմբերի 10-ին Ջիհան Շահի սպանությամբ Կարա-Կոյունլուների տիրապետությունը տարածաշրջանում ավարտվեց։", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Կարա-Կոյունլու պետության փլուզումը՝ Ջիհան շահի սպանությունը", "30bc6358"], "d": ["Ուզուն Հասանի դեմ ձեռնարկած արշավանքից ձմռան վրա հասնելու պատճառով վերադառնալիս հարձակման ենթարկված կարա-կոյունլուների տիրակալ Ջիհան շահը փախուստի ժամանակ սպանվեց Բինգյոլի և Քղիի միջև։ Այս հարվածից հետո պետությունը չկարողացավ ուշքի գալ. վերջին տիրակալ Հասան Ալին 1469 թվականին գերի վերցվեց և սպանվեց Ուզուն Հասանի որդի Ուղուրլու Մեհմեդի կողմից։ Այսպիսով Արևելյան Անատոլիայում, Ատրպատականում և Իրաքում մոտ մեկ դար իշխած կարա-կոյունլուների տիրապետությունը անցավ ակ-կոյունլուներին։", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Սկանդերբեգի մահը — ալբանական դիմադրության մարումը", "9158c35f"], "d": ["Օսմանյան պալատում դաստիարակված, բայց 1444 թվականին Զլատիցայի ջախջախումից հետո ապստամբած և ավելի քան քառորդ դար Ալբանիայում դիմադրած Սկանդերբեգը մահացավ Լեժայում, ուր ապաստանել էր։ Մուրադ II-ի և Ֆաթիհի օրոք օսմանյան բանակները բազմիցս զբաղեցրած այս դիմադրությունը նրա մահով կորցրեց կենտրոնական առաջնորդությունը։ Պապականության և Վենետիկի սնուցած ալբանական ճակատի փլուզմամբ օսմանցիները տասը տարվա ընթացքում գրավեցին Կրույան և Շկոդերը և շրջանը վերջնականապես միացրին իրենց հողերին։", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Կայսերիում հաստատվեց օսմանյան կառավարում. Գեդիք Ահմեդ փաշան վերջ դրեց Կարամանօղուլներին", "33cf35fc"], "d": ["1474 թ. Գեդիք Ահմեդ փաշայի կողմից Կարամանօղուլներին վերջ դնելով՝ Կայսերին անցավ օսմանյան կառավարման տակ. 15-րդ դարի ընթացքում քաղաքը ձեռքից ձեռք էր անցել Դուլկադիրօղուլների, Ռամազանօղուլների և Կարամանօղուլների միջև։ Օսմանյան իշխանության օրոք Կայսերին դարձավ Կարամանի բեյլերբեյության սանջակի կենտրոն։", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Սամոսը լքվեց. ջենովական (Մահոնա) սեփականությունը դադարեց", "5bdc380c"], "d": ["Ըստ TDV-ի՝ կղզին լքվեց 1475 թվականից հետո. 1479 թ. Մեհմեդ II Ֆաթիհը (Նվաճողը) գրավեց կղզին և այնտեղ բերդ կառուցել տվեց։", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Ռակովայի (Վասլույ) ջախջախումը Մոլդովայում", "a1a74bf7"], "d": ["Մոլդովայի վոյևոդ Ստեփանոս Մեծը (Stefan cel Mare) Ռումելիի բեյլերբեյ Հադըմ Սուլեյման փաշայի հրամանատարությամբ օսմանյան ուժերը ճահճոտ տեղանք քաշելով ծանր պարտության մատնեց։ Ֆաթիհի շրջանի ամենածանր ցամաքային պարտություններից մեկը եղած այս ջախջախումը Եվրոպայում մեծ արձագանք առաջացրեց և Ստեփանոսին խաչակրաց աշխարհում համբավ բերեց։ Փադիշահը հաջորդ տարի վրեժխնդրության համար անձամբ ելնելու էր արշավանքի։", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Ակդերեի (Valea Albă) հաղթանակը — մոլդովական արշավանքը", "45a66791"], "d": ["Մեկ տարի առաջվա Ռակովայի ջախջախման վրեժը լուծելու համար անձամբ արշավանքի ելած սուլթան Մեհմեդ Ֆաթիհը օսմանյան բանակով Ակդերե վայրում մեծ պարտության մատնեց մոլդովական զորամասերին և մտավ իշխանության կենտրոն Սուչավան։ Սակայն ամրոցները չգրավվեցին. պարենի նեղության, ենիչերիների մեջ բռնկված ժանտախտի և հունգարական նախապատրաստությունների պատճառով բանակը ստիպված եղավ նահանջել։ Մոլդովայի վերջնական հպատակությունը կարող էր ապահովվել միայն հաջորդ տարիներին՝ 1484 թվականին Կիլիայի և Ակկերմանի գրավմամբ։", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Կրույայի (Akçahisar) նվաճումը և Ալբանիայի նվաճման ամբողջացումը", "559a79b4"], "d": ["Սկանդերբեգի մահից տասը տարի անց՝ 1478 թվականին, Կրույայի, Դրիվաստոյի, Լեժայի և Ժաբլյակի գրավմամբ Ալբանիայի նվաճումը մեծ մասամբ ավարտվեց։ Տարիներ շարունակ օսմանյան բանակներին դիմադրած և Սկանդերբեգի դիմադրության խորհրդանիշ եղած Կրույայի ամրոցի անկումը նշանակում էր շրջանում վենետիկա-ալբանական դաշինքի ավարտը։ Մնացած Շկոդերը հաջորդ տարի ստորագրվելիք Ստամբուլի պայմանագրով թողնվելու էր օսմանցիներին։", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Թաման թերակղզու միացումը", "4ef917b8"], "d": ["1475 թվականին Կաֆայի և Կերչի գրավումից հետո սուլթան Մեհմեդ Ֆաթիհի կովկասյան ափեր ուղարկած նավատորմը Անապայի և Կոպայի հետ միասին գրավեց Թաման թերակղզու ջենովական Մատրեգան (Թամաթարխան)։ Այսպիսով վերահսկողության տակ վերցվեցին նեղուցի երկու ափերը, և Ազովի ծով մուտքը դարձավ լիովին վերահսկելի։ Թամանը որպես Հյուսիսային Կովկաս բացվող դուռ կապվեց Կաֆայի սանջակին։", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Սամոսն անցավ օսմանյան կառավարման տակ (Ֆաթիհ)", "c877bc14"], "d": ["Սուլթան Մեհմեդ II Ֆաթիհը նվաճեց Սամոսը, բերդ կառուցել տվեց և վերակազմակերպեց մարդահամարը. 1483 թ. Բայազիդ II-ը քաղաքական պատճառներով քանդել տվեց բերդը։", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Ռոդոսի պաշարման ձախողումը", "35a85c28"], "d": ["Սուլթան Մեհմեդ Ֆաթիհի հրամանով Մեսիհ փաշայի հրամանատարությամբ 160 նավից բաղկացած նավատորմը 885 (1480) թվականի գարնանը պաշարեց Ռոդոսը, և կղզին երեք ամիս մնաց շրջափակման մեջ։ Մեծ մագիստրոս Պիեռ դ'Օբյուսոնի գլխավորությամբ Սուրբ Հովհաննեսի ասպետները, չնայած ծանր կորուստներին, կատաղի դիմադրեցին. 885 թվականի Ջումադա ալ-ուլայի 20-ին կատարված վերջին մեծ գրոհի ևս հետ մղվելուց հետո նավատորմը օգոստոսի 3-ին նահանջեց։ Այս ձախողումից հետո քաղաքի պարիսպները հիմնովին վերանորոգվելով վերածվեցին Եվրոպայի ամենաուժեղ ամրության, և կղզին կարողացավ գրավել միայն Քանունին 1522 թվականին։", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Նիկարիան (Իկարիան) անցավ Հռոդոսի Սուրբ Հովհաննեսի ասպետների կառավարման տակ", "5cbc2669"], "d": ["Սամոսի և Քիոսի միջև գտնվող Նիկարիան 1481-1521 թթ. գտնվում էր Հռոդոսի Սուրբ Հովհաննեսի ասպետների կառավարման ներքո։", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Ենիշեհիրի ճակատամարտը — Ջեմ սուլթանի պարտությունը", "c35abee2"], "d": ["Ֆաթիհի մահից հետո գահի համար շարժման մեջ մտած երկու եղբայրները դեմ հանդիման կանգնեցին Ենիշեհիրի դաշտում, և Ջեմ սուլթանը վճռական պարտություն կրեց։ Բուրսայում տասնութ օր իշխած և իր անունով խուտբա կարդացնել տված շահզադեն պարտությունից հետո ստիպված եղավ ապաստանել նախ Կոնիա, այնտեղից՝ մամլուքների հողերում։ Ենիշեհիրը սկիզբ դրեց օսմանյան պատմության ամենաերկարաշունչ հարստական ճգնաժամին. Ջեմի հարցը տասնչորս տարի կաթվածահար անելու էր օսմանյան արտաքին քաղաքականությունը Եվրոպայի դիմաց։", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Հերցեգովինայի բռնակցումը", "bf247891"], "d": ["1463 թվականին Բոսնիայի նվաճումից հետո կանգուն մնացած Հերցեգովինայի դքսության հողերը փուլ առ փուլ անցան օսմանյան կառավարման. Տրեբինյեն և Մոստարը գրավվել էին 1466 թվականին, Հերցեգովինայի սանջակը ստեղծվել էր 1470 թվականին, դքսության Ադրիատիկի ափի վերջին հողերը ևս, Հերցեգ Նովիի հետ միասին, նվաճվել էին 1482 թվականի սկզբին և միացվել սանջակին։ Այսպիսով Ադրիատիկի թիկունքի լեռնային շրջանն ամբողջությամբ դարձավ օսմանյան, և Բոսնիան ու Հերցեգովինան վերածվեցին մեկ վարչական աշխարհագրության։ Վերջին դքսի՝ օսմանյան պալատ մտած որդին Հերսեքզադե Ահմեդ փաշան է, որը հետագայում հասնելու էր մինչև մեծ վեզիրություն։", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Զակինթոսի (Զաքլիսե) թողնվելը Վենետիկին տարեկան հարկի դիմաց", "268a691a"], "d": ["Ֆաթիհի դարաշրջանի վերջում Տոկկո ընտանիքից վերցված Հոնիական կղզիներից Զակինթոսը Վենետիկին թողնվեց այն ժամանակ, երբ Ջեմ Սուլթանի հարցով զբաղված նոր փադիշահը Արևմուտքում հանգստություն էր փնտրում։ Կղզին փոխանցվեց վենետիկյան կառավարման, որը ճանաչում էր օսմանյան տիրակալությունը և վճարում էր տարեկան հինգ հարյուր դուկատ հարկ։ Այսպիսով Հոնիական ծովում ուղղակի օսմանյան կառավարումը մնաց միայն Այա Մավրայում։", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Ջեմ սուլթանի ապաստանը Ռոդոսում", "2228d6da"], "d": ["Կոնիան պաշարելու փորձն էլ անարդյունք մնացած Ջեմ սուլթանը մոտ երեսուն մարդով փախավ Անատոլիայից և հասավ Ռոդոս, ուր Սուրբ Հովհաննեսի ասպետները նրան դիմավորեցին արարողությամբ։ Սակայն հյուրընկալությունը կարճ ժամանակում վերածվեց գերության. շահզադեն փոխանցվեց նախ Ֆրանսիա, ապա Պապականությանը և դարձավ եվրոպական քաղաքականության ձեռքի խաղաքարտ։ Բայազիդ II-ը ստիպված եղավ եղբոր պահվելու դիմաց տարեկան վճարում կատարել, և օսմանցիների՝ Արևմուտքի դեմ ուղղված ռազմական քայլերը մինչև Ջեմի մահը կասեցվեցին։", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Օսմանա-մամլուքյան պատերազմի սկիզբը (կիլիկյան ճակատ)", "3fe3f0c7"], "d": ["Դուլկադիրյանների նկատմամբ ազդեցության պայքարը և Ջեմ սուլթանի՝ մամլուքների հողերում ապաստանելու թողած թշնամանքը 1485 թվականին երկու սուննի մեծ ուժերի միջև սկիզբ դրեցին վեց տարի տևելիք պատերազմի։ Կիլիկիայում՝ Ադանայի և Տարսոնի շրջակայքում տեղի ունեցած ընդհարումներում կողմերը չկարողացան առավելություն ձեռք բերել միմյանց նկատմամբ. օսմանյան բանակները մի քանի ծանր հարված ստացան։ Այս պատերազմը օսմանա-մամլուքյան հարաբերությունների բեկման առաջին փուլն է և սկիզբն այն գործընթացի, որը երեսուն տարի անց ավարտվելու էր Յավուզի Մարջ Դաբիկի և Ռիդանիայի արշավանքներով։", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Օսմանա-մամլուքյան հաշտությունը — Թունիսի միջնորդությունը", "60dd6719"], "d": ["1485 թվականին սկսված օսմանա-մամլուքյան պատերազմում կողմերը վճռական հաղթանակի չհասան. Թունիսի տիրակալ Օսման Հաֆսիի միջնորդությամբ 1491 թվականին հասան համաձայնության։ Պայմանագիրը սահմանները մեծ մասամբ վերադարձրեց մինչպատերազմյան վիճակին, և երկու իսլամական պետությունների հաշվեհարդարը հետաձգվեց մեկ սերնդով։ Վեցամյա հյուծիչ պայքարը Բայազիդ II-ի զգուշավոր արտաքին քաղաքականության և դեպի արևելք շարժվելու փոխարեն ներքին կարգավորումներին կարևորություն տալու գլխավոր պատճառներից է։", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Իսպանիայից վտարված սեֆարդ հրեաների ընդունումը Օսմանյան պետություն", "5c2b5c24"], "d": ["Գրանադայի անկումից հետո Իսպանիայում ինկվիզիցիայի հալածանքներից փախած հրեաների մի մասը, ապաստանելով օսմանյան հողերում, բնակեցվեց տարբեր քաղաքներում։ Օսմանյան կառավարման տակ այս սեֆարդ համայնքները ձեռք բերեցին մինչ այդ օրը չտեսած ազատություն՝ բնակվել ուր կամենան, ապրել իրենց հավատով, բացել կրթական հաստատություններ և կառուցել նոր սինագոգներ։ Իրենց հետ բերած տպագրության, բժշկության և ֆինանսների գիտելիքներով Սալոնիկի և Ստամբուլի տնտեսական կյանքը վերափոխած այս գաղթը դարձավ օսմանյան հանդուրժողականության կարգի՝ Եվրոպայում ամենաշատ խոսվող օրինակը։", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Ջեմ Սուլթանի մահը. տասնչորսամյա պատանդության ավարտը", "f6588b70"], "d": ["Պապությունից Ֆրանսիայի թագավոր Շառլ VIII-ին հանձնված Ջեմ Սուլթանը 1495 թվականի հունվարի 27-ին Հռոմից ճանապարհ ընկնելուց հետո մահացավ Castel Capuana կոչվող վայրում. աղբյուրները նշում են, որ նա հնարավոր է թունավորված լինի պապական շրջանակների կողմից։ Տասնչորս տարի շարունակ եվրոպական պետությունների ձեռքում Օսմանյան պետության դեմ որպես սպառնալիքի խաղաքարտ պահված շահզադեի մահը վերջապես ազատեց Բայազիդ II-ի ձեռքերը։ Եվ իրոք, փադիշահն այնուհետև պատերազմ հայտարարեց Վենետիկին և իր նավատորմը առաջնորդեց դեպի նրա առաջին մեծ հաղթանակը։", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Սապիենցայի (Զոնկիո) ծովային հաղթանակը. նավատորմի առաջին մեծ հաջողությունը Միջերկրական ծովում", "9754aaef"], "d": ["Ջեմի հարցի ավարտով ձեռքերն ազատված Բայազիդ II-ը 1499 թվականին պատերազմ հայտարարեց Վենետիկին. օսմանյան նավատորմը Սապիենցայի (Զոնկիո) ափերի մոտ հաղթեց վենետիկյան նավատորմին և Միջերկրական ծովում տարավ իր առաջին խոշոր ծովային հաղթանակը։ Այս հաղթանակով նավատորմը փաստորեն հայտարարեց, որ այսուհետ կարող է ծովում դիմակայել Վենետիկին։", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Կեֆալոնիայի և Իթակայի կորուստը", "60f0f687"], "d": ["Մոդոնի և Կորոնի վերցնելուց ցնցված Վենետիկը, միավորվելով Իսպանիայի հետ, անցավ հակահարձակման և պաշարեց 1479 թվականից օսմանյան ձեռքում գտնվող Կեֆալոնիան։ Քառասունյոթ օր տևած դիմադրությունից հետո բերդն ընկավ, կղզին Իթակայի հետ անցավ Վենետիկին և երեք հարյուր տարի չվերադարձավ օսմանյան կառավարման տակ։ Այս կորուստը ստեղծեց հավասարակշռություն, երբ Մորեայում ձեռք բերածը հետ տրվեց Հոնիական ծովում։", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Ոսկե Հորդայի խանության անկումը և Ղրիմի վերելքը", "0d1dc515"], "d": ["Նրա վերջին տիրակալ Շեյխ Ահմեդ խանը (1481-1502) չկարողացավ երկիրը փրկել այն ճգնաժամից, որի մեջ այն հայտնվել էր, և 1502 թվականին Ղրիմի խան Մենգլի Գիրեյի հարվածով Ոսկե Հորդայի խանությունը պատմության գիրկն անցավ։ Գահակալական կռիվների և մասնատման հետևանքով Ոսկե Հորդայի նախկին տարածքներում առաջացան Ղրիմի, Կազանի, Նողայի, Աստրախանի և Սիբիրի խանությունները։ Օսմանյան հովանավորության տակ գտնվող Ղրիմի այս հաղթանակը Սև ծովից հյուսիս օսմանյան ազդեցությունը դարձրեց անվիճելի, իսկ տարածաշրջանում առաջացած դատարկությունը հաջորդ դարում լրացնելու էր Մոսկվան։", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Օսմանյան-վենետիկյան պատերազմի ավարտը և հաշտությունը", "125b1526"], "d": ["1499 թվականին սկսված և Սապիենցայով, ինչպես նաև Լեպանտոյի, Մոդոնի ու Կորոնի կորստով Վենետիկը ցնցած պատերազմը 1502 թվականին ավարտվեց հաշտությամբ։ Մորեայում իր կարևորագույն հենակետերը կորցրած Վենետիկը, Արևելյան Միջերկրականում իր առևտրական արտոնությունները պահպանելու դիմաց, ստիպված էր ճանաչել օսմանյան գերակայությունը։ Բայազիդ II-ի զգուշավոր համարվող կառավարումը այս պատերազմով Օսմանյան պետությունը առաջին անգամ բարձրացրեց Միջերկրական ծովում լուրջ ծովային ուժի դիրքի։", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Շահկուլուի ապստամբությունը. ղզլբաշական խռովություն Թեքեի շրջանից մինչև Սեբաստիա", "3beadca7"], "d": ["Անատոլիայում սեֆյան քարոզչության ազդեցությամբ 1510 թվականին իր ապստամբությունը բացահայտած Շահկուլու Բաբա Թեքելին 1511 թվականի մարտին հարձակվեց Անթալիայի շուկայի վրա, իսկ ապրիլին Քյոթահիայում ու նրա շրջակայքում հաղթեց օսմանյան ուժերին։ Սեբաստիայի մոտ մեծ վեզիր Հադըմ Ալի փաշայի հետ նրա վերջին ընդհարման ժամանակ երկու կողմերն էլ ծանր կորուստներ կրեցին. կյանքը կորցրին և՛ մեծ վեզիրը, և՛ ապստամբության առաջնորդը։ Անատոլիայում պետության հեղինակությունը խարխլած այս ապստամբությունը ի ցույց դրեց Բայազիդ II-ի վերջին տարիների իշխանության դատարկությունը և դարձավ շահզադե Սելիմի՝ դեպի գահ ընթացքի ամենահիմնավոր պատճառը։", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Բայազիդ II-ի հրաժարումը գահից և Յավուզ Սուլթան Սելիմի գահակալումը", "c4cfab69"], "d": ["Եղբայրների հետ գահի համար մղած պայքարում ենիչերիների աջակցությունը ստացած շահզադե Սելիմի ճնշմամբ Բայազիդ II-ը 1512 թվականի ապրիլի 24-ին հրաժարվեց գահից, և նույն օրը Սելիմ I-ը գահ բարձրացավ որպես օսմանյան իններորդ տիրակալ։ Ծեր փադիշահը, ուղևորվելով դեպի իր ծննդավայր Դիդիմոտիխո, ճանապարհին՝ Չորլուի մոտ գտնվող Աբալար գյուղում, վախճանվեց հիջրայի 918 թվականի Ռաբի ալ-ավվալի 25-ին (1512 թվականի հունիսի 10)։ Երեսունմեկամյա զգուշավոր և ներփակ կառավարմանը փոխարինեց Յավուզի դարաշրջանը, որն ութ տարում կրկնապատկելու էր կայսրության սահմանները։", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Սինի (Sinj) բերդի նվաճումը", "83271ea5"], "d": ["Բոսնիայի սահմանին գտնվող օսմանյան ասպատակային ուժերը Հունգարիայի թագավորությունից վերցրին Դալմաթիայի խորքերը ձգվող Սինի (Sinj) բերդը։ Սա Դալմաթիայի սահմանագծի վաղ օղակներից մեկն էր, որն ինը տարի անց ընդլայնվելու էր Ղազի Խյուսրև բեյի կողմից Կնինի և նրա շրջակայքի նվաճմամբ. բերդը 1686 թվականին կորցվելու էր հօգուտ Վենետիկի։", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Յենիշեհիրի ճակատամարտը և շահզադե Ահմեդի վերացումը", "e2ed15dd"], "d": ["Յավուզ Սուլթան Սելիմը Բուրսայի մոտ գտնվող Յենիշեհիրի դաշտում ջախջախեց գահի ամենաուժեղ հավակնորդ իր ավագ եղբորը՝ շահզադե Ահմեդին, գերի վերցրեց և վերացրեց նրան։ Այսպիսով փակվեց 1511 թվականից տևող եղբայրների կռիվը, և վերջ տրվեց Անատոլիայի ներքին պառակտմանը։ Սելիմը, ապահովելով իր թիկունքը, ազատություն ձեռք բերեց անդրադառնալու սեֆյան հարցին։", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Յավուզ Սուլթան Սելիմի մուտքը Թավրիզ", "dad2e227"], "d": ["Չալդըրանի հաղթանակից հետո օսմանյան բանակը մտավ սեֆյան մայրաքաղաք Թավրիզ, և քաղաքում խուտբան կարդացվեց փադիշահի անունով։ Սելիմն այստեղ մնաց մեկ շաբաթ և թավրիզցի արհեստավորների ու ուլեմաների մի մասին տեղափոխել տվեց Ստամբուլ. այս տեղափոխությունը խորապես ազդելու էր օսմանյան պալատական արվեստի վրա։ Թեև ձմռան մոտենալու և ենիչերիների դժգոհության պատճառով քաղաքը լքվեց, Արևելքում սեֆյան գերակայությունը կոտրված էր։ Քարտեզի վրա այս օրը Օսմանյան պետությանն անցնող վայրերը իրար կից չեն, և դա ճիշտ է. Թավրիզը ինն օր տևած ռազմական օկուպացիա է. Երզնկայի դաշտը արշավանքի ընթացքում հանձնվել է առանց կռվի, մինչդեռ նրա կենտրոնում գտնվող Կամախի բերդը մինչև 1515 թվականի մայիսի 19-ը դիմադրել է Սեֆյանների ձեռքում. Սղերդը Թավրիզում շահ Իսմայիլի բանտից ազատված Հասանքեյֆի մելիք Խալիլ բեյը, հնազանդվելով Օսմանյան պետությանը, հետ է խլել Սեֆյաններից. նրա շրջակայքում Դիարբեքիրը մինչև 1515 թվականը, իսկ Հասանքեյֆը մինչև 1517 թվականը մնացել են սեֆյան։", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Մուշը և Բինգյոլը (Չապաքչուր) Սեֆյաններից անցան օսմանյան կառավարման տակ", "b0a53b5a"], "d": ["Չալդըրանից հետո Արևելյան Անատոլիան Սեֆյաններից գրավելու ընթացքում Մուշը 921/1515 թ. անցավ օսմանյան կառավարման տակ. հարևան Չապաքչուրը (Բինգյոլ) նույն գործընթացում միացավ Օսմանյան պետությանը։", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Կամախի բերդի նվաճումը Սեֆյաններից", "73fd8671"], "d": ["Չալդըրանից վերադարձին ձմեռը Ամասիայում անցկացրած Յավուզ Սուլթան Սելիմը Եփրատի անցման կետը հսկող ամրացված Կամախի բերդի նվաճումը հանձնարարեց Բըյըքլը Մեհմեդ փաշային։ Փադիշահի անձամբ մասնակցությամբ պաշարման ավարտին բերդը խլվեց Սեֆյաններից, և Արևելյան Անատոլիայի դուռը բացվեց։ Այս նվաճումը առաջին կոնկրետ քայլն էր, որը Չալդըրանի հաղթանակը վերածեց մնայուն տարածքային ձեռքբերման։", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Թուրնադաղի հաղթանակը. Դուլկադիրի բեյությունը դարձավ Օսմանյան պետության վասալ", "fd879145"], "d": ["Օսմանյան ուժերը Գյոքսունի և Անդըրընի միջև գտնվող Օրդեքլի վայրում պարտության մատնեցին Դուլկադիրի բեյ Ալաուդդևլե Բոզքուրթին, որը Չալդըրանի արշավանքի ժամանակ երկդիմի դիրք էր բռնել. Ալաուդդևլեն սպանվեց այս ճակատամարտում։ Բեյությունն այդ ժամանակ չբռնակցվեց. Ալաուդդևլեից հետո Յավուզ Սուլթան Սելիմը Դուլկադիրօղուլների բեյության գլուխ դրեց Շեհսուվարօղլու Ալի բեյին, և Մարաշ-Ալբիսթան կենտրոնով երկիրը շարունակեց գոյությունը որպես Օսմանյան պետությանը վասալ բեյություն։ Այսպիսով մամլուքյան սահմանի վրա գտնվող բուֆերն անցավ օսմանյան վերահսկողության տակ, և բացվեց երկու տարի անց կայացած եգիպտական արշավանքի ճանապարհը. իսկ բռնակցումը տեղի ունեցավ Ալի բեյի սպանությունից հետո։", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Ամիդի (Դիարբեքիր) նվաճումը և Դիարբեքիրի բեյլերբեյության հիմնումը", "a6867d5b"], "d": ["Այն բանից հետո, երբ Իդրիս Բիթլիսին տարածաշրջանի սուննի քուրդ բեյերին գրավեց օսմանյան կողմը, սեֆյան ուժերը չկարողացան դիմանալ երկարատև պաշարմանը, և Ամիդի բանալիները հանձնվեցին Բըյըքլը Մեհմեդ փաշային։ Քաղաքը դարձավ նորաստեղծ Դիարբեքիրի բեյլերբեյության կենտրոն։ Այսպիսով Վերին Միջագետքի վարչական միջուկն անցավ օսմանյան ձեռքը։", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Խարբերդի նվաճումը. Դիարբեքիր տանող ճանապարհի բացումը", "564eb269"], "d": ["Չալդըրանից հետո վերցված Դիարբեքիրը սեֆյան պաշարումից ազատելու նպատակով ճանապարհ ելած Կարամանի բեյլերբեյ Խյուսրև փաշան եռօրյա պաշարման ավարտին վերցրեց Խարբերդի բերդը, որի շրջակայքը նախապես գրավել էր Չերքեզ Հուսեյն բեյը։ Այսպիսով Եփրատից արևելք՝ դեպի Դիարբեքիր ձգվող ճանապարհն ապահովվեց։", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Կոչհիսարի (Կըզըլթեփե) ճակատամարտը. Կարա խանի պարտությունը", "9ea9e843"], "d": ["Բըյըքլը Մեհմեդ փաշայի հրամանատարությամբ օսմանյան բանակը Կոչհիսարի մոտ՝ Դեդե Գարքընի դաշտի Կորուք կոչվող վայրում, ամբողջ օրը տևած դաշտային ճակատամարտում հաղթեց սեֆյան կուսակալ Կարա խանին. Կարա խանի կտրված գլուխն ուղարկվեց փադիշահի ճամբարը։ Այնուհետև օսմանյան ուժերը թեև մտան Մարդին քաղաք, բայց մի քանի օր մնալով հեռացան. սեֆյան կայազորի ձեռքում գտնվող Մարդինի բերդը հնարավոր եղավ վերցնել միայն մեկ տարի անց։ Այս հաղթանակը, ապահովելով Յավուզի հարավային սահմանը, հնարավորություն տվեց նրան ուղղվել դեպի եգիպտական արշավանք։ Նույն ամսաթվին միացած այլ վայրեր՝ Բալու, Չմշկածագ, Սիվերեկ։", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Յավուզ Սուլթան Սելիմի մեկնումը Ստամբուլից եգիպտական արշավանքի", "ac258b4b"], "d": ["Յավուզ Սուլթան Սելիմը Ստամբուլից շարժվեց արտաքուստ Սեֆյանների դեմ նոր արևելյան արշավանքի պատրաստությամբ և Աքշեհիրի վրայով ուղղվեց դեպի հարավ։ Մամլուք սուլթան Կանսուհ ալ-Ղաուրիի կապ հաստատելը շահ Իսմայիլի հետ և օսմանյան արևելյան թևին սպառնալը շուտով հանգեցնելու էին թիրախի փոփոխությանը։ Արշավանքը այն մեծ գործողության սկիզբն է, որը տևելու էր երկու տարի և Օսմանյան պետությունը վերածելու էր մերձավորարևելյան կայսրության։", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Զաբիդի գրավումը. օսմանյան ծովայինների առաջին մուտքը Կարմիր ծով", "38740e0c"], "d": ["Հնդկական օվկիանոսում պորտուգալական ճնշմանն ի պատասխան՝ մամլուք սուլթան Կանսուհ ալ-Ղաուրիի խնդրանքով Կարմիր ծով ուղարկված օսմանյան ծագմամբ ծովայիններ Հուսեյն բեյը և Սելման ռեիսը իրենց նավատորմով գրավեցին Զաբիդը։ Դեռևս մամլուքյան ծառայության մեջ իրականացված այս գործողությունը օսմանյան նավատորմի առաջին փաստացի ներկայությունն է Կարմիր ծով-Հնդկաստան ուղղությամբ։ Մեկ տարի անց, երբ Եգիպտոսն անցնի Օսմանյան պետությանը, նույն նավատորմն ուղղակիորեն կենթարկվի Ստամբուլին։", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Արշավանքի թիրախի՝ մամլուքների և Հալեպի պաշտոնական հայտարարումը", "689e310d"], "d": ["Այն բանից հետո, երբ Կանսուհ ալ-Ղաուրին, պայմանավորվելով Սեֆյանների հետ, իր բանակը շարժեց դեպի Հալեպ, Յավուզ Սուլթան Սելիմը բացահայտորեն հայտարարեց, որ արշավանքի թիրախը մամլուքների սուլթանն ու Հալեպն են։ Այսպիսով երկու սուննի պետությունների միջև տարիներ շարունակ տևած քողարկված մրցակցությունը վերածվեց բացահայտ պատերազմի։ Այս հայտարարությունը սկիզբ դրեց դեպի Մարջ Դաբիկ տանող քառաշաբաթյա հետհաշվարկին։", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Ադենի պաշարման ձախողումը. Պորտուգալիայի դեմ Կարմիր ծովի առաջին ձեռնարկումը", "8ffd46f2"], "d": ["Սելման ռեիսը և Հուսեյն բեյը ութ օր տևած պաշարում ձեռնարկեցին՝ գրավելու Ադենը, որը Կարմիր ծովից դեպի Հնդկական օվկիանոս բացվող դուռն էր, սակայն քաղաքի հզոր ամրությունների առջև ստիպված եղան նահանջել։ Ադենը չգրավելը երկար տարիներ խափանելու էր Պորտուգալիայի դեմ վարվելիք հարավային ռազմավարությունը։ Այս ձեռնարկումը Օսմանյան պետության առաջին փորձությունն է օվկիանոսային քաղաքականության մեջ։", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Ռամազան-օղլուների բեյլիքի կապումը օսմանցիներին", "cfaa3754"], "d": ["Մարջ Դաբիկի հաղթանակից հետո կատարված նշանակումների ժամանակ Ադանա կենտրոնով Ռամազան-օղլուների բեյլիքը, տրվելով Մահմուդ բեյին, վերցվեց օսմանյան տիրապետության տակ։ Մամլուքների հպատակությունից դուրս եկած բեյլիքը վերացնելու փոխարեն թողնվեց ընտանիքին «օջախության» (ocaklık) կարգավիճակով. Ռամազան-օղլուները Կիլիկիայի կառավարումը շարունակեցին որպես օսմանյան սանջակբեյեր։ Այս արտոնյալ կարգը շարունակվեց մինչև 1608 թվականը, երբ Փիր Մանսուրը թողեց բեյլիքը։ Նույն ամսաթվին միացած այլ վայրեր՝ Մալաթիա, Տարսոն, Մոսուլ, Այնթապ։", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Հալեպի, Ռաքքայի և Դեյր էզ-Զորի անցումը օսմանյան տիրապետության տակ", "2088eb6a"], "d": ["Մարջ Դաբիկից չորս օր անց Յավուզ Սուլթան Սելիմը առանց դիմադրության մտավ Հալեպ, և քաղաքի մզկիթներում խուտբան կարդացվեց նրա անունով։ Սիրիայի առևտրական և վարչական մայրաքաղաքը համարվող Հալեպի այսքան արագ անկումը ցույց է տալիս, որ մամլուքյան իշխանությունը տարածաշրջանում փլուզվել էր։ Քաղաքի գրավումը մեկեն բացեց դեպի Դամասկոս և այնտեղից Եգիպտոս ձգվող ճանապարհը։ Նույն ամսաթվին միացած այլ վայրեր՝ Անտիոք, Ռաքքա, Դեյր էզ-Զոր։", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Հանդիպումը Աբբասյան խալիֆա ալ-Մութավաքքիլ III-ի հետ Հալեպի Գյոքմեյդանում", "22979f42"], "d": ["Մարջ Դաբիկում մամլուքյան բանակի հետ գերի ընկած Կահիրեի Աբբասյան խալիֆա ալ-Մութավաքքիլ III-ը Հալեպի Գյոքմեյդանում բերվեց փադիշահի առջև, և Յավուզ Սուլթան Սելիմը նրա հանդեպ մեծ հարգանք ցուցաբերեց։ 1261 թվականից ի վեր մամլուք սուլթանների ստվերում խորհրդանշական պաշտոն հանդիսացող Կահիրեի խալիֆայությունն այս հանդիպմամբ փաստորեն անցավ օսմանյան հովանավորության տակ։ Խալիֆան ավելի ուշ փադիշահի հետ տարվելու էր Ստամբուլ։", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Տրիպոլիի (Լիբանան) և Համայի անցումը օսմանյան կառավարման", "a1e19a79"], "d": ["Հալեպից և Համայից հետո Սիրիայի ափի Տրիպոլին ևս առանց դիմադրության անցավ օսմանյան կառավարման։ Արևելյան Միջերկրածովի ամենաաշխույժ նավահանգիստներից մեկը եղած քաղաքը Դամասկոսի՝ դեպի ծով բացվող դուռն էր և մետաքսի ու շաքարի առևտրի կենտրոնը։ Դրա գրավմամբ Բիլադ ալ-Շամի ափամերձ շերտն ամբողջությամբ ձեռքից ձեռք անցավ։", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Դամասկոսի (Դիմաշք) անցումը օսմանյան տիրապետության տակ", "2b844d91"], "d": ["Հալեպից հետո Համայի և Հոմսի հանձնվելով ճանապարհը բացված Յավուզ Սուլթան Սելիմը սեպտեմբերի 27-ին հասավ Դամասկոսի մատույցներ. նա անմիջապես քաղաք չմտավ, այլ իր վրանը խփեց դրսում՝ Մաստաբա կոչվող վայրում, և ժամանելուց տասներկուերորդ օրը մեծ հանդիսությամբ ներս մտավ։ Դամասկոսում բավական երկար մնալով՝ նա հաստատեց Սիրիայի վարչական կարգը և կառուցել տվեց Մուհիդդին Իբն ալ-Արաբիի դամբարանը։ Այսպիսով ամբողջ Բիլադ ալ-Շամը դուրս եկավ մամլուքյան կառավարումից։ Նույն ամսաթվին միացած այլ վայրեր՝ Բեյրութ։", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Թուման բեյի հռչակումը մամլուքների սուլթան Կահիրեում", "6020d90d"], "d": ["Մարջ Դաբիկում մահացած Կանսուհ ալ-Ղաուրիից հետո մամլուք էմիրները գահ բարձրացրին Թուման բեյին, որը լինելու էր պետության վերջին սուլթանը։ Չերքեզական ծագմամբ նոր սուլթանը ստանձնեց մի պետություն, որը կորցրել էր Սիրիան, սպառել էր գանձարանը և զուրկ էր հրազենից։ Այնուամենայնիվ, նա Կահիրեի մատույցներում պաշտպանական գիծ ստեղծելով՝ կազմակերպելու էր վերջին դիմադրությունը օսմանյան առաջխաղացման դեմ։", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Գազայի (Խան Յունիս) ճակատամարտը. Ջանբիրդի Ղազալիի պարտությունը", "9f1eb8cb"], "d": ["Յավուզ Սուլթան Սելիմը մեծ վեզիր Հադըմ Սինան փաշային չորս հազարանոց առաջապահ ուժով ուղարկեց Գազա։ Թուման բեյի կողմից Դամասկոսի նաիբ նշանակված Ջանբիրդի Ղազալին թեև փորձեց Գազա-Խան Յունիս գծում կանգնեցնել օսմանյան առաջապահ զորքը, սակայն ծանր պարտություն կրեց և փախավ Եգիպտոս։ Պաղեստինում մամլուքների վերջին բուֆերային ուժի ցրվելով Սինայի անապատ տանող ճանապարհը լիովին բացվեց։", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Հորդանանից արևելք՝ Ամմանի անցումը օսմանյան կառավարման", "9db62667"], "d": ["Գազայի ճակատամարտից հետո եգիպտական արշավանքի նախապատրաստվող օսմանյան ուժերը հարավ իջնելիս Հորդանանից արևելք գտնվող Ամմանը ևս անցավ օսմանյան կառավարման։ Իսկ Պաղեստինի ափամերձ և ներքին քաղաքները (Յաֆա, Նաբլուս, Սիդոն, Աքքա, Երուսաղեմ) Մարջ Դաբիկից հետո արդեն 1516 թվականի աշնանը ձեռքից ձեռք էին անցել։ Այս քաղաքները չորս դար կառավարվեցին որպես Դամասկոսի էյալեթի սանջակներ։", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Յավուզ Սուլթան Սելիմի ժամանումը Երուսաղեմ", "66d7bfad"], "d": ["Մարջ Դաբիկից հետո առանց դիմադրության օսմանյան կառավարման տակ անցած Երուսաղեմ Յավուզ Սուլթան Սելիմը Գազայի ճակատամարտից հետո եկավ պետության ավագանու և զորքի հետ։ Փադիշահը, այցելելով Ժայռի գմբեթը (Կուբբաթ աս-Սախրա) և Ալ-Աքսա մզկիթը, հաստատեց քաղաքի սրբազան կարգավիճակը։ Երուսաղեմն այդ ժամանակից մինչև 1917 թվականի դեկտեմբերը՝ ուղիղ չորս դար, մնալու էր օսմանյան կառավարման տակ։", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Յավուզ Սուլթան Սելիմի մուտքը Գազա և ուղղվելը դեպի Սինայի անապատ", "2106bfc7"], "d": ["Խան Յունիսում Ջանբիրդի Ղազալիի պարտությունից (1516 թվականի դեկտեմբերի 21) հետո Գազան առաջապահ ուժի ձեռքում էր։ Փադիշահը 1517 թվականի հունվարի 2-ին մտնելով Գազա՝ այնտեղ հանդիպեց առաջապահ ուժի գլուխ կանգնած Սինան փաշային, և բանակը կատարեց Եգիպտոս անցնելու վերջին պատրաստությունները։ Գազայից մինչև Սալիհիա ձգվող անջուր Կատիայի (Սինայի) անապատով անհրաժեշտ էր անցնել ութ օթևան, իսկ ջուրը տեղափոխվելու էր ուղտերով։ Այս անցումը արշավանքի ամենառիսկային և լոգիստիկ առումով ամենադժվար փուլն է։", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Սուեզի գրավումը — Կարմիր ծով բացվող դուռը", "05f3324e"], "d": ["Ռիդանիայի հաղթանակից հետո օսմանյան զորամասերի Կահիրե մուտք գործելով Կարմիր ծովի հյուսիսային ծայրի Սուեզը ևս անցավ օսմանյան կառավարման։ Այս նավաշինարան-նավահանգիստը, որտեղից մամլուքները նավատորմ էին ուղարկում Հնդկական օվկիանոս, դարձավ Պորտուգալիայի դեմ վարվելիք հարավային քաղաքականության հենակետը։ Սուեզը այն գծի հյուսիսային մուտքն է, որտեղ երեք դար անց բացվելու էր ջրանցքը։", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Օսմանյան զորամասերի առաջին մուտքը Կահիրե", "0a3f4f4d"], "d": ["Ռիդանիայի հաղթանակի հաջորդ օրը թույլատրվեց, որ օսմանյան զորքերը մտնեն Կահիրե, և հունվարի 24-ին զորամասերը տեղավորվեցին քաղաքում։ Սակայն այս մուտքը չէր նշանակում քաղաքի լիակատար վերահսկողություն. Թուման բեյը նահանջել էր Վերին Եգիպտոս, և մամլուքյան դիմադրությունը դեռ կոտրված չէր։ Կահիրեի նվաճումն ավարտվելու էր ոչ թե մեկ օրում, այլ շաբաթների վրա ձգված արյունալի գործընթացում։", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Թուման բեյի հարձակումը Կահիրեի վրա և եռօրյա փողոցային մարտերը", "b83b6ce6"], "d": ["Վերին Եգիպտոս նահանջած Թուման բեյը իր մոտ գտնվող մոտ յոթ հազար մարդկանց հետ հունվարի 27-ի լույս 28-ի գիշերը հանկարծակի մտավ Կահիրե, քաղաքի ներսում դիմադրություն սկսեց և օսմանյան զորամասերին ծայրահեղ ծանր դրության մեջ դրեց։ Երեք օր տևած կատաղի փողոցային ընդհարումների ընթացքում մամլուքները ժամանակավորապես իրենց ձեռքում պահեցին քաղաքի մեծ մասը։ Դիմադրությունը հնարավոր եղավ կոտրել միայն օսմանյան հրետանու և օժանդակ ուժերի գործի անցնելուց հետո։", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Ջանբիրդի Ղազալիի անցումը օսմանյան ծառայության", "a94ea459"], "d": ["Ռիդանիայից հետո Սալիհիա քաշված նախկին մամլուք էմիր Ջանբիրդի Ղազալին դիմեց փադիշահին և ներում խնդրեց։ Յավուզ Սուլթան Սելիմը, մտածելով, որ նա օգտակար կլինի Եգիպտոսում և Սիրիայում կարգուկանոն հաստատելու գործում, ընդունեց նրան իր ծառայության։ Այս ընտրությունը օսմանյան այն քաղաքականության առաջին խոշոր օրինակն է, ըստ որի մամլուքյան կադրերը ոչ թե վերացվում, այլ ներառվում էին համակարգի մեջ։", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Յավուզ Սուլթան Սելիմի հանդիսավոր մուտքը Կահիրե և խուտբայի ընթերցումը", "6d98080c"], "d": ["Փողոցային ընդհարումները ճնշելուց հետո փադիշահը 1517 թվականի փետրվարի 15-ին շատ շքեղ արարողությամբ մտավ Կահիրե, և մզկիթներում խուտբան կարդացվեց նրա անունով։ Կահիրեում օսմանյան սուլթանի անունով խուտբայի ընթերցումը հայտարարություն էր այն մասին, որ 1250 թվականից տևող մամլուքյան տիրապետությունն իրավականորեն ավարտվել է։ Այս օրը համարվում է Եգիպտոսի փաստացի նվաճման խորհրդանշական ավարտի պահը։", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Մամլուքների վերջին սուլթան Թուման բեյի ձերբակալումը Թարուջայում", "7058e6ad"], "d": ["Կահիրեն լքելուց հետո Նեղոսի դելտայում թաքնված Թուման բեյին մատնեցին նրան ապաստան տված բեդվինները, և նա բռնվեց Թարուջայի շրջանում։ Նրա ձերբակալությունը վերացրեց մամլուքյան դիմադրության կազմակերպված կենտրոնը։ Վերջին սուլթանն այնուհետև տասնչորս օր պահվելու էր օսմանցիների ձեռքում։", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Թուման բեյի մահապատիժը Բաբ Զուվեյլայում և Մամլուքների պետության վերջը", "ad9820be"], "d": ["Ձերբակալությունից տասնչորս օր անց Թուման բեյին կախեցին Կահիրեի հանրահայտ Բաբ Զուվեյլա դարպասի վրա. նրա դին ավելի ուշ թաղվեց իր հորեղբոր կառուցած մեդրեսեում։ Այսպիսով 1250 թվականից Եգիպտոսին և Սիրիային իշխող Մամլուքների պետությունը պաշտոնապես անցավ պատմության գիրկը։ Դիմադրությունը կոտրվելով՝ Վերին Եգիպտոսի (Սաիդ) Ասյուտ և Ասուան քաղաքները ևս միացան օսմանյան կառավարմանը։", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Պորտուգալական նավատորմի հարձակումը Ջիդդայի վրա և Սելման ռեիսի պաշտպանությունը", "52322cf5"], "d": ["Մոտ երեսուն գալերից և գալեոնից բաղկացած պորտուգալական նավատորմը հարձակվեց Ջիդդայի վրա. Սելման ռեիսը, ղեկավարելով քաղաքի պաշտպանությունը, թույլ չտվեց, որ թշնամին ափ իջնի, և խորտակեց մի քանի պորտուգալական նավ։ Այս պաշտպանությունը կանխեց, որ Մեքքայի նավահանգիստը, հետևաբար նաև ուխտագնացության ճանապարհը, անցնի քրիստոնեական մի պետության ձեռքը։ Ջիդդան մի քանի ամիս անց Հիջազի հավատարմության երդումով պաշտոնապես ներառվելու էր օսմանյան կառավարման մեջ։", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Ալեքսանդրիայի հանձնումը նավատորմին. Եգիպտոսի նվաճման ավարտը", "386878fe"], "d": ["Ռիդանիայից ուղիղ չորս ամիս, իսկ Թուման բեյի մահապատժից երեսունվեց օր անց, Ջաֆեր բեյի հրամանատարությամբ օսմանյան նավատորմի նավահանգիստ ժամանելով Ալեքսանդրիան անցավ օսմանյան կառավարման տակ. նույն գործընթացում միացան նաև դելտայի այնպիսի նավահանգիստներ, ինչպիսիք են Ռաշիդը և Դամիետան։ Եգիպտոսի՝ դեպի Միջերկրական ծով բացվող այս մեծ նավահանգստի հանձնումը Կահիրեի անկումից ամիսներ անց, և այն էլ ոչ թե ցամաքից, այլ ծովից, հստակ ցույց է տալիս, որ նվաճումն ավարտվել է ոչ թե մեկ ճակատամարտով, այլ շրջան առ շրջան։ Ալեքսանդրիան այնուհետև դառնալու էր Ստամբուլը Կահիրեի հետ կապող կենսական նավահանգիստը։ Նույն ամսաթվին միացած այլ վայրեր՝ Ռաշիդ (Ռոզետա)։", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Հիջազի անպատերազմ միացումը. Մեքքայի շարիֆի որդի Աբու Նումեյի հավատարմության երդումը", "c13b98c7"], "d": ["Յավուզ Սուլթան Սելիմը սկզբում մտածել էր զորք ուղարկել Մեքքան և նրա շրջակայքը գրավելու համար, սակայն Մեքքայի էմիր շարիֆ Բարաքաթի հնազանդությունը հայտնելուց հետո հրաժարվել էր այդ մտքից։ Բարաքաթի տասներկուամյա որդի Աբու Նումեյը, հոր նվերներով և Մեքքայի բանալիներով գալով Կահիրե, ընդունվեց փադիշահի ներկայության։ Այսպիսով Հիջազը միացավ Օսմանյան պետությանը ոչ թե որպես Ռիդանիայի ինքնաբերական հետևանք, այլ հինգուկես ամիս անց և առանց մեկ գնդակ արձակելու՝ խաղաղ ճանապարհով և հավատարմության երդումով։ Նույն ամսաթվին միացած այլ վայրեր՝ Թաիֆ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Հուրմա (Թաիֆից արևելք), Ռաբիղ, Բադր։", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["«Խադիմ ալ-Հարամայն» տիտղոսի ընդունումը և խուտբան Մեդինայում", "63b32b59"], "d": ["Մեքքայի պատվիրակության երկրորդ ընդունելությունից հետո Յավուզ Սուլթան Սելիմը պաշտոնապես ստանձնեց Երկու սրբավայրերի (Հարամայն) հովանավորությունը և սկսեց օգտագործել «խադիմ ալ-Հարամայն աշ-Շարիֆայն» տիտղոսը։ Շարիֆ Բարաքաթը, հագնելով իրեն ուղարկված պատվո պատմուճանը, կարգադրեց խուտբա կարդալ փադիշահի անունով. Մեդինայի պատվիրակության՝ նաև Ստամբուլ գնալուց հետո Բարաքաթի էմիրությունը հաստատվեց բերաթով։ Փադիշահը Երկու սրբավայրերի բնակչությանը ուղարկելով երկու հարյուր հազար ոսկի և առատ պարեն՝ սկիզբ դրեց ամեն տարի կրկնվող սուրրեի ավանդույթին։ Նույն ամսաթվին միացած այլ վայրեր՝ Յանբու, Թաբուք։", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Սելման ռեիսի անցումը օսմանյան ծառայության և Կարմիր ծովի քաղաքականության փոխանցումը", "771da99a"], "d": ["Ջիդդան պորտուգալացիներից պաշտպանած Սելման ռեիսը, գալով Կահիրե, ներկայացավ Յավուզ Սուլթան Սելիմին. թեև որոշ ժամանակ նրան պահեցին, 1519 թվականին նա կանչվեց Ստամբուլ և պարտավորվեց պորտուգալական սպառնալիքի դեմ պատրաստել երեսուն գալեր և մի քանի գալիոտ։ Այս հանդիպումը սկիզբն է այն բանի, որ Կարմիր ծովի և Հնդկական օվկիանոսի քաղաքականությունը, մամլուքյան ժառանգությունից վերցվելով, ուղղակիորեն կապվեց Ստամբուլի հետ։ Օսմանյան պետությունն այլևս Միջերկրածովյան պետություն լինելուց բացի նաև օվկիանոսային քաղաքականություն վարող ուժ էր։", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Յավուզ Սուլթան Սելիմի մեկնումը Կահիրեից և Խայր բեյի բեյլերբեյությունը", "8cd4fb23"], "d": ["Եգիպտոսում մոտ ութ ամիս մնալով և վարչական, ֆինանսական ու ռազմական կարգ հաստատելով՝ Յավուզ Սուլթան Սելիմը հեռացավ Կահիրեից. Մարջ Դաբիկում ձախ թևը հետ քաշելով մամլուքյան պարտությունն արագացրած Հալեպի նախկին նաիբ Խայր բեյը, որպես Եգիպտոսի առաջին օսմանյան բեյլերբեյ, սկսեց կառավարել Լեռան բերդից (Կալաթ ալ-Ջաբալ)։ Մամլուքյան ծագմամբ կուսակալի ընտրությունը գիտակցված անցումային քաղաքականություն էր, որն ապահովում էր, որ նոր կառավարումը տեղի բնակչությանը օտար չթվա։ Վերադարձի ճանապարհին փադիշահն իր հետ Ստամբուլ տարավ նաև Աբբասյան վերջին խալիֆա ալ-Մութավաքքիլ III-ին ու Եգիպտոսի ընտիր արհեստավորներին և գիտնականներին։", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Կահիրեի Աբբասյան խալիֆայության վերջը. «փոխանցման արարողության» ավանդությունը", "1d357640"], "d": ["Յավուզ Սուլթան Սելիմը Եգիպտոսը գրավելով՝ Մարջ Դաբիկում գերի ընկած վերջին խալիֆա ալ-Մութավաքքիլ ալա Ալլահ III-ին իր հետ բերեց Ստամբուլ. այսպիսով ավարտվեց Կահիրեի Աբբասյան խալիֆայությունը, որը 1261 թվականից ի վեր մամլուք սուլթանների ստվերում շարունակվում էր առանց իրավասության։ Սակայն այն հանրահայտ ավանդությունը, թե խալիֆայությունը Այա Սոֆիայում պաշտոնական արարողությամբ փոխանցվեց Յավուզին, առաջին անգամ հանդիպում է XVIII դարի վերջին՝ դ’Օհսոնի աշխատության մեջ, և չկա Յավուզի ժամանակաշրջանի ոչ մի աղբյուրում։ TDV İslâm Ansiklopedisi-ն, քանի որ արարողությունը հաստատող բնօրինակ աղբյուր չկա, ավանդությունը համարում է հորինված. սակայն նաև նշում է, որ խալիֆայության փոխանցման համար շարիաթով նման փոխանցման արարողության կարիք չկա։", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Էրզրումը միացավ օսմանյան կառավարմանը. Արևելյան Անատոլիայում սեֆյան ազդեցությունը կոտրվեց", "78d1be02"], "d": ["Թեև Չալդըրանի հաղթանակից (1514) հետո տարածաշրջանում օսմանյան ազդեցությունն աճեց, Էրզրումի ամբողջական գրավումը ձգձգվեց մինչև իրանական ազդեցության կոտրվելը. քաղաքը օսմանյան կառավարմանը միացավ միայն եգիպտական արշավանքից հետո՝ 1518-19 թվականներին։ Էրզրումը սեֆյան տիրապետության տակ էր անցել 1502 թվականին, երբ շահ Իսմայիլը վերջ տվեց Ակ-Կոյունլուների բեյությանը. այսպիսով փակվեց այս տասնվեցամյա շրջանը։ 1534 թվականին՝ Իրաքեյնի արշավանքի ժամանակ, հիմնվելու էր Էրզրումի բեյլերբեյությունը։ 1518-1519 թվականների միջև Էրզրումի շրջանի հետ Աշկալեն միացավ օսմանյան կառավարմանը (օրը հաստատված չէ)։", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Ջալալիների ապստամբությունների սկիզբը. բոզոքցի շեյխ Ջալալի ապստամբությունը", "99bd8a99"], "d": ["Բոզոքի շրջանում շեյխ Ջալալ անունով մի մարդ, իրեն մահդի հռչակելով, ապստամբեց Թոքաթի շրջակայքում. թեև ապստամբությունը ճնշվեց, նրա անունը մեկ դար շարունակ դարձավ Անատոլիայի բոլոր ավազակային ու ապստամբական շարժումների անունը։ Ջալալիությունը XVI դարի վերջին, միաձուլվելով թիմարային համակարգի քայքայման և ժողովրդագրական ճնշման հետ, վերածվեց կայսրության ամենաերկարատև ներքին անվտանգության խնդրի։ Ապստամբությունները Անատոլիայում հանգեցրին «մեծ փախուստ» կոչվող զանգվածային գաղթերի։", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Ալժիրի միացումը Օսմանյան պետությանը", "b8eba4c1"], "d": ["Հյուսիսային Աֆրիկայում իսպանական ճնշմանը դիմադրող Հայրեդդին ռեիսը, դիմադրությունը պահպանելու համար դիմելով Ստամբուլ, Ալժիրը մատուցեց փադիշահին, և խուտբան կարդացվեց Յավուզ Սուլթան Սելիմի անունով։ Այսպիսով Ալժիրը պաշտոնապես միացավ օսմանյան հողերին, իսկ Հայրեդդինին բեյլերբեյի տիտղոսի հետ զորք և թնդանոթներ ուղարկվեցին։ Այս միացումը դրեց Արևմտյան Միջերկրականում դարեր տևելիք օսմանյան ծովային գերակայության հիմքը։ Նույն ամսաթվին միացած այլ վայրեր՝ Կոնստանտին, Շերշել (Cherchell), Մեդեա (Թիթերի), Սեթիֆ։", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Յավուզ Սուլթան Սելիմի մահը Չորլուում", "9fe83744"], "d": ["Ութ տարում պետության տարածքն ավելի քան կրկնապատկած Սելիմ I-ը 1520 թվականի հուլիսի 18-ին նոր արշավանքի համար դուրս եկավ Ստամբուլից. մեջքին առաջացած մեծ ուռուցքի պատճառով նա չկարողացավ Չորլուից հեռու գնալ։ Չնայած բժիշկների միջամտությանը՝ նրա հիվանդությունը ծանրացավ, և երկու ամիս տևած անհույս բուժումից հետո նա այստեղ վախճանվեց հիջրայի 926 թվականի Շավվալի 8-9-ին (1520 թվականի սեպտեմբերի 21-22)։ Չալդըրանով, Մարջ Դաբիկով և Ռիդանիայով նա կանգնեցրել էր Իրանը և վերացրել Մամլուքների պետությունը, իսկ խալիֆայությունն ու Երկու սրբավայրերի հովանավորությունը բերել էր Օսմանյան պետությանը։ Նա թողեց միակ արու զավակ՝ Սուլեյմանին։", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Իկարիա (Նիկարիա) կղզու անցումը օսմանյան կառավարման տակ", "6afa972b"], "d": ["Սամոսի և Քիոսի միջև գտնվող Իկարիան 1481-ից մինչև 1521 թվականը գտնվում էր Ռոդոսի Սուրբ Հովհաննեսի ասպետների կառավարման տակ. կղզում առաջին օսմանյան շրջանը սկսվեց 1522 թվականին և տևեց մինչև 1822 թվականը։ Այս շրջանում հարկերի հավաքման ու վճարման համար պատասխանատու էր կայմակամը. ինչպես մյուս Էգեյան կղզիներում, տեղական ծերերի խորհուրդը (դեմոգերոնտիա) ևս շարունակեց իր գոյությունը և ժամանակ առ ժամանակ բախվեց օսմանյան վարչակազմի հետ։", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Դուլկադիրի երկրի բռնակցումը. Մարաշ կենտրոնով Դուլկադիրի էյալեթը", "595c3c30"], "d": ["1515 թվականի Թուրնադաղի ջախջախումից հետո որպես Օսմանյան պետությանը վասալ բեյություն շարունակված Դուլկադիրի երկիրը, Շեհսուվարօղլու Ալի բեյի՝ Արթուկովայում իր զավակների հետ սպանությունից հետո, ուղղակիորեն միացվեց օսմանյան հողերին և, Մարաշը կենտրոն ունենալով, դարձվեց էյալեթ։ Բեյության Բոզոքի շրջանը որպես առանձին սանջակ ենթարկվեց օսմանյան կառավարմանը։ Այսպիսով փակվեց Մարաշի, Ալբիսթանի, Գյոքսունի, Գյուրունի, Զամանթըի և Դարենդեի մոտ երկդարյա դուլկադիրյան շրջանը. մամլուքյան սահմանի բուֆերային բեյությունը լիովին վերացավ։", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Կնինի նվաճումը", "a46d3117"], "d": ["Բոսնիայի սանջակբեյ Ղազի Խյուսրև բեյի՝ հիջրայի 927-928 (1521-1522) թվականների ասպատակություններով վենետիկյան մի շարք բերդեր, հատկապես Կնինը, Սկրադինը և Օստրովիցան, անցան օսմանյան կառավարման տակ. սահմանը հետ մղվեց երկրորդ լեռնաշղթայից այն կողմ։ Այս նվաճումների շղթան դրեց Դալմաթիայի սանջակի հիմքը, որը տասնհինգ տարի անց ամբողջանալու էր Կլիսի վերցմամբ։", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Ասպետների հեռանալը. Բոդրումի, Կոսի և Տասներկու կղզիների փոխանցումը", "ea01666e"], "d": ["Ռոդոսի հանձնման պայմանների համաձայն՝ Սուրբ Հովհաննեսի ասպետները դատարկեցին ոչ միայն կղզու կենտրոնը, այլև երկու հարյուր տարի իրենց ձեռքում պահած բոլոր դիրքերը։ Անատոլիայի ափի Բոդրումի (Սեն Պիեռ) բերդը, ինչպես նաև Կոս, Կելեմեզ և Լերոս կղզիները այսպիսով առանց ընդհարման անցան օսմանյան կառավարման տակ։ Ռոդոսի անկումից երկու շաբաթ անց ավարտված այս փոխանցմամբ Էգեյան ծովի հարավարևելյան անկյունում լատինական ներկայությունը լիովին վերջ գտավ։", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Խաին (դավաճան) Ահմեդ փաշայի ապստամբությունը Եգիպտոսում", "b18bb805"], "d": ["Մեծ վեզիրության սպասելիս Եգիպտոսի կուսակալ ուղարկված Ահմեդ փաշան Կահիրեում իրեն հռչակեց «ալ-Մալիք ալ-Մանսուր սուլթան Ահմեդ» և հայտարարեց իր անկախությունը։ Ապստամբությունը կարճ ժամանակում ճնշվեց, և փաշան սպանվեց, սակայն այդ դեպքը ցույց տվեց կայսրության ամենահարուստ էյալեթում կենտրոնական վերահսկողության փխրունությունը։ Այնուհետև Իբրահիմ փաշան մեկնեց Եգիպտոս և կազմել տվեց էյալեթի կառավարումը վերակարգավորող հանրահայտ «Եգիպտոսի օրենսգիրքը» (Մըսըր կանունամեսի)։", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Հյուսիսային Բոսնիայի բռնակցումը. Յայցե և Բանյա Լուկա", "8ec86cfa"], "d": ["Երբ Մոհաչից հետո հունգարական պաշտպանական գիծը փլուզվեց, Բոսնիայի սանջակբեյ Ղազի Խյուսրև բեյը, առաջ շարժվելով Վրբասի հովիտով, վերցրեց Հունգարիայի թագավորության ձեռքում մնացած վերջին բոսնիական բերդերը։ Յայցեի և Բանյա Լուկայի անկումով Բոսնիայի էյալեթը հյուսիսում հենվեց Սավա գետին, և ծնվեց Խորվաթիայի ճակատը։ Բանյա Լուկան շուտով դարձավ էյալեթի երկրորդ կենտրոնը։", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Բուդայի վերցնելը և հանձնումը Զապոլյային", "fba4f89b"], "d": ["Վիեննայի արշավանքի ճանապարհին օսմանյան բանակը, պաշարելով Ֆերդինանդի ձեռքն անցած Բուդան, հետ վերցրեց այն և քաղաքը հանձնեց օսմանյան հովանավորության տակ գտնվող Հունգարիայի թագավոր János Szapolyai-ին (Յանոշ Զապոլյա)։ Այսպիսով Հունգարիայի նկատմամբ Հաբսբուրգ-օսմանյան մրցակցության մեջ ստեղծվեց բուֆերային վասալ թագավորության մոդել։ Այս կարգը տևելու էր մինչև 1541 թվականը, իսկ Զապոլյայի մահից հետո Բուդան ուղղակիորեն վերածվելու էր օսմանյան էյալեթի։", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Կանունին դուրս եկավ գերմանական արշավանքի. մարտահրավեր Կարլոս V-ին", "7c3d7055"], "d": ["Վիեննայի պաշարման անարդյունք մնալուց և Ֆերդինանդի՝ Բուդան կրկին պաշարելուց հետո փադիշահն այս անգամ ճանապարհ ելավ Ստամբուլից՝ ուղղակիորեն կայսր Կարլոս V-ին դաշտային ճակատամարտի քաշելու համար։ Բանակը օգոստոսին ուշանալու էր փոքրիկ Գյունս բերդի դիմադրության պատճառով, և երբ կայսրը ճակատամարտի դուրս չգար, արշավանքը սահմանափակվելու էր ասպատակություններով։ Արշավանքը հող նախապատրաստեց հաջորդ տարի Հաբսբուրգների հետ կնքված առաջին հաշտության համար։", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Գերմանական արշավանքը և Գյունսի (Kőszeg) պաշարումը", "8aec937a"], "d": ["Կանունին, նպատակ ունենալով Կարլոս V-ին ստիպել դաշտային ճակատամարտի, իր բանակով առաջ շարժվեց Ավստրիայի վրա. փոքրիկ Գյունս բերդը, դիմադրելով քսանհինգ օր, ուշացրեց բանակի առաջխաղացումը։ Երբ կայսրը ճակատամարտի դուրս չեկավ, ասպատակները հարվածեցին Վիեննայի շրջակայքին, և եղանակի առաջանալու պատճառով վերադարձ կատարվեց։ Արշավանքը տարածքային ձեռքբերում չբերեց, սակայն Հաբսբուրգներին նստեցնելով բանակցությունների սեղանի շուրջ՝ հող նախապատրաստեց հաջորդ տարվա հաշտության համար։", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Ստամբուլի պայմանագիրը. առաջին հաշտությունը Հաբսբուրգների հետ", "b085767a"], "d": ["Ֆերդինանդի դեսպան Կոռնելիուսին ընդունած փադիշահը համաձայնեց զինադադարի, և ստեղծվեց Օսմանյան պետության ու Ավստրիայի միջև առաջին պաշտոնական հաշտության տեքստը։ Պայմանագրով Ֆերդինանդը, իր ձեռքում պահած հունգարական հողերի դիմաց, համաձայնեց տարեկան հարկ վճարել, իսկ Ավստրիայի էրցհերցոգը արարողակարգում հավասարեցվեց մեծ վեզիրին։ Այս անհավասար կարգավիճակը XVI դարում օսմանյան դիվանագիտության գերակայության հավակնության բացահայտ արտահայտությունն էր։", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Կարսի վերցնելը և հյուսիսարևելյան սահմանի բացումը", "742e3101"], "d": ["Մինչ Իրաքեյնի արշավանքի առաջապահ թևը Էրզրումից ուղղվում էր դեպի արևելք, վրացական աթաբեկության ձեռքում գտնվող և Լենկթեմուրի ժամանակներից ավերակ Կարսի բերդը առանց դիմադրության հանձնումով վերցվեց։ Քաղաքը, քանի որ վերահսկում էր Արաքսի աղեղի և Չըլդըրի միջև անցումը, համարվում էր դեպի Իրան բացվող հյուսիսային դարպասի բանալին։ Այս ձեռքբերումը դարձավ երեսուն տարի անց հիմնվելիք Կարսի բեյլերբեյության և Կովկասյան գծի առաջին օղակը։", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Առաջին մուտքը Թավրիզ. Իրաքեյնի արշավանքի բացումը", "cf7ed4e3"], "d": ["Սերդարի (գերագույն հրամանատարի) կարգավիճակով առջևից շարժվող Իբրահիմ փաշան, երբ շահ Թահմասպը, խուսափելով դաշտային ճակատամարտից, նահանջեց երկրի խորքերը, առանց դիմադրության մտավ սեֆյան մայրաքաղաք Թավրիզ։ Կանունին ևս սեպտեմբերին հասավ քաղաք. սակայն ձմռան վրա հասնելու և մատակարարման գծի չափազանց երկարելու պատճառով բանակը ուղղվեց դեպի Բաղդադ, և Թավրիզը երկար ժամանակ ձեռքում պահել հնարավոր չեղավ։ Չալդըրանից հետո երկրորդ անգամ վերցված քաղաքը դարձավ այն վայրը, որտեղ Օսմանյան պետությունը սովորեց, որ արևելքում գրավելը հեշտ է, իսկ ձեռքում պահելը՝ դժվար։", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Բարբարոսի կողմից Թունիսի նվաճումը", "d8754216"], "d": ["Կապուդան փաշա Բարբարոս Հայրեդդին փաշան, իր նավատորմով հարվածելով Իտալիայի ափերին, ուղղվեց դեպի Թունիս, փախուստի մատնեց Հաֆսյան տիրակալ Մուլայ Հասանին և մտավ քաղաք։ Թունիսի գրավումը, Սիցիլիայի նեղուցը վերահսկող իր դիրքով, Արևմտյան Միջերկրականում ուժերի հավասարակշռությունը մեկեն փոխեց հօգուտ Օսմանյան պետության։ Սակայն այս տիրապետությունը երկար չէր տևելու. հաջորդ տարի Կարլոս V-ը պատասխանելու էր մեծ նավատորմով։", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Թունիսի կորուստը հօգուտ Կարլոս V-ի", "a691f0f8"], "d": ["Կարլոս V-ը ջենովական և պապական նավատորմներով աջակցվող մեծ արշավանքով գրավելով Հալք ալ-Ուադը՝ տիրեց Թունիսին և Մուլայ Հասանին իսպանական հովանավորության ներքո վերադարձրեց գահին։ Քաղաքում իսպանական կայազոր տեղակայելով՝ ժամանակավորապես կանգնեցվեց օսմանցիների առաջխաղացումը Կենտրոնական Միջերկրականում։ Թունիսի վերջնական նվաճումը հնարավոր էր լինելու միայն քառասուն տարի անց՝ 1574 թվականին։", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Ղազի Խյուսրև բեյի Սավայի ափի գործողությունը. Բոսանսկի Բրոդ և Յասենովաց", "3740ec83"], "d": ["1528 թվականին Յայցեն և Բանյա Լուկան վերցնելուց հետո Սավա գետի երկայնքով գտնվող բերդերը որոշ ժամանակ ևս մնացին Հաբսբուրգյան թագին ենթակա խորվաթա-սլավոնական սահմանում։ 1536 թվականին երրորդ անգամ Բոսնիայի սանջակբեյ դարձած Ղազի Խյուսրև բեյը, նույն տարի վերցնելով Պոժեգան և նրա շրջակայքը, օսմանյան կառավարմանը միացրեց նաև Սավայի ափի Բրոդ և Յասենովաց բերդերը։ Այսպիսով Բոսնիայի հյուսիսային սահմանը հենվեց Սավային. շրջանը ամբողջացվեց երկու տարի անց Դուբիցայի վերցմամբ։", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Մաքբուլ Իբրահիմ փաշայի մահապատիժը", "348aa7b8"], "d": ["Տասներեք տարի մեծ վեզիրի պաշտոնը զբաղեցրած, Կանունիի ամենամտերիմ ընկերն ու պետության փաստացի երկրորդ անձը՝ Իբրահիմ փաշան, իֆթարի հրավիրված պալատում առանց որևէ հիմնավորման խեղդամահ արվեց։ Նրա մահվան մեջ ազդեցիկ են համարվում Իրաքեյնի արշավանքի ժամանակ նրա դրսևորած վարքը, «սերասքեր սուլթան» տիտղոսի գործածումը և ներպալատական հավասարակշռությունները։ Մահապատիժը շրջադարձային կետ է, որը ցույց է տալիս, որ օսմանյան կենտրոնական կառավարման մեջ մեծ վեզիրները բացարձակ անվտանգություն չունեին։", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Կլիսի բերդի նվաճումը և Դալմաթիայի սանջակի հիմնումը", "6ffd4ebf"], "d": ["Ղազի Խյուսրև բեյի քեթխուդա, խորվաթական ծագմամբ իսլամ ընդունած Մուրադ բեյը Վենետիկից վերցրեց Սպլիտից անմիջապես հյուսիս գտնվող ռազմավարական Կլիսի բերդը։ Նվաճումից անմիջապես հետո Կլիսը դարձավ իր շրջակայքն ընդգրկող նոր սանջակի և կազայի կենտրոն. այս սանջակի սահմանները մեծ մասամբ գծեցին օսմանյան Խորվաթիայի շրջանակը։ Կնինից տասնհինգ տարի անց եկած այս նվաճումը ամբողջացրեց Դալմաթիայի ներքին մասի վարչական կմախքը։", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Կորֆուի պաշարումը և պատերազմը Վենետիկի հետ", "11af95bd"], "d": ["Ապուլիայի (Puglia) արշավանքից հետո օսմանյան բանակը զորք իջեցրեց Կորֆու և պաշարեց կղզու վենետիկյան հզոր բերդը։ Բերդի անառիկ կառուցվածքի, ծանր կորուստների և եղանակային պայմանների պատճառով սեպտեմբերի 6-ին պաշարումը հանվեց, և զորքը հետ քաշվեց։ Թեև պաշարումը անարդյունք մնաց, Վենետիկի հետ բացված պատերազմն ավարտվեց Էգեյան և Ադրիատիկ ծովերում բազմաթիվ կղզիների միացմամբ Օսմանյան պետությանը և հաջորդ տարի Պրևեզայի հաղթանակով։", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Բարբարոսի էգեյան արշավանքը. Վենետիկի ուղղակի կառավարած կղզիների վերցնելը", "1b32ed96"], "d": ["Կորֆուի պաշարումից վերադարձող նավատորմը, օգտվելով Վենետիկին պատերազմ հայտարարելու հանգամանքից, Էգեյան ծովում մեկ առ մեկ հանձնումով վերցրեց ոչ թե դքսությանը, այլ ուղղակիորեն Վենետիկին ենթակա կղզիները։ Էգինան գրավվեց կատաղի դիմադրությունից հետո, Կվերինի ընտանիքի ձեռքում գտնվող Աստիպալեան, ինչպես նաև Կարպաթոսը և Կասոսը հանձնվեցին, իսկ վանական կառավարման տակ գտնվող Պաթմոսը ևս ընդունեց օսմանյան հովանավորությունը։ Իսկ Նաքսոսի դքսությունը թողնվեց իր տեղում՝ խարաջի ենթարկվելով. նրա բռնակցումը սպասելու էր 1566 թվականին։", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Բարբարոսի հյուսիսէգեյան արշավանքը. Սկիրոսի և Հյուսիսային Սպորադների վերցնելը", "20ab688e"], "d": ["Դեպի Պրևեզա տանող ճանապարհին նավատորմը մեկ առ մեկ հանձնումով վերցրեց Հյուսիսային Էգեյան կղզիները, որոնք Ստամբուլի նվաճումից հետո ապաստանել էին Վենետիկի մոտ։ Էվբեայից հյուսիս գտնվող Սկիրոսը և Սալոնիկի ծոցի մուտքը հսկող Սկիաթոսը, Սկոպելոսը և Ալոնիսոսը այսպիսով անցան օսմանյան կառավարման տակ։ Այս կղզիները փակեցին Հյուսիսային Էգեյան ծովի վերջին բացը, որը, թեև Էվբեան վերցվել էր 1470 թվականին, ևս վաթսունութ տարի մնացել էր վենետիկյան ձեռքում։", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Ադենի գրավումը և Եմենի ափի բռնակցումը", "e7d46d8f"], "d": ["Հնդկական արշավանքի համար Սուեզից դուրս եկած նավատորմը, քանի որ առանց Կարմիր ծովը ապահովելու օվկիանոս դուրս գալ հնարավոր չէր, նախ ուղղվեց դեպի Եմենի ափ։ Հադըմ Սուլեյման փաշան 1538 թվականի օգոստոսի 3-ին մտավ Ադենի նավահանգիստ. պորտուգալացիներին հակված Թահիրյան տիրակալ Ամիր բին Դաուդը բերվեց նավապետի նավը և մահապատժի ենթարկվեց, իսկ քաղաքում թողնվեց 500 հոգանոց կայազոր։ Նույն արշավանքի ընթացքում հանձնումով վերցվեցին նաև Մոխան և նեղուցին իշխող Քամարան և Ֆարասան կղզիները, և դրվեց Եմենի բեյլերբեյության հիմքը։ Այսպիսով Օսմանյան պետությունն առաջին անգամ տիրեց Բաբ ալ-Մանդեբի ամբողջ հյուսիսային ափին. իսկ Սանաան և ներքին շրջանները ստիպված էին սպասել ևս ինը տարի։", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Մոլդովայի արշավանքը և Բուջաքի (Բենդեր) շրջանի բռնակցումը", "90a88a56"], "d": ["Օսմանյան պարտավորությունները չկատարող Մոլդովայի վոյևոդ Պետրու Ռարեշի դեմ ձեռնարկված արշավանքի ժամանակ գրավվեց Սուչավան, իսկ Յասի քաղաքը թալանվեց Ղրիմի խան Սահիբ Գիրեյի կողմից։ Փադիշահը վոյևոդության գլուխ բերեց Շտեֆան Լակուստային (Մորեխ Շտեֆան) և Բենդերի հետ Բուջաքի (Հարավային Բեսարաբիա) շրջանն ուղղակիորեն միացրեց օսմանյան հողերին։ Այս բռնակցումը դարձավ այն օղակներից մեկը, որոնք Սև ծովի հյուսիսարևմտյան ափերը վերածեցին օսմանյան ներքին ծովի։ Մոլդովան արդեն Օսմանյան պետությանը վասալ վոյևոդություն էր. այս արշավանքը հողը չխլեց օտար պետությունից, այլ միայն Բենդերի ու Բուջաքի ներքին կառավարումը վերցրեց վոյևոդից և ուղղակիորեն ենթարկեց փադիշահին. վոյևոդության մնացած մասը պահպանեց իր վասալ կարգավիճակը։ Նույն կառուցվածքը կրկնվելու էր 1484 թվականին Կիլիայում և Աքքերմանում, իսկ 1713 թվականին՝ Խոտինում. սահմանային բերդերը՝ ուղղակի ենթակայությամբ, ներքին հողերը՝ վասալ։", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Նավպլիոնի (Անաբոլու) ստանձնումը պայմանագրով", "104d0937"], "d": ["Պրևեզայից հետո երեք տարի տևած վենետիկյան պատերազմն ավարտվեց այն բանով, որ հանրապետությունը համաձայնեց թողնել Մորեայում իր վերջին երկու բերդը։ Պաշարմամբ չվերցված Նավպլիոնը և Մոնեմվասիան (Բենեֆշե), երեք հարյուր հազար դուկատ ռազմատուգանքի հետ միասին, բանակցությունների սեղանի շուրջ փոխանցվեցին Օսմանյան պետությանը։ Այսպիսով Մորեա թերակղզին միավորվեց այնպես, որ ոչ մի վենետիկյան հետք չմնաց։", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Սեգեդի անցումը օսմանյան կառավարման տակ և Սեգեդի լիվայի ստեղծումը", "019aa000"], "d": ["1541 թվականին Բուդայում օսմանյան կառավարումը լիովին հաստատվելուց հետո Սեգեդի ավագանին ընդունեց Ֆերդինանդ I-ի տիրապետությունը և պատրաստվեց զինված պաշտպանության։ Բուդայի բեյլերբեյ Քյուչուկ Բալի փաշան 1543 թվականի սկզբին քաղաքի կառավարիչներին կանչեց իր մոտ և դավաճանության մեղադրանքով մահապատժի ենթարկեց, ապա քաղաքը գրավելու համար զորամաս ուղարկեց։ Այդ ժամանակ ստեղծվեց Սեգեդի լիվան (սանջակը), և առաջին սանջակբեյ նշանակվեց Բալի փաշայի որդի Դերվիշ բեյը. լիվան սկզբում տարածվում էր Դանուբի և Թիսայի միջև։", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Վալպոյի, Շիկլոշի և Պեչի նվաճումը", "2ca030a3"], "d": ["Բուդայի բռնակցումից երկու տարի անց ձեռնարկված հունգարական արշավանքի առաջին նպատակը նոր էյալեթի՝ Դրավայի և Դանուբի միջև գտնվող հարավային թևի ապահովումն էր։ Վալպոյի և Շիկլոշի բերդերը վերցնելուց հետո հանձնվեց Բարանյայի կենտրոն Պեչը։ Քաղաքը դառնալու էր օսմանյան Հունգարիայի ամենաբազմամարդ և ամենաշատ կառուցապատված կենտրոնը, և պատմիչ Իբրահիմ Փեչուլուն իր անունը վերցնելու էր այստեղից։", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Էստերգոնի և Սեկեշֆեհերվարի (Իստոլնի Բելգրադ) նվաճումը", "efca9e05"], "d": ["Կանունիի անձամբ ձեռնարկած հունգարական արշավանքի ժամանակ, երկուսուկես շաբաթ տևած պաշարումից հետո, Հունգարիայի թագավորության կրոնական կենտրոնը և արքեպիսկոպոսական քաղաք Էստերգոնը անցավ օսմանյան կառավարման տակ։ Այնուհետև վերցվեց նաև հունգարական թագավորների թագադրման քաղաք Սեկեշֆեհերվարը, և ամբողջացավ Բուդայի էյալեթի պաշտպանական գոտին։ Էստերգոնը մինչև 1595 թվականը որպես Դանուբի գծի առանցքային բերդ մնալու էր օսմանցիների ձեռքում։", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Բուդայի հյուսիսային և արևմտյան պաշտպանական գոտին. Վաց, Հատվան և Սիմոնտորնյա", "733ee5ce"], "d": ["Էստերգոնը և Սեկեշֆեհերվարը վերցնելուց հետո Բուդայի բեյլերբեյը, մայրաքաղաքը շրջապատող բերդերի օղակը ամբողջացնելու նպատակով, շարժման մեջ մտավ առանց փադիշահի արշավանքի։ Դանուբի ծնկի Վացը, Ալֆյոլդի դուռը՝ Հատվանը, և Շիոյի գծի Սիմոնտորնյան մեկ առ մեկ հանձնումով վերցվեցին։ Այս լուռ տարվա ձեռքբերումները Բուդան սահմանային քաղաքից վերածեցին հարյուր քառասուն տարի դիմանալիք էյալեթի կենտրոնի։", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Բասրայի բռնակցումը և ելքը Պարսից ծոց", "02f87c11"], "d": ["Բաղդադի նվաճման ժամանակ (1534) Բասրայի տիրակալ Ռաշիդ բին Մեղամիսը իր հնազանդությունը հայտնել էր Կանունիին և 1538 թվականին ուղարկել էր քաղաքի բանալիները։ Երբ նրան փոխարինած շեյխ Յահյան դիրք բռնեց օսմանցիների դեմ, Բաղդադի բեյլերբեյ Այաս փաշան ցամաքով, իսկ Մոսուլի սանջակբեյը 120 նավով Եփրատով առաջ շարժվեցին. Այաս փաշան 1545 թվականի դեկտեմբերի 26-ին մտավ Բասրա, և քաղաքը դարձավ բեյլերբեյության կենտրոն։ Շատ ալ-Արաբի գետաբերանի այս նավահանգիստը այն դուռն էր, որով Օսմանյան պետությունը բացվեց դեպի այն ծոցը, որը Պորտուգալիան վերահսկում էր Հորմուզից. 1555 թվականի Ամասիայի պայմանագրով Իրանը ևս ճանաչեց այս վիճակը։", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Սանաայի և Եմենի ներքին շրջանների նվաճումը", "d31ded85"], "d": ["Թաիզից հետո վերցնելով նաև Սանաան՝ ամբողջ երկիրը ենթարկվեց բեյլերբեյությանը։ Սակայն անառիկ աշխարհագրության և դավանական տարբերության պատճառով այս տիրապետությունը երբեք հանգիստ չեղավ. Եմենը Օսմանյան պետության համար դարձավ մշտապես զինվոր կլանող ճակատ։", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Թաիզի նվաճումը", "d4509df9"], "d": ["Եմենում, ուր ինը տարի առաջ բավարարվել էին ափամերձ շերտով, զեյդիական իմամների՝ լեռնային ներքին շրջանում գնալով ուժեղանալու պատճառով Օզդեմիր փաշայի ուժերը բարձրացան բարձրավանդակ և գրավեցին Թաիզը։", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Ստամբուլի պայմանագիրը. հնգամյա հաշտություն Հաբսբուրգների հետ", "41f81773"], "d": ["Օսմանյան պետության և Հաբսբուրգների միջև ստորագրվեց հինգ տարի ժամկետով հաշտություն. Ֆերդինանդը համաձայնեց իր ձեռքում պահած հունգարական հողերի համար տարեկան 30.000 դուկատ վճարել։ Պայմանագիրը իրավականորեն արձանագրեց Հունգարիայի՝ երեք մասի բաժանված փաստացի վիճակը։ Արևմտյան ճակատի այսպիսով ապահովումը Կանունիին հնարավորություն տվեց նոր արշավանքներ կազմակերպել Իրանի դեմ։", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Իրանական երկրորդ արշավանքը և Թավրիզի վերստին վերցնելը", "e82365df"], "d": ["Շահ Թահմասպի դեմ ապստամբած և Ստամբուլ ապաստանած նրա եղբայր Ալկաս Միրզայի դրդմամբ ձեռնարկված արշավանքի ժամանակ բանակը երկրորդ անգամ մտավ Թավրիզ։ Քանի որ Սեֆյանները կրկին խուսափեցին դաշտային ճակատամարտից և հողը այրելով նահանջեցին, քաղաքում հնարավոր եղավ մնալ միայն մի քանի շաբաթ։ Արշավանքը վերջնականապես հաստատեց, որ Թավրիզը հնարավոր չէ ձեռքում պահել, և օսմանյան ռազմավարությունը ուղղեց մնայուն սահմանագիծ ստեղծելու, այսինքն՝ Վանը ամրացնելու կողմը։", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Վանի նվաճումը և արևելյան սահմանի ամրագրումը", "fc8f930b"], "d": ["Թավրիզից վերադառնալիս պաշարված Վանի բերդը, որ բարձրանում էր լճի արևելյան ափի ժայռի վրա, տարածաշրջանի անվիճելի բանալին էր և կարճ պաշարումից հետո հանձնվեց։ Քաղաքն անմիջապես դարձվեց բեյլերբեյության կենտրոն. Արճեշի, Ադիլջևազի և Հաքյարիի սանջակները ենթարկվեցին այստեղ։ Ի տարբերություն Թավրիզի՝ Վանը պահվեց ձեռքում և չորս հարյուր տարի մնաց Օսմանյան պետության արևելքի ամենաառաջավոր մնայուն դիրքը։", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Լահսայի և Կատիֆի բռնակցումը. ծոցի արաբական ափը", "f6701e60"], "d": ["Բասրայի վերցնելուց հետո ծոցի արևմտյան ափին Պորտուգալիայի առաջապահ կետի վերածված Կատիֆը գրավվեց, և ներքին մասի Լահսայի օազիսների հետ հիմնվեց նոր բեյլերբեյություն։ Սա էր Բահրեյնի և Հորմուզի դեմ ուղղված գործողությունների մեկնակետը։ Այսպիսով Օսմանյան պետությունը միաժամանակ խոսքի իրավունք ձեռք բերեց Արաբական թերակղզու և՛ Կարմիր ծովի, և՛ Պարսից ծոցի ափերին։", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Շեհրիզորի ձեռքից դուրս գալը. Արդելանի բեյ Սոհրաբը հակվեց Սեֆյաններին", "5600efc9"], "d": ["Իրաքեյնի արշավանքի ժամանակ (1535) օսմանյան կառավարումը ճանաչած Շեհրիզորի շրջանը գտնվում էր Զալմ բերդում նստող Արդելանի էմիր Բիգե բեյի կառավարման տակ։ 1550 թվականին Բիգե բեյի մահից հետո Զալմ բերդը գրավելով բեյությանը տիրացած նրա եղբայր Սոհրաբը, ուղղվելով դեպի Սեֆյանները, դուրս եկավ Օսմանյան պետությանը հնազանդությունից. այսպիսով Շեհրիզորի շրջանը դուրս եկավ օսմանյան ազդեցությունից։ Շրջանը հնարավոր եղավ հետ վերցնել միայն Նախիջևանի արշավանքի ժամանակ՝ 1554 թվականին, Զալմ բերդի պաշարմամբ և վերցմամբ։", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Արդահանի և Չըլդըրի ավազանի վերցնելը", "14c9eb76"], "d": ["Էրզրումի բեյլերբեյը, Սեֆյանների հետ շարունակվող պատերազմի ընթացքում ուղղվելով վրացի աթաբեկների՝ Կուրի աղեղի հողերին, Արդահանը և Չըլդըրի շրջակայքը ենթարկեց օսմանյան կառավարմանը։ Այսպիսով Կարս-Արդահան գիծը ամբողջացավ, և հյուսիսարևելքում դեպի Վրաստան բացվող բարձրավանդակները վերցվեցին վերահսկողության տակ։ Տարածաշրջանի վերջնական վարչական կարգը ամբողջանալու էր քսանյոթ տարի անց հիմնվելիք Չըլդըրի էյալեթով։", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Սոքոլլու Մեհմեդ փաշան անցավ Դանուբը. տրանսիլվանյան պատերազմի սկիզբը", "38fde931"], "d": ["Տրանսիլվանիայի մանկահասակ թագավոր János Zsigmond-ի (Յանոշ Ժիգմոնդ) խնամակալ վանական Մարտինուցիի առաջացրած խառնաշփոթի և Տրանսիլվանիայի՝ Բանատի բերդերը Ֆերդինանդին թողնելու պատճառով անհրաժեշտ համարվեց նոր արշավանք. հրամանատարությունը տրվեց Ռումելիայի բեյլերբեյ Սոքոլլու Մեհմեդ փաշային։ Բանակը, չնայած Մարտինուցիի՝ ժամանակ ձգելու ջանքերին, անցավ Դանուբը, վերցրեց Բեչեյը, Բեչկերեկը, Չանադը և Լիպպան. սակայն Տեմեշվարի պաշարումը նոյեմբերի 16-ին հանվեց ցրտերի պատճառով։ Այսպիսով Հունգարիայում բացվեց նոր օսմանա-հաբսբուրգյան պատերազմ։", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Լիպովա (Լիպպա) քաղաքն անցավ Կաստալդոյի ավստրիական բանակի ձեռքը. բերդը հանձնվեց դեկտեմբերի 5-ին", "a0e1ff0d"], "d": ["Սոքոլլու Մեհմեդ փաշայի կողմից 1551 թ. հոկտեմբերին գրավված Լիպովան գեներալ Կաստալդոյի բանակը պաշարեց նոյեմբերի 4-ին. երկու օր անց քաղաքն անցավ ավստրիացիների ձեռքը։ Ուլամա փաշան 5.000 հոգանոց կայազորով բերդը պաշտպանեց ևս ինը օր և 1551 թ. դեկտեմբերի 5-ին համաձայնությամբ դուրս եկավ։ Մինչև Թեմեշվարի անկումը 1552 թ. Լիպովան մնաց Հաբսբուրգների ձեռքում։", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Տեմեշվարից ուղարկված ուժերի կողմից Հարավային Բանատի պալանկաների զբաղեցումը. Վերշեց, Հարամ, Կեվե", "edca0921"], "d": ["Տեմեշվարի՝ օսմանյան բանակին հանձնվելուց հետո պաշարող բանակից առանձնացած զորամասերը ուղղվեցին Բանատի փոքր պալանկաների վրա. ըստ Բանլակիի նկարագրության՝ Վերշեցի, Facset, Mehádia, Csákóvár, Հարամվարի և Կեվեի պալանկաները զբաղեցվեցին այդ ուժերի կողմից։ Այսպիսով Դանուբի ափին գտնվող Հարամը ևս անցավ օսմանյան ձեռքը։", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Սոլնոկի նվաճումը և Էգերի պաշարման ձախողումը", "a7156e8f"], "d": ["Տեմեշվարի վերցնելուց հետո միավորված երկու օսմանյան բանակները Թիսա գետի վրա գտնվող Սոլնոկը գրեթե առանց ընդհարման գրավեցին, քանի որ վարձկան կայազորը լքել էր բերդը։ Այնուհետև պաշարված Էգերի բերդը Իշտվան Դոբոյի հրամանատարությամբ երկու հազարանոց կայազորի երեսունութ օր տևած դիմադրության առջև վերցնել հնարավոր չեղավ, և ձմռան վրա հասնելով բանակը հետ քաշվեց։ Այն, որ նույն արշավանքում մի բերդը հեշտությամբ ընկավ, իսկ մյուսը դիմացավ, առաջին բացահայտ նշանն էր, որ Հունգարիայում սահմանն այլևս ինքնաբերաբար առաջ չէր շարժվում հօգուտ Օսմանյան պետության։", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Օսմանա-ֆրանսիական դաշինքը. ֆրանսիական նավատորմի անցումը օսմանյան հրամանատարության ներքո", "a8e01b22"], "d": ["1553 թվականի փետրվարի 1-ի պայմանագրով ֆրանսիական նավատորմը դրվեց օսմանյան նավատորմի հրամանատարության ներքո. նախատեսվեց Իսպանիայի դեմ համատեղ գործողություն Արևմտյան Միջերկրականում։ Պայմանագրից հետո Թուրգութ ռեիսը 1553 թվականի հունիսի 15-ին քառասունհինգ գալերով արշավի դուրս եկավ՝ Ֆրանսիային աջակցելու համար։ Սա առաջին պաշտոնական դաշնակցային պայմանագիրն էր, որը 1536 թվականի կապիտուլյացիաների առևտրական հիմքը վերածեց ռազմական համագործակցության։", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Շահզադե Մուստաֆայի մահապատիժը Կոնիայի Էրեղլիում", "dec36858"], "d": ["Նախիջևանի արշավանքի համար հավաքված բանակին միանալու նպատակով հոր վրանը մտած շահզադե Մուստաֆան, ներկայանալու պահին, դեմ հանդիման դուրս եկավ դահիճների հետ և խեղդամահ արվեց։ Բանակում մեծ սեր վայելող գահաժառանգի թեկնածուի սպանությունը ենիչերիների մեջ խոր զայրույթ առաջացրեց, իսկ Ռուսթեմ փաշան հեռացվեց մեծ վեզիրի պաշտոնից։ Այս դեպքը, որպես շահզադեների նկատմամբ օսմանյան քաղաքականության ամենավիճահարույց բեկումներից մեկը, մտավ գրականություն և ժողովրդական հիշողություն։", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Իբրիմը և Նուբիայի սահմանի տեղափոխումը դեպի հարավ", "c57d5d77"], "d": ["Եգիպտոսի բեյլերբեյության հարավային սահմանը տեղափոխվեց երկրորդ ջրվեժից այն կողմ՝ Նեղոսի վրա ժայռոտ հրվանդանի վրա բարձրացող Իբրիմ բերդը Օզդեմիր բեյի ձեռքով ամրացնելով և Ստորին Նուբիան ամբողջությամբ միացնելով օսմանյան Եգիպտոսին։ (Իբրիմում օսմանյան վարչական կազմակերպությունը ստեղծվել էր Եգիպտոսի նվաճումից հետո. քարտեզի վրա Իբրիմը 1517 թվականից ցուցադրվում է որպես օսմանյան։ Այս տարին մոտավոր է, աղբյուրը տարի չի տալիս։) Բերդը ոչ միայն պատնեշ էր Նուբիայից եկող ասպատակությունների դեմ, այլև Սեննար տանող ոսկու և ստրուկների ճանապարհի վերահսկման կետ։ Այստեղ տեղակայված բոսնիացի պահակազորը այնքան մնայուն եղավ, որ նրանց թոռները երեք հարյուր տարի անց դեռ գտնվում էին բերդում։ Աղբյուրները Իբրիմի՝ օսմանյան կառավարման տակ անցնելու ժամանակի վերաբերյալ երկու տարբեր պատում են տալիս. TDV-ի Սուդանի մասին հոդվածը Ստորին Նուբիայի միացումը օսմանյան Եգիպտոսին կապում է XVI դարի կեսերին Օզդեմիր փաշայի գործողությունների հետ, մինչդեռ Նուբիայի մասին հոդվածը գրում է, որ մինչև Հալֆայի հովիտ ընկած շրջանը և Իբրիմի վարչական կազմակերպությունը ստեղծվել են 1517 թվականի նվաճումից անմիջապես հետո։ Իբրիմի սանջակը 1573 թվականի հուլիսի 26-ին ենթարկվեց Հաբեշի էյալեթին։", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Բեջայայի (Bougie) վերցնելը իսպանացիներից", "49691cda"], "d": ["Քառասուներեք տարի Իսպանիայի ձեռքում գտնվող և Ալժիրի ու Կոնստանտինի միջև ափը երկու մասի բաժանող Բեջայան ցամաքից և ծովից պաշարելուց հետո հանձնվեց։ Բերդի անկումով Ալժիրի օջախի ափը դարձավ անընդմեջ մինչև Օրան։ Իսպանիայում այս կորուստը այնպիսի մեծ վրդովմունք առաջացրեց, որ բերդը հանձնած հրամանատար Ալոնսո դե Պերալտան մահապատժի ենթարկվեց իր հայրենիքում։", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Զեյլայի միացումը Հաբեշի էյալեթին", "7bbf369a"], "d": ["Հաբեշի էյալեթի հարավային ծայրում՝ Ադենի ծոցի աֆրիկյան ափի Զեյլայի նավահանգիստը ենթարկվեց օսմանյան կառավարմանը։ Ադալի սուլթանության՝ դեպի ծով բացվող դուռը եղած այս քաղաքը Բաբ ալ-Մանդեբից դուրս եկող նավերի վերջին մատակարարման կետն էր։ Զեյլայի միացմամբ Օսմանյան պետության սահմանը Աֆրիկայում հասավ իր ամենահարավային կետին։", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Շահզադեների ճակատամարտը Կոնիայում", "1c8de387"], "d": ["Գահի համար պայքարի մեջ մտած շահզադե Բայազիդը մոտ 30.000-անոց ուժով եկավ Կոնիայի մատույցներ և երկու օր տևած ընդհարման մեջ պարտվեց իր եղբայր շահզադե Սելիմին։ Ջախջախված Բայազիդը Ամասիայի վրայով փախավ Իրան և ապաստանեց շահ Թահմասպի մոտ։ Ճակատամարտը Կանունիի վերջին տարիներին գահաժառանգության ճգնաժամը վերածեց արտաքին քաղաքական խնդրի։", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Ջերբայի ծովային հաղթանակը", "c7b905c1"], "d": ["Փիյալե փաշայի հրամանատարությամբ օսմանյան նավատորմը Ջերբայի ափերի մոտ երկու մասի բաժանվելու մանևրով ցրեց Տրիպոլին հետ վերցնելու համար հավաքված իսպանա-ջենովական-մալթայական դաշնակցային նավատորմը։ Դաշնակիցները կորցրին իրենց նավատորմի մեծ մասը, կղզու բերդը ևս շուտով ընկավ։ Ջերբան համարվում է Պրևեզայից հետո Միջերկրական ծովում օսմանյան գերակայությունը ամրապնդած երկրորդ մեծ ծովային հաղթանակը։", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Շահզադե Բայազիդի մահապատիժը Ղազվինում", "a759de14"], "d": ["Իրան ապաստանած շահզադե Բայազիդը երկարատև սակարկությունների արդյունքում շահ Թահմասպի կողմից հանձնվեց օսմանյան պատվիրակությանը և չորս որդիների հետ խեղդամահ արվեց։ Հանձնման դիմաց Սեֆյանները ստացան զգալի նյութական զիջումներ և սահմանային երաշխիքներ։ Այս մահապատժով վերացավ Սելիմ II-ի գահակալման ճանապարհի վերջին խոչընդոտը, և պահպանվեց Ամասիայի պայմանագրի խաղաղ կարգը։", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Քիոսի վերցնելը ջենովացիներից", "a4559b96"], "d": ["Երկու հարյուր տարի որպես Ջենովայի Ջուստինիանի ընտանիքի առևտրական գաղութ կառավարվող և Օսմանյան պետությանը հարկ վճարող Քիոսը, պատճառաբանելով, որ ուշացնում է իր հարկը և նավահանգիստ է տրամադրում թշնամու նավերին, Փիյալե փաշան հանձնումով վերցրեց առանց մեկ գնդակ արձակելու։ Քիոսի և Փսարայի հետ վերացվեց նաև Էգեյան ծովի արևելյան ափի վերջին ջենովական ներկայությունը։ Քիոսցիների մաստիքի արտադրությունն ու արտոնությունները պահպանելով՝ կղզին ենթարկվեց Սպիտակ ծովի կղզիների (Ջեզայիր-ի Բահր-ի Սեֆիդ) էյալեթին։", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Նաքսոսի դքսության բռնակցումը. ամբողջ Կիկլադյան կղզիները", "68f0ec0b"], "d": ["1207 թվականից գոյություն ունեցող և 1537 թվականից Օսմանյան պետությանը հարկ վճարող լատինական Նաքսոսի դքսությունը վերացվեց՝ պատճառաբանելով վերջին դուքս Ջակոմո Կրիսպոյի՝ իր ժողովրդին ճնշելու վերաբերյալ ստացված գանգատները։ Նաքսոսը, Պարոսը, Միլոսը (Դեյիրմենլիք), Անդրոսը, Սիրոսը, Միկոնոսը, Իոսը, Ամորգոսը և շրջակա բոլոր Կիկլադյան կղզիները մեկ որոշմամբ ուղղակիորեն անցան օսմանյան կառավարման տակ։ Կանունին կղզիների կառավարումը որոշ ժամանակ տվեց Յոսեֆ Նասիին. երեքուկես դարի լատինական տիրապետությունը այսպիսով ավարտվեց Էգեյան ծովի կենտրոնում։", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Եմենի ապստամբությունը և Քոջա Սինան փաշայի եմենյան արշավանքը", "c8218d8e"], "d": ["Զեյդիական իմամ Մութահհարը, հարկերի բռնի հավաքումը պատճառաբանելով, ապստամբեց և օսմանյան կառավարումը դուրս մղեց Եմենի մեծ մասից։ Ստամբուլից ուղարկված Քոջա Սինան փաշան 1568-1570 թվականներին իրականացրած գործողություններով, երկար պաշարումից հետո վերցնելով Կաուկաբանը, տարածաշրջանում վերահաստատեց օսմանյան տիրապետությունը։ Արշավանքը կենսական նշանակություն ուներ Կարմիր ծովի հարավային դարպասի և Հնդկական օվկիանոսի առևտրային ճանապարհի վերահսկողությունը պահպանելու տեսանկյունից։", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Պաշտպանական դաշինք Աչեի սուլթանության հետ և օգնությունը Հնդկական օվկիանոսում", "8e835f24"], "d": ["Պորտուգալական հարձակումների առջև Կանունիից օգնություն խնդրած Աչեի դեսպանները, փադիշահի Սիգեթվարում վախճանվելու պատճառով, իրենց հավատարմությունը հայտնեցին Սելիմ II-ին, և նրա հետ ստորագրվեց պաշտպանական պայմանագիր։ Փադիշահը հրամայեց Ալեքսանդրիայից ուղարկել թնդանոթներ, հրացաններ, ռազմամթերք և վարպետներ. հնդկական ջրեր ուղարկելու համար պատրաստվեց տասնյոթ ռազմանավ։ Եմենի ապստամբության ծավալումը խոչընդոտեց նավատորմի ճանապարհ ելնելը, սակայն Աչե հասած օսմանյան հրետանավորներն ու վարպետները տարածաշրջանում մնայուն հետք թողեցին։", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Կիպրոսյան դեսանտը. Լիմասոլի վերցնելը", "9074ccc9"], "d": ["Կղզի իջած օսմանյան բանակը առանց լուրջ դիմադրության գրավեց Լիմասոլը և հաջորդ օրը ուղղվեց դեպի Լառնակա։ Շնորհիվ այն բանի, որ տեղի բնակչությունը գոհ չէր վենետիկյան կառավարումից և օգնում էր օսմանյան ուժերին, Լառնակայում ևս լուրջ դիմադրության չհանդիպեցին. Թուզլայի նավամատույցը դարձվեց զորք և հանդերձանք իջեցնելու հենակետ։ Վենետիկը պաշտպանությունը կենտրոնացրել էր Նիկոսիայում և Ֆամագուստայում. Պաֆոսի կուսակալը հնազանդությունը սերդարին հայտնեց միայն Նիկոսիայի անկումից հետո։", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Նիկոսիայի նվաճումը", "413d866b"], "d": ["1570 թվականի հուլիսի 25-ին սկսված և քառասունհինգ օր տևած պաշարումից հետո Կիպրոսի՝ վենետիկյան կառավարման տակ գտնվող մայրաքաղաք Նիկոսիան հանձնվեց օսմանյան բանակին։ Կղզու կենտրոնի անկումը վենետիկյան դիմադրությունը սեղմեց Ֆամագուստա բերդում։ Նվաճումը Արևմուտքում մեծ արձագանք առաջացրեց և արագացրեց այն գործընթացը, որը Հռոմի պապի առաջնորդությամբ տանում էր Սուրբ Լիգայի նավատորմի ստեղծմանը։", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Կիրենիայի հանձնումը. Կիպրոսի հյուսիսային ափը", "39fdeea5"], "d": ["Նիկոսիայի՝ սեպտեմբերի 9-ին կոտորածով ուղեկցված անկումը կոտրեց Կիպրոսի հյուսիսում եղած դիմադրությունը։ Բեշփարմակ լեռների հետևում գտնվող Կիրենիայի բերդը, իմանալով մայրաքաղաքի ճակատագիրը, ութ օր անց պայմաններով հանձնվեց, և կայազորը ուղարկվեց՝ թույլտվություն ստանալով հեռանալ կղզուց։ Կղզում վենետիկյան դրոշը մնաց միայն Ֆամագուստայում. այն էլ դիմանալու էր ևս տասնմեկ ամիս։", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Նավատորմի վերակառուցումը Լեպանտոյից հետո", "db51fe44"], "d": ["Լեպանտոյի պարտությունից հետո կապուդան փաշա նշանակված Քըլըչ Ալի փաշայի առաջին գործը ծանր կորուստներ կրած նավատորմի վերականգնումն էր. նավաշինարանները 1571-1572 թվականների ամբողջ ձմռանը աշխատեցին անընդմեջ։ 1572 թվականի հունիսին մոտ 250 գալերից և 300 կամավոր ռեիսների գալերներից բաղկացած նոր նավատորմը դուրս եկավ Միջերկրական ծով։ Այս արագ վերականգնումը ցույց տվեց, որ Լեպանտոն չկարողացավ մնայուն կերպով կոտրել օսմանյան ծովային ուժը։", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Ստամբուլի պայմանագիրը Վենետիկի հետ. Կիպրոսի ճանաչումը", "4d08ef50"], "d": ["Սուրբ Լիգայի կազմալուծումից հետո մենակ մնացած Վենետիկը, առանձին հաշտություն կնքելով Օսմանյան պետության հետ, պաշտոնապես ընդունեց, որ Կիպրոսը պատկանում է Օսմանյան պետությանը, և համաձայնեց ռազմատուգանք վճարել։ Պայմանագիրը հստակ ցույց տվեց, որ Լեպանտոյի հաղթանակը քրիստոնեական աշխարհին քաղաքական շահ չէր բերել։ Վենետիկն այնուհետև յոթանասուն տարի խուսափելու էր Օսմանյան պետության հետ ուղղակի պատերազմի մեջ մտնելուց։", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Սելիմ II-ի մահը", "c289f5ee"], "d": ["Սելիմ II-ը ընկնելուց հետո մոտ երկու ամիս չկարողացավ դուրս գալ դիվան և մահացավ։ Նրա մահը տասներկու օր գաղտնի պահվեց պալատում, մինչև Մանիսայում գտնվող ավագ որդին՝ Մուրադը, հասավ Ստամբուլ։ Մահվան օրվա հարցում աղբյուրները տարաձայնում են. Սելանիքին ասում է դեկտեմբերի 15, իսկ Գերլախը, Մեհմեդ բ. Մեհմեդը և Ջենաբին՝ դեկտեմբերի 13։", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Սելիմ II-ի մահվան հայտարարումը և Մուրադ III-ի գահակալումը", "84334d70"], "d": ["Սելիմ II-ի մահը և Մանիսայից բերված Մուրադ III-ի գահակալումը պաշտոնապես հայտարարվեցին 1574 թվականի դեկտեմբերի 22-ին։ Նոր փադիշահը գահին մնալու էր քսանմեկ տարի, իսկ նրա կառավարումը հիշվելու էր Արևելքում՝ իրանական երկարատև պատերազմներով, Արևմուտքում՝ Երկար պատերազմի նախօրեով, իսկ երկրի ներսում՝ ակչեի արժեզրկմամբ։ Մինչև Սոքոլլու Մեհմեդ փաշայի մահը 1579 թվականին՝ պետության կառավարման մեջ շարունակվեց հին կարգը։", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Վադի աս-Սեյլի (Քասր ալ-Քաբիր) ճակատամարտը. օսմանյան աջակցությամբ Աբդ ալ-Մալիքը ոչնչացրեց պորտուգալական բանակը", "21280dac"], "d": ["Օսմանյան աջակցությամբ Մարոկկոյի գահը բարձրացած Աբդ ալ-Մալիքը Վադի աս-Սեյլում ոչնչացրեց Պորտուգալիայի թագավոր Սեբաստիանի մեծ բանակը. քանի որ ճակատամարտում միանգամից երեք տիրակալ մահացավ, արևմտյան աղբյուրներում այն հիշատակվում է որպես «Երեք թագավորների ճակատամարտ»։ Պորտուգալիայի ռազմական ուժը փլուզվեց, և երկիրը կարճ ժամանակ անց անցավ Իսպանիայի ձեռքը։ Աբդ ալ-Մալիքը ևս զոհվեց ճակատամարտում. նրան փոխարինած եղբայրը՝ Ահմեդ ալ-Մանսուրը, հաղթանակի մասին Ստամբուլին տեղեկացրեց պատվիրակությամբ։ Երկու պետությունների հարաբերությունները ոչ թե հարկի կամ վասալության, այլ դեսպանների ու նվերների փոխանակման մակարդակում մնացին և շուտով լարվեցին նվերների հարցի պատճառով։", "0ddf3962"]}
});
